(window.PARENT_DIGEST = window.PARENT_DIGEST || {})[8] = {"grade":8,"subjects":[{"id":"toan","name":"Toán","b":[{"t":"Toán 8, tập 1","c":[{"t":"Chương I. Đa thức","l":[{"t":"Bài 1. Đơn thức","sum":["Đơn thức là biểu thức đại số chỉ gồm một số, hoặc một biến, hoặc có dạng tích của những số và biến.","Khái niệm: Đơn thức là biểu thức đại số chỉ gồm một số, hoặc một biến, hoặc có dạng tích của những số và biến.","Đơn thức thu gọn là đơn thức…: Đơn thức thu gọn là đơn thức chỉ gồm tích của một số với các biến, mà mỗi biến đã được nâng lên luỹ thừa với số mũ nguyên dương (mỗi biến chỉ xuất…","Bậc của đơn thức có hệ số…: Bậc của đơn thức có hệ số khác 0 là tổng số mũ của tất cả các biến có trong đơn thức đó.","Hai đơn thức đồng dạng là hai…: Hai đơn thức đồng dạng là hai đơn thức có hệ số khác 0 và có cùng phần biến.","Để cộng (trừ) các đơn thức đồng…: Để cộng (trừ) các đơn thức đồng dạng, ta cộng (trừ) các hệ số với nhau và giữ nguyên phần biến."],"e":["Hay nhầm: Biểu thức này có phép cộng nên không phải đơn thức.","Hay nhầm: Biểu thức này có phép trừ giữa các biến nên không phải đơn thức.","Hay nhầm: Biểu thức này có phép cộng nên không phải đơn thức.","Hay nhầm: 3 là số mũ của x, không phải hệ số.","Hay nhầm: Hệ số phải kèm dấu âm, nên là −7.","Hay nhầm: Hệ số của đơn thức này là số đứng trước phần biến, tức −7."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 2. Đa thức","sum":["Đa thức là một tổng của những đơn thức. Mỗi đơn thức trong tổng gọi là một hạng tử của đa thức đó.","Đa thức là một tổng của những đơn thức: Mỗi đơn thức trong tổng gọi là một hạng tử của đa thức đó.","Đa thức thu gọn là đa thức…: Đa thức thu gọn là đa thức không có hai hạng tử nào đồng dạng.","Bậc của đa thức là bậc của…: Bậc của đa thức là bậc của hạng tử có bậc cao nhất trong dạng thu gọn của đa thức đó.","Giá trị của đa thức tại những…: Giá trị của đa thức tại những giá trị cho trước của các biến là kết quả nhận được khi thay các giá trị đó vào đa thức rồi thực hiện phép tính."],"e":["Hay nhầm: Biểu thức có biến ở mẫu không phải là tổng của các đơn thức.","Hay nhầm: Biểu thức có căn của biến không phải là đa thức.","Hay nhầm: Biểu thức có biến ở mẫu không phải là tổng của các đơn thức.","Hay nhầm: Chỉ có ba hạng tử: 2x²y, −5xy và 3.","Hay nhầm: Đây là tổng của ba đơn thức.","Hay nhầm: Có hai hạng tử đồng dạng là x²y và 2x²y."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 3. Phép cộng và phép trừ đa thức","sum":["Muốn cộng hai đa thức, ta nối chúng bằng dấu \"+\" rồi bỏ ngoặc, nhóm các hạng tử đồng dạng và thu gọn.","Khái niệm: Muốn cộng hai đa thức, ta nối chúng bằng dấu \"+\" rồi bỏ ngoặc, nhóm các hạng tử đồng dạng và thu gọn.","Muốn trừ đa thức A cho đa…: Muốn trừ đa thức A cho đa thức B, ta viết A − (B), bỏ ngoặc bằng quy tắc dấu (dấu \"−\" đứng trước ngoặc thì đổi dấu mọi hạng tử trong ngoặc), rồi thu…"],"e":["Hay nhầm: Chưa đổi dấu hạng tử −2x và +1.","Hay nhầm: Dấu \"−\" trước ngoặc phải đổi dấu mọi hạng tử.","Hay nhầm: Hạng tử +1 phải đổi thành −1."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 4. Phép nhân đa thức","sum":["Muốn nhân một đơn thức với một đa thức, ta nhân đơn thức với từng hạng tử của đa thức rồi cộng các tích với nhau.","Khái niệm: Muốn nhân một đơn thức với một đa thức, ta nhân đơn thức với từng hạng tử của đa thức rồi cộng các tích với nhau.","Muốn nhân một đa thức với một…: Muốn nhân một đa thức với một đa thức, ta nhân mỗi hạng tử của đa thức này với từng hạng tử của đa thức kia rồi cộng các tích với nhau."],"e":["Hay nhầm: Chưa nhân 3x với hạng tử −2.","Hay nhầm: Phép nhân 3x·x bằng 3x², không phải 3x.","Hay nhầm: Quên hệ số 3 ở hạng tử đầu.","Hay nhầm: Thiếu các tích chéo x·2 và 1·x.","Hay nhầm: Hạng tử tự do phải là 1·2 = 2."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 5. Phép chia đa thức cho đơn thức","sum":["Đơn thức A chia hết cho đơn thức B (B khác 0) khi mỗi biến của B đều là biến của A với số mũ không lớn hơn số mũ của nó trong A.","Khái niệm: Đơn thức A chia hết cho đơn thức B (B khác 0) khi mỗi biến của B đều là biến của A với số mũ không lớn hơn số mũ của nó trong A.","Muốn chia đơn thức A cho đơn…: Muốn chia đơn thức A cho đơn thức B (trường hợp chia hết), ta chia hệ số của A cho hệ số của B, chia luỹ thừa của từng biến trong A cho luỹ thừa của…","Đa thức A chia hết cho đơn…: Đa thức A chia hết cho đơn thức B khi mọi hạng tử của A đều chia hết cho B."],"e":["Hay nhầm: Số mũ của x trong 4x⁴ lớn hơn số mũ của x trong 6x³y².","Hay nhầm: Biến z không có trong đơn thức bị chia.","Hay nhầm: Số mũ của y trong x²y³ lớn hơn số mũ của y trong 6x³y².","Hay nhầm: Hạng tử thứ hai: −4x : 4x = −1 chứ không phải −4.","Hay nhầm: Hạng tử đầu: 8x² : 4x = 2x chứ không phải 2x².","Hay nhầm: Hạng tử đầu: 8x² : 4x = 2x chứ không phải 8x."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương II. Hằng đẳng thức đáng nhớ và ứng dụng","l":[{"t":"Bài 6. Hiệu hai bình phương. Bình phương của một tổng hay một hiệu","m":[{"t":"Tìm giá trị nhỏ nhất, lớn nhất của biểu thức bậc hai","w":"Đề hỏi \"giá trị nhỏ nhất\", \"giá trị lớn nhất\" của biểu thức dạng ax² + bx + c, hoặc \"x bằng bao nhiêu thì biểu thức đạt nhỏ nhất\".","s":["Xem hệ số của x²: dương thì tìm giá trị nhỏ nhất; âm thì đặt dấu trừ ra ngoài để tìm giá trị lớn nhất.","Biến đổi thành dạng (x ± a)² + m bằng hằng đẳng thức (thêm bớt một số cho đủ bình phương).","Dùng (x ± a)² ≥ 0 với mọi x để suy ra biểu thức ≥ m (hoặc ≤ m).","Tìm x để dấu \"=\" xảy ra: x ± a = 0, rồi kết luận giá trị nhỏ nhất (lớn nhất) bằng m tại x đó."],"n":["Luôn nêu rõ dấu \"=\" xảy ra khi nào; không nêu thì chưa kết luận được giá trị nhỏ nhất.","Hệ số của x² khác 1 thì đặt ra ngoài trước: 2x² + 4x = 2(x² + 2x).","(A)² ≥ 0 nên −(A)² ≤ 0; vì vậy biểu thức có dấu trừ trước bình phương chỉ có giá trị lớn nhất."]}],"sum":["Hằng đẳng thức là đẳng thức đúng với mọi giá trị của các biến. Ta có ba hằng đẳng thức đầu tiên:","Khái niệm: Hằng đẳng thức là đẳng thức đúng với mọi giá trị của các biến.","Bình phương của một tổng bằng bình…: Bình phương của một tổng bằng bình phương số thứ nhất, cộng hai lần tích số thứ nhất với số thứ hai, cộng bình phương số thứ hai."],"d":["Tìm giá trị nhỏ nhất, lớn nhất của biểu thức bậc hai"],"e":["Hay nhầm: Vế phải (A − B)² = A² − 2AB + B² là hằng đẳng thức khác.","Hay nhầm: (A + B)² = A² + 2AB + B², không phải hiệu hai bình phương.","Hay nhầm: Không có hằng đẳng thức này.","Hay nhầm: Thiếu hạng tử 2·x·3 = 6x.","Hay nhầm: Hạng tử ở giữa phải là 2·x·3 = 6x.","Hay nhầm: Hạng tử cuối phải là 3² = 9."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 7. Lập phương của một tổng. Lập phương của một hiệu","sum":["Lưu ý: trong khai triển (A + B)³ mọi hạng tử đều mang dấu \"+\"; trong khai triển (A − B)³ các dấu đan xen \"+\", \"−\".","Công thức","Lưu ý: Trong khai triển (A + B)³ mọi hạng tử đều mang dấu \"+\"; trong khai triển (A − B)³ các dấu đan xen \"+\", \"−\"."],"e":["Hay nhầm: Thiếu các hạng tử 3x²·2 và 3x·2².","Hay nhầm: Các hệ số phải là 3·2 = 6 và 3·4 = 12.","Hay nhầm: Đây là khai triển của (x − 2)³.","Hay nhầm: Thiếu các hạng tử −3x² và 3x.","Hay nhầm: Đây là khai triển của (x + 1)³.","Hay nhầm: Dấu của hạng tử 3x phải là \"+\"."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 8. Tổng và hiệu hai lập phương","sum":["Chú ý: A² − AB + B² gọi là bình phương thiếu của hiệu A − B, còn A² + AB + B² gọi là bình phương thiếu của tổng A + B.","Công thức","Chú ý: A² − AB + B² gọi là bình phương thiếu của hiệu A − B, còn A² + AB + B² gọi là bình phương thiếu của tổng A + B."],"e":["Hay nhầm: (A + B)³ có thêm hai hạng tử 3A²B và 3AB².","Hay nhầm: Thừa số thứ hai phải là A² − AB + B².","Hay nhầm: Đây là công thức của hiệu hai lập phương.","Hay nhầm: Dấu của 2x phải là \"+\" với hiệu hai lập phương.","Hay nhầm: Đây là phân tích của x³ + 8.","Hay nhầm: (x − 2)³ = x³ − 6x² + 12x − 8, khác x³ − 8."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 9. Phân tích đa thức thành nhân tử","m":[{"t":"Phân tích đa thức thành nhân tử","w":"Đề yêu cầu \"phân tích thành nhân tử\", \"viết dưới dạng tích\", hoặc là bước đầu của bài rút gọn, tìm x.","s":["Đặt nhân tử chung (cả hệ số và biến) nếu các hạng tử có nhân tử chung.","Nhìn số hạng tử: hai hạng tử → hiệu hai bình phương hoặc tổng, hiệu hai lập phương; ba hạng tử → bình phương của một tổng hoặc một hiệu.","Từ bốn hạng tử trở lên: nhóm các hạng tử để xuất hiện nhân tử chung hoặc hằng đẳng thức.","Kiểm tra bằng cách nhân lại các nhân tử, và dừng khi mỗi nhân tử không phân tích được nữa."],"n":["Luôn đặt nhân tử chung trước rồi mới nghĩ đến hằng đẳng thức.","Khi nhóm, chú ý đổi dấu: −(a − b) = b − a. Hai nhóm phải có nhân tử chung giống hệt nhau.","Kết quả phải là tích; ví dụ x(x − 1) + 2 chưa phải là đã phân tích xong."]},{"t":"Tìm x bằng cách phân tích thành nhân tử","w":"Đề cho phương trình có dạng đa thức bậc hai, bậc ba bằng 0 hoặc \"tìm x biết A·B = 0\".","s":["Chuyển tất cả hạng tử về một vế, vế còn lại bằng 0.","Phân tích vế trái thành tích các nhân tử.","Dùng tính chất: A·B = 0 khi A = 0 hoặc B = 0; giải từng phương trình nhỏ.","Kết luận tất cả giá trị của x, có thể thử lại bằng cách thay vào phương trình ban đầu."],"n":["Không chia hai vế cho một biểu thức chứa x, vì sẽ làm mất nghiệm (ví dụ x² = 4x không được chia cho x).","Một tích bằng 0 khi có ít nhất một thừa số bằng 0, nên mỗi thừa số cho một nghiệm.","Nhân tử lặp lại (như (x − 3)²) chỉ cho một giá trị của x."]}],"sum":["Phân tích đa thức thành nhân tử (hay thừa số) là biến đổi đa thức đó thành một tích của những đa thức.","Khái niệm: Phân tích đa thức thành nhân tử (hay thừa số) là biến đổi đa thức đó thành một tích của những đa thức.","Phương pháp đặt nhân tử chung: Tìm nhân tử chung của các hạng tử, đặt ra ngoài dấu ngoặc.","Phương pháp dùng hằng đẳng thức: Nhận ra dạng A² − B², (A ± B)², A³ ± B³, (A ± B)³ rồi viết thành tích.","Phương pháp nhóm hạng tử: Nhóm các hạng tử thích hợp để xuất hiện nhân tử chung của cả đa thức."],"d":["Phân tích đa thức thành nhân tử","Tìm x bằng cách phân tích thành nhân tử"],"e":["Hay nhầm: Đúng một phần nhưng chưa đặt hết nhân tử chung (còn x).","Hay nhầm: Chưa đặt hết nhân tử chung 2.","Hay nhầm: Nhân lại 2x·4 = 8x, không bằng 4x.","Hay nhầm: (x − 5)² = x² − 10x + 25.","Hay nhầm: (x + 5)² = x² + 10x + 25.","Hay nhầm: x không phải nhân tử chung của x² và 25."],"q":{"n":17,"lv":{"Biết":3,"Hiểu":8,"Vận dụng":6}}}]},{"t":"Chương III. Tứ giác","l":[{"t":"Bài 10. Tứ giác","sum":["Tứ giác ABCD là hình gồm bốn đoạn thẳng AB, BC, CD, DA, trong đó không có hai đoạn thẳng nào nằm trên cùng một đường thẳng.","Khái niệm: Tứ giác ABCD là hình gồm bốn đoạn thẳng AB, BC, CD, DA, trong đó không có hai đoạn thẳng nào nằm trên cùng một đường thẳng.","Tứ giác lồi là tứ giác luôn…: Tứ giác lồi là tứ giác luôn nằm về một phía của đường thẳng chứa bất kì cạnh nào của nó.","Định lí: Tổng các góc của một tứ giác bằng 360°."],"e":["Hay nhầm: Đây là tổng ba góc của một tam giác.","Hay nhầm: Đây không phải tổng các góc của tứ giác.","Hay nhầm: Đây là tổng các góc của ngũ giác.","Hay nhầm: Còn có thêm đường chéo thứ hai.","Hay nhầm: Chỉ có hai cặp đỉnh đối nhau.","Hay nhầm: Chỉ có hai cặp đỉnh đối nhau."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 11. Hình thang cân","sum":["Hình thang là tứ giác có hai cạnh đối song song. Hai cạnh song song gọi là hai đáy, hai cạnh còn lại gọi là hai cạnh bên.","Hình thang là tứ giác có hai cạnh đối song song: Hai cạnh song song gọi là hai đáy, hai cạnh còn lại gọi là hai cạnh bên.","Hình thang cân là hình thang có…: Hình thang cân là hình thang có hai góc kề một đáy bằng nhau.","Trong hình thang cân: Hai cạnh bên bằng nhau; hai đường chéo bằng nhau.","Dấu hiệu nhận biết: Hình thang có hai đường chéo bằng nhau là hình thang cân."],"e":["Hay nhầm: Đây là điều kiện của hình chữ nhật.","Hay nhầm: Đây là dấu hiệu của hình thang cân.","Hay nhầm: Điều này không đúng với mọi hình thang cân.","Hay nhầm: Điều này không đúng với hình thang cân tổng quát."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 12. Hình bình hành","sum":["Hình bình hành là tứ giác có các cặp cạnh đối song song.","Khái niệm: Hình bình hành là tứ giác có các cặp cạnh đối song song.","Tính chất: Trong hình bình hành, các cạnh đối bằng nhau; các góc đối bằng nhau; hai đường chéo cắt nhau tại trung điểm của mỗi đường.","Dấu hiệu nhận biết hình bình hành: Dấu hiệu nhận biết hình bình hành:","1) Tứ giác có các cạnh đối…: 1) Tứ giác có các cạnh đối bằng nhau.","2) Tứ giác có hai cạnh đối…: 2) Tứ giác có hai cạnh đối song song và bằng nhau."],"e":["Hay nhầm: Tính chất này đúng với hình chữ nhật, không đúng với mọi hình bình hành.","Hay nhầm: Đây là điều kiện của hình chữ nhật.","Hay nhầm: Hình thang chỉ cần một cặp cạnh song song.","Hay nhầm: Đây không phải dấu hiệu nhận biết.","Hay nhầm: Hình thoi có bốn cạnh bằng nhau."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 13. Hình chữ nhật","sum":["Hình chữ nhật là tứ giác có bốn góc vuông.","Khái niệm: Hình chữ nhật là tứ giác có bốn góc vuông.","Tính chất: Hình chữ nhật là hình bình hành, nên có mọi tính chất của hình bình hành; ngoài ra hai đường chéo của hình chữ nhật bằng nhau.","Dấu hiệu nhận biết hình chữ nhật: Dấu hiệu nhận biết hình chữ nhật:","1) Tứ giác có ba góc vuông: 1) Tứ giác có ba góc vuông.","2) Hình thang cân có một góc…: 2) Hình thang cân có một góc vuông."],"e":["Hay nhầm: Đây là điều kiện của hình thoi.","Hay nhầm: Đây chỉ là điều kiện của hình thang.","Hay nhầm: Đây là tính chất của hình thoi.","Hay nhầm: Hình thoi có hai đường chéo vuông góc.","Hay nhầm: Hình vuông cần thêm điều kiện bốn cạnh bằng nhau.","Hay nhầm: Hình thang cân không phải hình bình hành."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 14. Hình thoi và hình vuông","sum":["Hình thoi là tứ giác có bốn cạnh bằng nhau. Hình thoi là hình bình hành.","Hình thoi là tứ giác có bốn cạnh bằng nhau: Hình thoi là hình bình hành.","Dấu hiệu nhận biết hình thoi: Dấu hiệu nhận biết hình thoi:","1) Hình bình hành có hai cạnh…: 1) Hình bình hành có hai cạnh kề bằng nhau.","2) Hình bình hành có hai đường…: 2) Hình bình hành có hai đường chéo vuông góc với nhau.","3) Hình bình hành có một đường…: 3) Hình bình hành có một đường chéo là đường phân giác của một góc."],"e":["Hay nhầm: Tính chất này không đúng với mọi hình thoi.","Hay nhầm: Đây chỉ là điều kiện của hình thang.","Hay nhầm: Hai đường chéo của hình thoi nói chung không bằng nhau.","Hay nhầm: Hai đường chéo chia hình thoi thành bốn tam giác vuông bằng nhau."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương IV. Định lí Thalès","l":[{"t":"Bài 15. Định lí Thalès trong tam giác","sum":["Tỉ số của hai đoạn thẳng là tỉ số độ dài của chúng theo cùng một đơn vị đo. Tỉ số của hai đoạn thẳng AB và CD kí hiệu là AB/CD.","Khái niệm: Tỉ số của hai đoạn thẳng là tỉ số độ dài của chúng theo cùng một đơn vị đo.","Định lí Thalès: Nếu một đường thẳng song song với một cạnh của tam giác và cắt hai cạnh còn lại thì nó định ra trên hai cạnh đó những đoạn thẳng tương ứng tỉ lệ.","Định lí Thalès đảo: Nếu một đường thẳng cắt hai cạnh của tam giác và định ra trên hai cạnh đó những đoạn thẳng tương ứng tỉ lệ thì đường thẳng đó song song với cạnh còn…","Hệ quả: Nếu một đường thẳng song song với một cạnh của tam giác và cắt hai cạnh còn lại thì nó tạo thành một tam giác mới có ba cạnh tương ứng tỉ lệ với ba…"],"e":["Hay nhầm: Tỉ số AM/AB phải bằng AN/AC, không phải NC/AC.","Hay nhầm: Tỉ số đúng là AM/AB = MN/BC.","Hay nhầm: Định lí Thalès đảo cho quan hệ song song, không phải vuông góc.","Hay nhầm: Định lí không cho biết độ dài hai đoạn này bằng nhau.","Hay nhầm: Điều này chỉ đúng khi AM = MB.","Hay nhầm: Đây là kết quả của AN · AM : MB, nhầm tỉ số."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 16. Đường trung bình của tam giác","sum":["Đường trung bình của tam giác là đoạn thẳng nối trung điểm hai cạnh của tam giác. Mỗi tam giác có ba đường trung bình.","Khái niệm: Đường trung bình của tam giác là đoạn thẳng nối trung điểm hai cạnh của tam giác.","Định lí: Đường trung bình của tam giác thì song song với cạnh thứ ba và bằng nửa cạnh ấy."],"e":["Hay nhầm: Đường trung bình song song với cạnh thứ ba.","Hay nhầm: Độ dài bằng nửa cạnh thứ ba."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 17. Tính chất đường phân giác của tam giác","sum":["Định lí: trong tam giác, đường phân giác của một góc chia cạnh đối diện thành hai đoạn thẳng tỉ lệ với hai cạnh kề hai đoạn ấy.","Định lí: Trong tam giác, đường phân giác của một góc chia cạnh đối diện thành hai đoạn thẳng tỉ lệ với hai cạnh kề hai đoạn ấy."],"e":["Hay nhầm: Điều này chỉ đúng khi AB = AC.","Hay nhầm: Tỉ số này không đúng với tính chất đường phân giác.","Hay nhầm: Chỉ đúng với tam giác cân tại đỉnh đó.","Hay nhầm: Tỉ lệ với hai cạnh kề của hai đoạn đó."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương V. Dữ liệu và biểu đồ","l":[{"t":"Bài 18. Thu thập và phân loại dữ liệu","sum":["Dữ liệu là các số liệu hoặc thông tin thu được trong quá trình điều tra, khảo sát, đo đạc… Có thể thu thập dữ liệu trực tiếp (quan sát, phỏng vấn, lập phiếu hỏi, làm thí nghiệm) hoặc gián tiếp (từ…","Khái niệm: Dữ liệu là các số liệu hoặc thông tin thu được trong quá trình điều tra, khảo sát, đo đạc… Có thể thu thập dữ liệu trực tiếp (quan sát, phỏng vấn,…","Dữ liệu chia thành hai loại: Dữ liệu định tính (không phải là số, ví dụ màu sắc, tên môn học yêu thích) và dữ liệu định lượng (là số, ví dụ chiều cao, số anh chị em).","Dữ liệu định lượng gồm: Số liệu rời rạc (đếm được, ví dụ số học sinh, số bàn thắng) và số liệu liên tục (thu được từ đo lường, có thể nhận giá trị bất kì trong một khoảng,…","Tính hợp lí của dữ liệu: Dữ liệu cần đúng với đối tượng khảo sát và nằm trong phạm vi hợp lí."],"e":["Hay nhầm: Đây là số đếm nên là dữ liệu định lượng.","Hay nhầm: Cân nặng là số đo nên là dữ liệu định lượng.","Hay nhầm: Điểm là số nên là dữ liệu định lượng.","Hay nhầm: Số bàn thắng là số đếm được (0; 1; 2; …), không nhận mọi giá trị trong một khoảng.","Hay nhầm: Đây là dữ liệu thu được qua quan sát.","Hay nhầm: Chiều cao được biểu diễn bằng số."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 19. Biểu diễn dữ liệu bằng bảng, biểu đồ","sum":["Có thể biểu diễn dữ liệu bằng bảng thống kê hoặc bằng biểu đồ. Tuỳ mục đích mà chọn loại biểu đồ phù hợp.","Khái niệm: Có thể biểu diễn dữ liệu bằng bảng thống kê hoặc bằng biểu đồ.","Biểu đồ cột: So sánh các số liệu của một đại lượng.","Trong biểu đồ hình quạt tròn, cả…: Trong biểu đồ hình quạt tròn, cả hình tròn ứng với 100% hay 360°."],"e":["Hay nhầm: Biểu đồ này biểu diễn tỉ lệ các phần so với toàn thể, không dùng cho sự thay đổi theo thời gian.","Hay nhầm: Biểu đồ này dùng để so sánh hai tập dữ liệu.","Hay nhầm: Không phải là một loại biểu đồ.","Hay nhầm: Biểu đồ này dùng cho sự thay đổi theo thời gian.","Hay nhầm: Biểu đồ này dùng để so sánh hai tập dữ liệu.","Hay nhầm: Đây là bảng, không phải biểu đồ."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 20. Phân tích số liệu thống kê dựa vào biểu đồ","sum":["Từ biểu đồ, ta có thể đọc số liệu, so sánh các giá trị, tính tổng, tính tỉ lệ phần trăm và rút ra nhận xét hay dự đoán xu hướng.","Khái niệm: Từ biểu đồ, ta có thể đọc số liệu, so sánh các giá trị, tính tổng, tính tỉ lệ phần trăm và rút ra nhận xét hay dự đoán xu hướng.","Tỉ lệ phần trăm của một phần so với tổng: (giá trị của phần : tổng) · 100%."],"e":["Hay nhầm: Tháng 1 là tháng thấp (40 triệu đồng).","Hay nhầm: Doanh thu tháng 3 (38 triệu đồng) là thấp nhất.","Hay nhầm: Doanh thu tháng 4 là 55, thấp hơn tháng 5 (60).","Hay nhầm: Tháng 2 tăng từ 40 lên 45.","Hay nhầm: Tháng 4 tăng từ 38 lên 55.","Hay nhầm: Tháng 5 tăng từ 55 lên 60."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]}]},{"t":"Toán 8, tập 2","c":[{"t":"Chương VI. Phân thức đại số","l":[{"t":"Bài 21. Phân thức đại số","m":[{"t":"Tìm điều kiện xác định của phân thức","w":"Đề hỏi \"phân thức xác định khi nào\", \"tìm điều kiện của x\", hoặc \"x không được nhận giá trị nào\".","s":["Điều kiện xác định là mẫu thức khác 0: B ≠ 0.","Phân tích mẫu thành nhân tử (đặt nhân tử chung, hằng đẳng thức, tam thức bậc hai đơn giản).","Cho từng nhân tử khác 0 và giải: mỗi nhân tử cho một giá trị bị loại.","Kết luận: x khác tất cả các giá trị vừa tìm được."],"n":["Điều kiện xác định luôn tìm trên phân thức ban đầu, trước khi rút gọn.","Mẫu là tích bằng 0 khi có ít nhất một nhân tử bằng 0, nên phải loại hết các giá trị đó.","Tử bằng 0 không làm phân thức không xác định; chỉ mẫu bằng 0 mới gây ra điều đó."]}],"sum":["Phân thức đại số (gọi tắt là phân thức) là biểu thức có dạng A/B, trong đó A, B là những đa thức và B khác đa thức 0.","Khái niệm: Phân thức đại số (gọi tắt là phân thức) là biểu thức có dạng A/B, trong đó A, B là những đa thức và B khác đa thức 0.","Mỗi đa thức cũng được coi là…: Mỗi đa thức cũng được coi là một phân thức với mẫu thức bằng 1.","Hai phân thức A/B và C/D gọi là bằng nhau nếu A·D = B·C: Khi đó viết A/B = C/D.","Điều kiện xác định của phân thức…: Điều kiện xác định của phân thức A/B là điều kiện để mẫu thức B khác 0."],"d":["Tìm điều kiện xác định của phân thức"],"e":["Hay nhầm: Mẫu thức phải khác đa thức 0.","Hay nhầm: Tử thức √x không phải đa thức.","Hay nhầm: Mẫu 1/x không phải là đa thức.","Hay nhầm: x + 4 = 0 khi x = −4, không phải x = 4.","Hay nhầm: Mẫu là x + 4 chứ không phải x.","Hay nhầm: Phân thức chỉ không xác định khi x = −4."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 22. Tính chất cơ bản của phân thức đại số","m":[{"t":"Rút gọn phân thức","w":"Đề cho phân thức có tử và mẫu là đa thức và yêu cầu \"rút gọn\", hoặc \"rút gọn rồi tính giá trị\".","s":["Phân tích tử và mẫu thành nhân tử (đặt nhân tử chung, dùng hằng đẳng thức, nhóm hạng tử).","Tìm nhân tử chung của tử và mẫu; chú ý hai nhân tử đối nhau: A − B = −(B − A).","Chia cả tử và mẫu cho nhân tử chung (ước chung lớn nhất của các hệ số và các nhân tử giống nhau).","Viết kết quả gọn nhất. Nếu đề bảo tính giá trị thì thay giá trị của biến vào phân thức đã rút gọn."],"n":["Chỉ được triệt tiêu nhân tử (có dạng tích), không được gạch từng số hạng trong một tổng. Ví dụ (x + 2)/(x + 3) không bằng 2/3.","Nhân tử bị triệt tiêu phải khác 0, nên giá trị của biến không được làm nhân tử đó bằng 0.","Gặp (x − 3) và (3 − x) thì đổi dấu: 3 − x = −(x − 3) rồi mới triệt tiêu."]}],"sum":["Tính chất cơ bản của phân thức: nếu nhân cả tử và mẫu của một phân thức với cùng một đa thức khác 0 thì được một phân thức bằng phân thức đã cho; nếu chia cả tử và mẫu của một phân thức cho một nhân…","Tính chất cơ bản của phân thức: Nếu nhân cả tử và mẫu của một phân thức với cùng một đa thức khác 0 thì được một phân thức bằng phân thức đã cho; nếu chia cả tử và mẫu của một phân…","Rút gọn phân thức là biến đổi…: Rút gọn phân thức là biến đổi phân thức đã cho thành một phân thức bằng nó nhưng đơn giản hơn: phân tích tử và mẫu thành nhân tử rồi chia cả tử và…","Quy đồng mẫu thức nhiều phân thức…: Quy đồng mẫu thức nhiều phân thức là biến đổi các phân thức đã cho thành những phân thức có cùng mẫu thức và lần lượt bằng các phân thức đã cho."],"d":["Rút gọn phân thức"],"e":["Hay nhầm: Cộng thêm cùng một số vào tử và mẫu không giữ nguyên giá trị phân thức.","Hay nhầm: Mẫu thay đổi nhưng tử không đổi.","Hay nhầm: Đã chia sai: 10 : 5 = 2 nên là y/2.","Hay nhầm: Chưa còn nhân tử y ở tử thức.","Hay nhầm: Không phải là bội chung của 2x và 3y theo cách quy đồng.","Hay nhầm: Không liên quan tới mẫu của hai phân thức."],"q":{"n":13,"lv":{"Biết":2,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 23. Phép cộng và phép trừ phân thức đại số","sum":["Muốn cộng (hay trừ) hai phân thức có cùng mẫu thức, ta cộng (hay trừ) các tử thức và giữ nguyên mẫu thức.","Khái niệm: Muốn cộng (hay trừ) hai phân thức có cùng mẫu thức, ta cộng (hay trừ) các tử thức và giữ nguyên mẫu thức.","Muốn cộng (hay trừ) hai phân thức…: Muốn cộng (hay trừ) hai phân thức có mẫu thức khác nhau, ta quy đồng mẫu thức rồi cộng (hay trừ) các phân thức có cùng mẫu thức vừa tìm được.","Phép cộng phân thức có tính chất…: Phép cộng phân thức có tính chất giao hoán và kết hợp; phân thức đối của A/B là −A/B."],"e":["Hay nhầm: Khi cộng hai phân thức cùng mẫu, mẫu được giữ nguyên.","Hay nhầm: Tử bị nhân với nhau thay vì cộng.","Hay nhầm: Đây là sai lầm thường gặp."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 24. Phép nhân và phép chia phân thức đại số","sum":["Muốn nhân hai phân thức, ta nhân các tử thức với nhau và nhân các mẫu thức với nhau.","Khái niệm: Muốn nhân hai phân thức, ta nhân các tử thức với nhau và nhân các mẫu thức với nhau.","Muốn chia phân thức A/B cho phân…: Muốn chia phân thức A/B cho phân thức C/D khác 0, ta nhân A/B với phân thức nghịch đảo của C/D.","Phép nhân phân thức có tính chất…: Phép nhân phân thức có tính chất giao hoán, kết hợp và phân phối đối với phép cộng."],"e":["Hay nhầm: Chưa rút gọn nhân tử chung x.","Hay nhầm: Đây là nhân với phân thức đối."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương VII. Phương trình bậc nhất và hàm số bậc nhất","l":[{"t":"Bài 25. Phương trình bậc nhất một ẩn","m":[{"t":"Giải phương trình đưa về dạng ax + b = 0","w":"Phương trình có ngoặc, có phân số hoặc ẩn x ở cả hai vế.","s":["Bỏ ngoặc (chú ý dấu) và khử mẫu bằng cách nhân hai vế với mẫu số chung nhỏ nhất.","Chuyển các hạng tử chứa x sang một vế, các hằng số sang vế kia (chuyển vế thì đổi dấu).","Thu gọn về dạng ax = −b với a ≠ 0.","Chia hai vế cho a để được x; thay nghiệm vào phương trình ban đầu để kiểm tra."],"n":["Khi nhân hai vế với mẫu chung phải nhân cả các hạng tử không có mẫu.","Dấu trừ trước ngoặc: bỏ ngoặc phải đổi dấu mọi hạng tử bên trong.","Nếu sau khi thu gọn được 0x = b: vô nghiệm khi b ≠ 0, vô số nghiệm khi b = 0."]}],"sum":["Phương trình bậc nhất một ẩn x là phương trình có dạng ax + b = 0, trong đó a và b là hai số đã cho và a ≠ 0.","Khái niệm: Phương trình bậc nhất một ẩn x là phương trình có dạng ax + b = 0, trong đó a và b là hai số đã cho và a ≠ 0.","Quy tắc chuyển vế: Khi chuyển một hạng tử từ vế này sang vế kia của một phương trình, ta phải đổi dấu hạng tử đó.","Phương trình ax + b = 0…: Phương trình ax + b = 0 (a ≠ 0) luôn có một nghiệm duy nhất x = −b/a."],"d":["Giải phương trình đưa về dạng ax + b = 0"],"e":["Hay nhầm: Hệ số của x bằng 0 nên không phải phương trình bậc nhất.","Hay nhầm: Đây là phương trình bậc hai.","Hay nhầm: Ẩn x ở mẫu nên không phải phương trình bậc nhất.","Hay nhầm: Quy tắc không yêu cầu điều này.","Hay nhầm: Chia sai: 3x = 18 chứ không phải 15.","Lưu ý: Khi nhân hai vế với mẫu chung phải nhân cả các hạng tử không có mẫu."],"q":{"n":15,"lv":{"Biết":3,"Hiểu":8,"Vận dụng":4}}},{"t":"Bài 26. Giải bài toán bằng cách lập phương trình","m":[{"t":"Giải bài toán bằng cách lập phương trình","w":"Bài toán có lời văn: tìm số, chuyển động, tuổi, công việc, ... với một đại lượng chưa biết.","s":["Chọn ẩn x (kèm đơn vị) và đặt điều kiện thích hợp cho ẩn.","Biểu diễn các đại lượng còn lại theo x, tìm mối quan hệ \"bằng nhau\" trong đề để lập phương trình.","Giải phương trình vừa lập.","Đối chiếu nghiệm với điều kiện của ẩn rồi trả lời đúng câu hỏi của đề (có đơn vị)."],"n":["Đồng nhất đơn vị trước khi lập phương trình (km với giờ, phút đổi ra giờ).","Chuyển động: quãng đường = vận tốc × thời gian. Hai xe đi ngược chiều gặp nhau: tổng quãng đường hai xe bằng khoảng cách ban đầu.","Nghiệm của phương trình chưa chắc là đáp số: phải kiểm tra điều kiện (số tự nhiên, thời gian dương, tuổi dương, ...)."]}],"sum":["Các bước giải bài toán bằng cách lập phương trình: Bước 1: lập phương trình (chọn ẩn số và đặt điều kiện thích hợp cho ẩn số; biểu diễn các đại lượng chưa biết theo ẩn và các đại lượng đã biết; lập…","Các bước giải bài toán bằng cách lập phương trình: Bước 1: lập phương trình (chọn ẩn số và đặt điều kiện thích hợp cho ẩn số; biểu diễn các đại lượng chưa biết theo ẩn và các đại lượng đã biết; lập…","Công thức chuyển động: Quãng đường = vận tốc × thời gian."],"d":["Giải bài toán bằng cách lập phương trình"],"e":["Hay nhầm: Cần lập phương trình trước.","Hay nhầm: Việc kiểm tra thực hiện sau khi giải.","Hay nhầm: Phương trình bậc nhất chỉ có một nghiệm.","Hay nhầm: Cần kiểm tra để kết luận đúng.","Lưu ý: Đồng nhất đơn vị trước khi lập phương trình (km với giờ, phút đổi ra giờ).","Lưu ý: Chuyển động: quãng đường = vận tốc × thời gian. Hai xe đi ngược chiều gặp nhau: tổng quãng đường hai xe bằng khoảng cách ban đầu."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":5}}},{"t":"Bài 27. Khái niệm hàm số và đồ thị của hàm số","sum":["Nếu đại lượng y phụ thuộc vào đại lượng thay đổi x sao cho với mỗi giá trị của x ta luôn xác định được chỉ một giá trị tương ứng của y thì y được gọi là hàm số của x và x được gọi là biến số.","Khái niệm: Nếu đại lượng y phụ thuộc vào đại lượng thay đổi x sao cho với mỗi giá trị của x ta luôn xác định được chỉ một giá trị tương ứng của y thì y được…","Hàm số có thể được cho bằng…: Hàm số có thể được cho bằng bảng, bằng công thức hoặc bằng biểu đồ.","Đồ thị của hàm số y =…: Đồ thị của hàm số y = f(x) là tập hợp tất cả các điểm biểu diễn các cặp giá trị tương ứng (x; f(x)) trên mặt phẳng toạ độ."],"e":["Hay nhầm: Khi đó y không phải hàm số của x.","Hay nhầm: Đây là điều kiện đảo, không phải định nghĩa.","Hay nhầm: Điểm này nằm trên trục hoành.","Hay nhầm: Điểm này không nằm trên trục toạ độ nào.","Hay nhầm: Điểm này nằm trên trục hoành."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 28. Hàm số bậc nhất và đồ thị của hàm số bậc nhất","sum":["Hàm số bậc nhất là hàm số cho bởi công thức y = ax + b, trong đó a, b là các số cho trước và a ≠ 0.","Khái niệm: Hàm số bậc nhất là hàm số cho bởi công thức y = ax + b, trong đó a, b là các số cho trước và a ≠ 0.","Hàm số y = ax + b xác định với mọi số thực x: Khi a > 0 hàm số đồng biến (x tăng thì y tăng); khi a < 0 hàm số nghịch biến (x tăng thì y giảm).","Đồ thị của hàm số bậc nhất…: Đồ thị của hàm số bậc nhất y = ax + b (a ≠ 0) là một đường thẳng cắt trục tung tại điểm có tung độ bằng b và cắt trục hoành tại điểm có hoành độ…","Cách vẽ đồ thị: Xác định hai điểm phân biệt của đồ thị (thường là giao điểm với hai trục) rồi vẽ đường thẳng đi qua hai điểm đó."],"e":["Hay nhầm: Hệ số a = 0 nên không phải hàm số bậc nhất.","Hay nhầm: Đây không phải đa thức bậc nhất.","Hay nhầm: Đây là hoành độ giao điểm với trục hoành.","Hay nhầm: Đây là tung độ của giao điểm với trục hoành."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 29. Hệ số góc của đường thẳng","sum":["Đường thẳng y = ax + b (a ≠ 0) có hệ số góc là a. Khi a > 0, góc tạo bởi đường thẳng và trục Ox là góc nhọn (hàm số đồng biến); khi a < 0, góc đó là góc tù (hàm số nghịch biến).","Đường thẳng y = ax + b (a ≠ 0) có hệ số góc là a: Khi a > 0, góc tạo bởi đường thẳng và trục Ox là góc nhọn (hàm số đồng biến); khi a < 0, góc đó là góc tù (hàm số nghịch biến).","Hệ số góc của đường thẳng đi…: Hệ số góc của đường thẳng đi qua hai điểm có hoành độ khác nhau A(x₁; y₁), B(x₂; y₂) là a = (y₂ − y₁)/(x₂ − x₁).","Hai đường thẳng y = ax +…: Hai đường thẳng y = ax + b và y = a′x + b′ (a ≠ 0, a′ ≠ 0): song song với nhau khi a = a′ và b ≠ b′; trùng nhau khi a = a′ và b = b′; cắt nhau khi a…"],"e":["Hay nhầm: Hai đường có hệ số góc bằng nhau nên không cắt nhau.","Hay nhầm: Hệ số góc bằng nhau không cho điều này.","Hay nhầm: Đường thẳng vuông góc với Ox không phải đồ thị hàm số."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương VIII. Mở đầu về tính xác suất của biến cố","l":[{"t":"Bài 30. Kết quả có thể và kết quả thuận lợi","sum":["Phép thử ngẫu nhiên là một thí nghiệm hay hành động mà ta không thể đoán trước kết quả của nó, nhưng biết được tập hợp tất cả các kết quả có thể xảy ra.","Khái niệm: Phép thử ngẫu nhiên là một thí nghiệm hay hành động mà ta không thể đoán trước kết quả của nó, nhưng biết được tập hợp tất cả các kết quả có thể xảy…","Tập hợp tất cả các kết quả…: Tập hợp tất cả các kết quả có thể xảy ra của phép thử gọi là không gian mẫu của phép thử.","Kết quả của phép thử làm cho…: Kết quả của phép thử làm cho biến cố xảy ra gọi là kết quả thuận lợi cho biến cố đó."],"e":["Hay nhầm: Mặt ngửa cũng có thể xảy ra.","Hay nhầm: Ta coi đồng xu luôn rơi ở mặt sấp hoặc ngửa.","Hay nhầm: Chỉ những kết quả làm biến cố xảy ra mới thuận lợi."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 31. Cách tính xác suất của biến cố bằng tỉ số","sum":["Trong một phép thử có n kết quả có thể xảy ra, đồng khả năng. Nếu biến cố A có k kết quả thuận lợi thì xác suất của biến cố A là P(A) = k/n.","Trong một phép thử có n kết quả có thể xảy ra, đồng khả năng: Nếu biến cố A có k kết quả thuận lợi thì xác suất của biến cố A là P(A) = k/n.","Xác suất của một biến cố luôn nằm từ 0 đến 1: 0 ≤ P(A) ≤ 1."],"e":["Hay nhầm: Xác suất không vượt quá 1.","Hay nhầm: Chỉ biến cố chắc chắn có xác suất 1.","Hay nhầm: Đây là xác suất của biến cố chắc chắn.","Hay nhầm: Đây là xác suất của biến cố có khả năng xảy ra như không xảy ra.","Hay nhầm: Mọi mặt đều có số chấm không vượt quá 6.","Hay nhầm: Có tất cả 6 kết quả thuận lợi."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 32. Mối liên hệ giữa xác suất thực nghiệm với xác suất và ứng dụng","sum":["Xác suất thực nghiệm của một biến cố là tỉ số giữa số lần biến cố đó xảy ra và tổng số lần thực hiện phép thử.","Khái niệm: Xác suất thực nghiệm của một biến cố là tỉ số giữa số lần biến cố đó xảy ra và tổng số lần thực hiện phép thử.","Khi số lần thực hiện phép thử…: Khi số lần thực hiện phép thử càng lớn thì xác suất thực nghiệm của một biến cố càng gần với xác suất của biến cố đó."],"e":["Hay nhầm: Chưa chia cho tổng số lần thử.","Hay nhầm: Đây là mẫu số của xác suất lí thuyết."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương IX. Tam giác đồng dạng","l":[{"t":"Bài 33. Hai tam giác đồng dạng","sum":["Tam giác A′B′C′ gọi là đồng dạng với tam giác ABC nếu Â′ = Â, B̂′ = B̂, Ĉ′ = Ĉ và A′B′/AB = B′C′/BC = C′A′/CA.","Khái niệm: Tam giác A′B′C′ gọi là đồng dạng với tam giác ABC nếu Â′ = Â, B̂′ = B̂, Ĉ′ = Ĉ và A′B′/AB = B′C′/BC = C′A′/CA.","Tính chất: Mỗi tam giác đồng dạng với chính nó (tỉ số 1); nếu ΔA′B′C′ ∽ ΔABC theo tỉ số k thì ΔABC ∽ ΔA′B′C′ theo tỉ số 1/k; nếu ΔA′B′C′ ∽ ΔABC và ΔABC ∽…","Định lí: Nếu một đường thẳng cắt hai cạnh của tam giác và song song với cạnh còn lại thì nó tạo thành một tam giác mới đồng dạng với tam giác đã cho.","Hai tam giác đồng dạng theo tỉ…: Hai tam giác đồng dạng theo tỉ số k thì tỉ số hai chu vi của chúng cũng bằng k."],"e":["Hay nhầm: Tỉ số đồng dạng luôn dương.","Hay nhầm: Các cạnh tương ứng bằng nhau nên tỉ số là 1.","Hay nhầm: Hai tam giác bằng nhau luôn đồng dạng.","Hay nhầm: Góc tương ứng với A′ là A.","Hay nhầm: Các cạnh chỉ tỉ lệ, chưa chắc bằng nhau."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 34. Ba trường hợp đồng dạng của hai tam giác","sum":["Trường hợp đồng dạng thứ nhất (cạnh – cạnh – cạnh): nếu ba cạnh của tam giác này tỉ lệ với ba cạnh của tam giác kia thì hai tam giác đó đồng dạng.","Trường hợp đồng dạng thứ nhất (cạnh – cạnh – cạnh): Nếu ba cạnh của tam giác này tỉ lệ với ba cạnh của tam giác kia thì hai tam giác đó đồng dạng.","Trường hợp đồng dạng thứ hai (cạnh – góc – cạnh): Nếu hai cạnh của tam giác này tỉ lệ với hai cạnh của tam giác kia và hai góc tạo bởi các cặp cạnh đó bằng nhau thì hai tam giác đồng dạng.","Trường hợp đồng dạng thứ ba (góc – góc): Nếu hai góc của tam giác này lần lượt bằng hai góc của tam giác kia thì hai tam giác đó đồng dạng."],"e":["Hay nhầm: Chưa chắc các cạnh tương ứng bằng nhau.","Hay nhầm: Đây là một trường hợp đồng dạng.","Hay nhầm: Không cần thêm điều kiện.","Hay nhầm: Chỉ đồng dạng, các cạnh chưa chắc bằng nhau.","Hay nhầm: Đây là trường hợp đồng dạng góc – góc.","Hay nhầm: 6/3 = 8/4 = 2 nhưng 9/5 ≠ 2."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 35. Định lí Pythagore và ứng dụng","sum":["Định lí Pythagore: trong một tam giác vuông, bình phương độ dài cạnh huyền bằng tổng các bình phương độ dài hai cạnh góc vuông.","Định lí Pythagore: Trong một tam giác vuông, bình phương độ dài cạnh huyền bằng tổng các bình phương độ dài hai cạnh góc vuông.","Định lí Pythagore đảo: Nếu một tam giác có bình phương của một cạnh bằng tổng các bình phương của hai cạnh còn lại thì tam giác đó là tam giác vuông (vuông tại đỉnh đối…","Ứng dụng: Tính độ dài một cạnh của tam giác vuông khi biết hai cạnh còn lại; kiểm tra một tam giác có phải tam giác vuông hay không; tính đường chéo hình chữ…"],"e":["Hay nhầm: Chỉ đúng với tam giác vuông.","Hay nhầm: Không phải mọi tam giác cân đều có tính chất này.","Hay nhầm: Định lí nói về tam giác vuông.","Hay nhầm: Vì 5² + 12² = 13² nên tam giác có một góc vuông.","Hay nhầm: Vì 5² + 12² = 13² nên tam giác có một góc vuông."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 36. Các trường hợp đồng dạng của hai tam giác vuông","sum":["Dấu hiệu đồng dạng của hai tam giác vuông: (1) nếu hai tam giác vuông có một cặp góc nhọn bằng nhau thì chúng đồng dạng;","Dấu hiệu đồng dạng của hai tam giác vuông: Nếu hai tam giác vuông có một cặp góc nhọn bằng nhau thì chúng đồng dạng","Nếu hai tam giác đồng dạng theo…: Nếu hai tam giác đồng dạng theo tỉ số k thì tỉ số hai đường cao tương ứng bằng k và tỉ số diện tích bằng k².","Ứng dụng: Trong tam giác ABC vuông tại A có đường cao AH thì AB² = BH·BC, AC² = CH·BC và AH·BC = AB·AC."],"e":["Hay nhầm: Chỉ đồng dạng, chưa chắc bằng nhau.","Hay nhầm: Hai góc bằng nhau (góc vuông và góc nhọn) nên đồng dạng g.g.","Hay nhầm: Đó là tỉ số theo thứ tự ngược."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 37. Hình đồng dạng","sum":["Hai hình gọi là đồng dạng nếu hình này là hình phóng to hoặc thu nhỏ của hình kia (hình dạng giống nhau, kích thước có thể khác nhau).","Khái niệm: Hai hình gọi là đồng dạng nếu hình này là hình phóng to hoặc thu nhỏ của hình kia (hình dạng giống nhau, kích thước có thể khác nhau).","Nếu hai hình đồng dạng theo tỉ…: Nếu hai hình đồng dạng theo tỉ số k thì các đoạn thẳng tương ứng tỉ lệ với nhau theo tỉ số k, các góc tương ứng bằng nhau, tỉ số chu vi bằng k và tỉ…","Hình đồng dạng phối cảnh: Nếu với mỗi điểm M của hình thứ nhất, lấy điểm M′ trên đường thẳng OM sao cho OM′/OM = k (k > 0, không đổi) thì tập hợp các điểm M′ là một hình đồng…","Ứng dụng: Đo gián tiếp chiều cao hoặc khoảng cách bằng cách tạo ra hai tam giác đồng dạng;"],"e":["Hay nhầm: Đồng dạng không yêu cầu diện tích bằng nhau.","Hay nhầm: Đồng dạng không yêu cầu chu vi bằng nhau.","Hay nhầm: Hai hình bằng nhau không phóng to.","Hay nhầm: Hai hình bằng nhau luôn đồng dạng."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương X. Một số hình khối trong thực tiễn","l":[{"t":"Bài 38. Hình chóp tam giác đều","sum":["Hình chóp tam giác đều S.ABC có đáy ABC là tam giác đều, ba mặt bên SAB, SBC, SCA là những tam giác cân bằng nhau có chung đỉnh S.","Khái niệm: Hình chóp tam giác đều S.ABC có đáy ABC là tam giác đều, ba mặt bên SAB, SBC, SCA là những tam giác cân bằng nhau có chung đỉnh S.","Chân đường cao H là tâm của đáy: Đường cao kẻ từ đỉnh S của một mặt bên gọi là trung đoạn của hình chóp.","Diện tích xung quanh của hình chóp…: Diện tích xung quanh của hình chóp đều bằng tích của nửa chu vi đáy với trung đoạn: Sxq = p·d (p là nửa chu vi đáy, d là trung đoạn).","Thể tích hình chóp: V = (1/3)·S đáy·h, với h là chiều cao."],"e":["Hay nhầm: Đáy phải là tam giác đều.","Hay nhầm: Đáy hình vuông là của hình chóp tứ giác đều.","Hay nhầm: Không nhất thiết là tam giác đều.","Hay nhầm: Đường cao không rơi vào đỉnh đáy."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 39. Hình chóp tứ giác đều","sum":["Hình chóp tứ giác đều S.ABCD có đáy ABCD là hình vuông, bốn mặt bên SAB, SBC, SCD, SDA là những tam giác cân bằng nhau có chung đỉnh S.","Khái niệm: Hình chóp tứ giác đều S.ABCD có đáy ABCD là hình vuông, bốn mặt bên SAB, SBC, SCD, SDA là những tam giác cân bằng nhau có chung đỉnh S.","Chân đường cao O là tâm của đáy: Diện tích xung quanh: Sxq = p·d (p là nửa chu vi đáy, d là trung đoạn).","Thể tích: V = (1/3)·S đáy·h.","Giữa chiều cao h, trung đoạn d và cạnh đáy a có hệ thức Pythagore: D² = h² + (a/2)²."],"e":["Hay nhầm: Đây là đáy của hình chóp tam giác đều.","Hay nhầm: Đó là số mặt của hình chóp tam giác đều."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương I. Đa thức","l":[{"t":"Bài tập nâng cao · Chương I. Đa thức (13 câu)","q":{"n":13,"lv":{"Nâng cao":13}}}]},{"t":"Chương II. Hằng đẳng thức đáng nhớ và ứng dụng","l":[{"t":"Bài tập nâng cao · Chương II. Hằng đẳng thức đáng nhớ và ứng dụng (12 câu)","e":["Hay nhầm: Dấu của hạng tử giữa phải là +2x với hiệu hai lập phương.","Hay nhầm: Đây là phân tích của x³ + 8.","Hay nhầm: (x − 2)³ = x³ − 6x² + 12x − 8, không phải x³ − 8."],"q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương III. Tứ giác","l":[{"t":"Bài tập nâng cao · Chương III. Tứ giác (13 câu)","q":{"n":13,"lv":{"Nâng cao":13}}}]},{"t":"Chương IV. Định lí Thalès","l":[{"t":"Bài tập nâng cao · Chương IV. Định lí Thalès (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương V. Dữ liệu và biểu đồ","l":[{"t":"Bài tập nâng cao · Chương V. Dữ liệu và biểu đồ (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương VI. Phân thức đại số","l":[{"t":"Bài tập nâng cao · Chương VI. Phân thức đại số (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương VII. Phương trình bậc nhất và hàm số bậc nhất","l":[{"t":"Bài tập nâng cao · Chương VII. Phương trình bậc nhất và hàm số bậc nhất (11 câu)","q":{"n":11,"lv":{"Nâng cao":11}}}]},{"t":"Chương VIII. Mở đầu về tính xác suất của biến cố","l":[{"t":"Bài tập nâng cao · Chương VIII. Mở đầu về tính xác suất của biến cố (7 câu)","q":{"n":7,"lv":{"Nâng cao":7}}}]},{"t":"Chương IX. Tam giác đồng dạng","l":[{"t":"Bài tập nâng cao · Chương IX. Tam giác đồng dạng (11 câu)","q":{"n":11,"lv":{"Nâng cao":11}}}]},{"t":"Chương X. Một số hình khối trong thực tiễn","l":[{"t":"Bài tập nâng cao · Chương X. Một số hình khối trong thực tiễn (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]}]}]},{"id":"ly","name":"Vật lí","b":[{"t":"Vật lí 8","c":[{"t":"Chương III. Khối lượng riêng và áp suất","l":[{"t":"Bài 13. Khối lượng riêng","req":["Nêu được định nghĩa khối lượng riêng; xác định được khối lượng riêng qua khối lượng và thể tích tương ứng.","Liệt kê được một số đơn vị đo khối lượng riêng thường dùng."],"sum":["Khi đo khối lượng và thể tích của các vật làm từ cùng một chất, tỉ số khối lượng trên thể tích luôn như nhau; các chất khác nhau cho tỉ số khác nhau.","Khái niệm: Khi đo khối lượng và thể tích của các vật làm từ cùng một chất, tỉ số khối lượng trên thể tích luôn như nhau; các chất khác nhau cho tỉ số khác nhau.","Khối lượng riêng của một chất cho…: Khối lượng riêng của một chất cho biết khối lượng của một đơn vị thể tích chất đó.","Đơn vị thường dùng: Kg/m³ hoặc g/cm³ (g/mL).","Biết khối lượng riêng và thể tích…: Biết khối lượng riêng và thể tích thì tính được khối lượng m = D · V.","Trọng lượng riêng d của một chất…: Trọng lượng riêng d của một chất là trọng lượng của một mét khối chất đó: d = P / V, đơn vị N/m³."],"e":["Hay nhầm: Ngược lại với khối lượng riêng.","Hay nhầm: Là đơn vị khối lượng riêng.","Hay nhầm: Là đơn vị khối lượng riêng.","Hay nhầm: Là đơn vị khối lượng riêng (1 g/mL = 1 g/cm³).","Hay nhầm: Sắt có khối lượng riêng lớn hơn."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 14. Thực hành xác định khối lượng riêng","req":["Thực hiện thí nghiệm xác định khối lượng riêng của khối hộp chữ nhật, của vật có hình dạng bất kì, của một lượng chất lỏng."],"sum":["Để xác định khối lượng riêng của một chất cần đo khối lượng m và thể tích V của vật làm từ chất đó, rồi tính D = m / V.","Khái niệm: Để xác định khối lượng riêng của một chất cần đo khối lượng m và thể tích V của vật làm từ chất đó, rồi tính D = m / V.","Vật hình hộp chữ nhật: Dùng thước đo ba cạnh a, b, c tính V = a·b·c; dùng cân đo khối lượng m.","Lượng chất lỏng: Đo khối lượng ống đong rỗng m₁, rót nước vào đo thể tích V trên ống đong, đo khối lượng ống đong có nước m₂; khối lượng nước là m₂ − m₁;","Vật rắn có hình dạng bất kì, không thấm nước (như hòn sỏi): Đo khối lượng m bằng cân; thể tích V = V₂ − V₁ với V₁ là thể tích nước ban đầu trong ống đong và V₂ là thể tích khi nhúng chìm vật;","Trong thực tế, người ta đo khối…: Trong thực tế, người ta đo khối lượng riêng của chất lỏng bằng tỉ trọng kế (phù kế), hoạt động dựa trên định luật Archimedes."],"e":["Hay nhầm: Không phải đại lượng cần đo trực tiếp.","Hay nhầm: Đó là diện tích toàn phần."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 15. Áp suất trên một bề mặt","req":["Khẳng định được: áp suất sinh ra khi có áp lực tác dụng lên một diện tích bề mặt; áp suất phụ thuộc áp lực và diện tích bị ép.","Liệt kê được một số đơn vị đo áp suất thông dụng."],"m":[{"t":"Bài toán áp suất trên một bề mặt","w":"Đề cho khối lượng (hoặc trọng lượng), diện tích tiếp xúc và hỏi áp suất, diện tích hoặc áp lực.","s":["Xác định áp lực F: lực ép vuông góc với mặt bị ép. Vật đặt trên mặt ngang thì F = P = 10·m.","Xác định diện tích bị ép S (cộng diện tích tất cả các chỗ tiếp xúc) và đổi về m² (1 m² = 10 000 cm²).","Áp dụng p = F/S; hỏi F hay S thì dùng F = p·S hoặc S = F/p.","Ghi kết quả có đơn vị: p tính bằng Pa (N/m²), rồi so sánh hoặc kết luận theo yêu cầu."],"n":["S là diện tích tiếp xúc thực, không phải diện tích cả vật; đứng hai chân thì S là tổng hai chân.","Cùng áp lực, diện tích bị ép càng nhỏ thì áp suất càng lớn (dao sắc dễ cắt, đinh nhọn dễ đóng).","Phải đổi cm² sang m² trước khi tính, nếu không kết quả sai 10 000 lần."]}],"sum":["Áp lực là lực ép có phương vuông góc với mặt bị ép. Ví dụ: người đứng trên sàn, xe đỗ trên mặt đường tác dụng áp lực lên mặt sàn, mặt đường.","Áp lực là lực ép có phương vuông góc với mặt bị ép: Ví dụ: người đứng trên sàn, xe đỗ trên mặt đường tác dụng áp lực lên mặt sàn, mặt đường.","Thí nghiệm khối sắt đặt lên bột mịn: Áp lực càng lớn, diện tích bị ép càng nhỏ thì độ lún càng lớn.","Áp suất được tính bằng độ lớn…: Áp suất được tính bằng độ lớn áp lực trên một đơn vị diện tích bị ép.","Đơn vị áp suất: Pascal (Pa), 1 Pa = 1 N/m².","Làm tăng áp suất: Tăng áp lực hoặc giảm diện tích bị ép (mũi đinh nhọn, lưỡi dao sắc)."],"d":["Bài toán áp suất trên một bề mặt"],"e":["Hay nhầm: Không phải lúc nào cũng vuông góc.","Hay nhầm: Dao sắc có diện tích nhỏ.","Lưu ý: S là diện tích tiếp xúc thực, không phải diện tích cả vật; đứng hai chân thì S là tổng hai chân.","Lưu ý: Cùng áp lực, diện tích bị ép càng nhỏ thì áp suất càng lớn (dao sắc dễ cắt, đinh nhọn dễ đóng).","Lưu ý: Phải đổi cm² sang m² trước khi tính, nếu không kết quả sai 10 000 lần."],"q":{"n":16,"lv":{"Biết":3,"Hiểu":7,"Vận dụng":6}}},{"t":"Bài 16. Áp suất chất lỏng. Áp suất khí quyển","req":["Khảo sát tác dụng của chất lỏng lên vật đặt trong chất lỏng.","Nêu được áp suất tác dụng vào chất lỏng được chất lỏng truyền đi nguyên vẹn theo mọi hướng.","Chứng tỏ được sự tồn tại của áp suất khí quyển và áp suất này tác dụng theo mọi phương."],"m":[{"t":"Bài toán áp suất chất lỏng","w":"Đề cho độ sâu hoặc chiều cao cột chất lỏng, loại chất lỏng và hỏi áp suất hoặc độ sâu.","s":["Xác định độ sâu h: khoảng cách thẳng đứng từ mặt thoáng đến điểm cần tính, đổi ra mét.","Xác định trọng lượng riêng d của chất lỏng (nước 10 000 N/m³); nếu cho khối lượng riêng D thì d = 10·D.","Áp dụng p = d·h cho áp suất do chất lỏng gây ra; hỏi độ sâu thì h = p/d.","Hỏi áp suất tổng cộng thì cộng thêm áp suất khí quyển ở mặt thoáng; ghi đơn vị Pa."],"n":["h là độ sâu tính từ mặt thoáng đến điểm xét, không phải chiều cao của bình hay khoảng cách đến đáy.","Áp suất chất lỏng chỉ phụ thuộc d và h, không phụ thuộc hình dạng hay dung tích bình.","Hai điểm cùng độ sâu trong cùng một chất lỏng có áp suất bằng nhau."]}],"sum":["Chất lỏng gây áp suất theo mọi phương lên các vật ở trong lòng nó và lên đáy, thành bình. Vật càng ở sâu trong lòng chất lỏng thì chịu áp suất chất lỏng càng lớn.","Khái niệm: Chất lỏng gây áp suất theo mọi phương lên các vật ở trong lòng nó và lên đáy, thành bình.","Định luật Pascal: Áp suất tác dụng vào chất lỏng sẽ được chất lỏng truyền đi nguyên vẹn theo mọi hướng.","Lớp không khí bao quanh Trái Đất…: Lớp không khí bao quanh Trái Đất dày hàng nghìn kilômét gọi là khí quyển.","Chứng minh tồn tại áp suất khí quyển: Úp ngược cốc nước đầy được đậy kín bằng tấm nylon, nước không rơi vì áp suất khí quyển tác dụng lên tấm nylon;","Khi thay đổi áp suất đột ngột…: Khi thay đổi áp suất đột ngột (máy bay cất, hạ cánh; leo núi cao) màng nhĩ bị đẩy về phía nơi có áp suất nhỏ hơn gây ù tai."],"d":["Bài toán áp suất chất lỏng"],"e":["Hay nhầm: Còn thành bình và vật trong lòng.","Hay nhầm: Không phải nguyên nhân chính.","Lưu ý: h là độ sâu tính từ mặt thoáng đến điểm xét, không phải chiều cao của bình hay khoảng cách đến đáy.","Lưu ý: Áp suất chất lỏng chỉ phụ thuộc d và h, không phụ thuộc hình dạng hay dung tích bình.","Lưu ý: Hai điểm cùng độ sâu trong cùng một chất lỏng có áp suất bằng nhau."],"q":{"n":16,"lv":{"Biết":3,"Hiểu":8,"Vận dụng":5}}},{"t":"Bài 17. Lực đẩy Archimedes","req":["Thực hiện thí nghiệm khảo sát tác dụng của chất lỏng lên vật đặt trong chất lỏng; rút ra điều kiện định tính về vật nổi, vật chìm.","Phát biểu và vận dụng được định luật Archimedes."],"m":[{"t":"Bài toán vật nhúng trong chất lỏng (lực đẩy Archimedes)","w":"Đề cho thể tích, khối lượng hoặc số chỉ lực kế của vật nhúng trong nước (hoặc chất lỏng khác) và hỏi lực đẩy, thể tích, số chỉ lực kế.","s":["Đổi về đơn vị chuẩn: thể tích ra m³ (1 cm³ = 0,000001 m³), trọng lượng P = 10·m (m tính bằng kg). Trọng lượng riêng của nước là 10 000 N/m³.","Liệt kê các lực tác dụng lên vật: trọng lượng P (hướng xuống), lực đẩy F_A (hướng lên) và lực kéo của lực kế nếu có.","Xác định trạng thái của vật: lơ lửng hoặc nổi cân bằng thì F_A = P; chìm hoàn toàn thì thể tích chìm bằng thể tích vật.","Áp dụng F_A = d·V (V là phần chìm); khi treo lực kế thì số chỉ F = P − F_A. Đổi kết quả về đơn vị đề hỏi."],"n":["V trong F_A = d·V là thể tích phần vật chìm trong chất lỏng, không phải thể tích cả vật khi vật nổi.","d là trọng lượng riêng của chất lỏng, không phải của vật.","Vật nổi cân bằng thì lực đẩy bằng đúng trọng lượng, dù thể tích vật có lớn hơn."]}],"sum":["Chất lỏng tác dụng lên vật đặt trong nó một lực đẩy có phương thẳng đứng, chiều từ dưới lên, gọi là lực đẩy Archimedes.","Khái niệm: Chất lỏng tác dụng lên vật đặt trong nó một lực đẩy có phương thẳng đứng, chiều từ dưới lên, gọi là lực đẩy Archimedes.","Điều kiện nổi, chìm của một vật…: Điều kiện nổi, chìm của một vật đặc trong chất lỏng (so sánh trọng lượng P với lực đẩy Archimedes F_A): P > F_A thì vật chìm;","Định luật Archimedes: Một vật nhúng trong chất lỏng chịu tác dụng một lực đẩy hướng thẳng đứng từ dưới lên, có độ lớn bằng trọng lượng của phần chất lỏng bị vật chiếm chỗ.","Thí nghiệm bình tràn: Lực đẩy F_A = P − F (P là số chỉ lực kế khi vật ở ngoài không khí, F là số chỉ khi nhúng trong chất lỏng) bằng trọng lượng của nước tràn ra.","Cá có bong bóng khí: Bong bóng phồng lên thì thể tích tăng, lực đẩy tăng nên cá nổi; bong bóng xẹp thì cá chìm."],"d":["Bài toán vật nhúng trong chất lỏng (lực đẩy Archimedes)"],"e":["Hay nhầm: Đó là hướng của trọng lực.","Hay nhầm: Không phụ thuộc trực tiếp.","Hay nhầm: Chỉ khi hai khối lượng riêng bằng nhau.","Lưu ý: V trong F_A = d·V là thể tích phần vật chìm trong chất lỏng, không phải thể tích cả vật khi vật nổi.","Lưu ý: d là trọng lượng riêng của chất lỏng, không phải của vật.","Lưu ý: Vật nổi cân bằng thì lực đẩy bằng đúng trọng lượng, dù thể tích vật có lớn hơn."],"q":{"n":16,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":7}}}]},{"t":"Chương IV. Tác dụng làm quay của lực","l":[{"t":"Bài 18. Tác dụng làm quay của lực. Moment","req":["Thực hiện thí nghiệm mô tả tác dụng làm quay của lực.","Nêu được tác dụng làm quay của lực lên một vật quanh một điểm hoặc một trục được đặc trưng bằng moment lực.","Giải thích được cách dùng cờ lê vặn ốc, cách đạp pê-đan xe đạp."],"sum":["Lực có thể làm một vật quay quanh trục cố định. Khi giá của lực cắt trục quay hoặc song song với trục quay thì lực không làm vật quay; khi giá của lực không song song và không cắt trục quay thì lực…","Lực có thể làm một vật quay quanh trục cố định: Khi giá của lực cắt trục quay hoặc song song với trục quay thì lực không làm vật quay; khi giá của lực không song song và không cắt trục quay thì…","Tác dụng làm quay của lực lên…: Tác dụng làm quay của lực lên một vật quanh một điểm hoặc một trục được đặc trưng bằng moment lực.","Lực càng lớn thì moment lực càng…: Lực càng lớn thì moment lực càng lớn, tác dụng làm quay càng lớn.","Giá của lực càng cách xa trục…: Giá của lực càng cách xa trục quay thì moment lực càng lớn, tác dụng làm quay càng lớn.","Ứng dụng: Cờ lê tay dài vặn ốc dễ hơn;"],"e":["Hay nhầm: Đặc trưng cho tác dụng ép.","Hay nhầm: Còn phụ thuộc giá của lực.","Hay nhầm: Không phải mục đích vật lí.","Hay nhầm: Lực tay có thể không đổi.","Hay nhầm: Khi đó giá lực cắt trục, không làm quay."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 19. Đòn bẩy và ứng dụng","req":["Minh hoạ được đòn bẩy làm thay đổi hướng tác dụng của lực.","Lấy được ví dụ về các loại đòn bẩy trong thực tiễn.","Giải quyết được một số vấn đề thực tiễn bằng kiến thức về đòn bẩy."],"sum":["Đòn bẩy là vật rắn quay quanh một điểm tựa O khi chịu tác dụng lực. Khoảng cách từ giá của lực tác dụng đến điểm tựa gọi là cánh tay đòn.","Khái niệm: Đòn bẩy là vật rắn quay quanh một điểm tựa O khi chịu tác dụng lực.","Đòn bẩy có thể làm thay đổi…: Đòn bẩy có thể làm thay đổi hướng tác dụng của lực (ví dụ ấn xuống một đầu để nâng vật ở đầu kia lên).","Đòn bẩy loại 1: Điểm tựa O nằm trong khoảng giữa điểm đặt của hai lực (bập bênh, kéo cắt, kìm, cân đòn).","Đòn bẩy loại 2: Điểm tựa O nằm ngoài khoảng giữa điểm đặt của hai lực.","Ứng dụng: Máy bơm nước bằng tay, cơ thể người (đầu là đòn bẩy loại 1 với điểm tựa là đốt sống trên cùng; cánh tay là đòn bẩy loại 2 với khớp khuỷu), xe đạp…"],"e":["Hay nhầm: Là đại lượng đặc trưng tác dụng quay.","Hay nhầm: Theo sách, đầu mới là loại 1."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}}]},{"t":"Chương V. Điện","l":[{"t":"Bài 20. Hiện tượng nhiễm điện do cọ xát","req":["Giải thích được sơ lược nguyên nhân một vật cách điện nhiễm điện do cọ xát.","Giải thích được một vài hiện tượng thực tế liên quan đến sự nhiễm điện do cọ xát."],"sum":["Nhiều vật sau khi cọ xát có khả năng hút các vật nhẹ như mẩu giấy vụn; người ta nói chúng bị nhiễm điện (mang điện tích).","Khái niệm: Nhiều vật sau khi cọ xát có khả năng hút các vật nhẹ như mẩu giấy vụn; người ta nói chúng bị nhiễm điện (mang điện tích).","Có hai loại điện tích: Quy ước điện tích trên thanh thuỷ tinh cọ xát với lụa là điện tích dương (+);","Giải thích sơ lược: Nguyên tử gồm hạt nhân mang điện dương và các electron mang điện âm chuyển động xung quanh.","Đũa thuỷ tinh cọ xát vào lụa: Electron từ thuỷ tinh sang lụa, thuỷ tinh nhiễm điện dương, lụa nhiễm điện âm.","Sấm sét là hiện tượng phóng điện…: Sấm sét là hiện tượng phóng điện giữa các đám mây tích điện trái dấu hoặc giữa mây và mặt đất."],"e":["Hay nhầm: Proton nằm trong hạt nhân, không dịch chuyển.","Hay nhầm: Khi đó nhựa mang điện dương.","Hay nhầm: Proton không dịch chuyển.","Hay nhầm: Không phải nguyên nhân chính.","Hay nhầm: A đẩy B nên B cùng dấu với A là dương.","Hay nhầm: B hút C nên C khác dấu B."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 21. Dòng điện, nguồn điện","req":["Nêu được định nghĩa dòng điện là dòng chuyển dời có hướng của các hạt mang điện.","Phân loại được vật dẫn điện, vật không dẫn điện.","Nêu được nguồn điện cung cấp năng lượng điện và liệt kê một số nguồn điện."],"sum":["Dòng điện là dòng chuyển dời có hướng của các hạt mang điện. Ví dụ: nối hai điện nghiệm bằng thanh kim loại, các điện tích dịch chuyển từ điện nghiệm này sang điện nghiệm kia nên có dòng điện qua…","Dòng điện là dòng chuyển dời có hướng của các hạt mang điện: Ví dụ: nối hai điện nghiệm bằng thanh kim loại, các điện tích dịch chuyển từ điện nghiệm này sang điện nghiệm kia nên có dòng điện qua thanh.","Để duy trì dòng điện trong các…: Để duy trì dòng điện trong các thiết bị tiêu thụ điện phải có nguồn điện.","Pin, acquy có hai cực: Cực dương (+) và cực âm (−).","Vật dẫn điện là vật cho dòng…: Vật dẫn điện là vật cho dòng điện chạy qua, thường làm bằng kim loại (đồng, nhôm, sắt...).","Pin Volta (1800) là pin điện đầu tiên: Hai bản kim loại đồng và kẽm nhúng trong dung dịch acid loãng; bản đồng là cực dương, bản kẽm là cực âm."],"e":["Hay nhầm: Không tạo được hiệu điện thế rõ."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 22. Mạch điện đơn giản","req":["Vẽ được sơ đồ mạch điện với các kí hiệu: điện trở, biến trở, chuông điện, ampe kế, vôn kế,...","Mắc được mạch điện đơn giản với pin, công tắc, dây nối, bóng đèn.","Mô tả sơ lược công dụng của cầu chì, rơle, cầu dao tự động, chuông điện."],"sum":["Mạch điện đơn giản gồm nguồn điện, dây nối, công tắc và các thiết bị tiêu thụ điện (bóng đèn, động cơ, quạt,...).","Khái niệm: Mạch điện đơn giản gồm nguồn điện, dây nối, công tắc và các thiết bị tiêu thụ điện (bóng đèn, động cơ, quạt,...).","Để vẽ sơ đồ mạch điện, người ta dùng kí hiệu: Nguồn điện (pin), bóng đèn, công tắc đóng/mở, dây dẫn, điện trở, biến trở, ampe kế (A), vôn kế (V), chuông điện,...","Dòng điện một chiều do pin, acquy…: Dòng điện một chiều do pin, acquy cung cấp có chiều không đổi.","Cầu chì: Có đoạn dây chì nóng chảy ở nhiệt độ thấp, khi dòng điện tăng quá mức dây chì nóng chảy làm mạch hở, bảo vệ thiết bị.","Rơle: Thiết bị đóng, ngắt mạch điện tự động, dùng trong các mạch điều khiển để đóng ngắt dòng điện lớn mà hệ thống điều khiển không trực tiếp can thiệp…"],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 23. Tác dụng của dòng điện","req":["Minh hoạ được các tác dụng cơ bản của dòng điện: nhiệt, phát sáng, hoá học, sinh lí.","Giải thích được vì sao nên dùng đèn LED thay cho đèn sợi đốt."],"sum":["Tác dụng nhiệt: vật dẫn nóng lên khi có dòng điện chạy qua (bàn là, bếp điện, nồi cơm điện, dây tóc bóng đèn, cầu chì).","Tác dụng nhiệt: Vật dẫn nóng lên khi có dòng điện chạy qua (bàn là, bếp điện, nồi cơm điện, dây tóc bóng đèn, cầu chì).","Tác dụng phát sáng: Dòng điện làm đèn phát sáng.","Đèn LED tiết kiệm điện hơn đèn…: Đèn LED tiết kiệm điện hơn đèn sợi đốt vì nhiệt toả ra không đáng kể, tuổi thọ rất lớn (có thể đến 100 000 giờ);","Tác dụng hoá học: Dòng điện chạy qua dung dịch muối copper(II) sulfate làm kim loại đồng tách ra bám vào điện cực nối với cực âm.","Tác dụng sinh lí: Dòng điện đi qua cơ thể có thể làm co giật cơ, ngừng tim, ngạt thở, tê liệt thần kinh; cần dùng điện an toàn."],"e":["Hay nhầm: Đó là tác dụng phát sáng."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 24. Cường độ dòng điện và hiệu điện thế","req":["Nêu được số chỉ của ampe kế là giá trị cường độ dòng điện.","Nêu được khả năng sinh ra dòng điện của pin được đo bằng hiệu điện thế giữa hai cực.","Nêu được đơn vị cường độ dòng điện và hiệu điện thế."],"sum":["Cường độ dòng điện đặc trưng cho mức độ mạnh, yếu của dòng điện; kí hiệu I; đo bằng ampe kế;","Khái niệm: Cường độ dòng điện đặc trưng cho mức độ mạnh, yếu của dòng điện; kí hiệu I;","Số chỉ của ampe kế chính là giá trị cường độ dòng điện: Dòng điện có cường độ càng lớn thì đèn càng sáng.","Ampe kế mắc nối tiếp với dụng…: Ampe kế mắc nối tiếp với dụng cụ cần đo; dòng điện đi vào chốt dương (+) và ra từ chốt âm (−).","Khả năng sinh ra dòng điện của…: Khả năng sinh ra dòng điện của pin, acquy được đo bằng hiệu điện thế (điện áp) giữa hai cực; kí hiệu U;","Pin thường có hiệu điện thế 1,5 V: 4,5 V;"],"e":["Hay nhầm: Là công suất hoặc áp suất.","Hay nhầm: Nhỏ hơn giá trị cần đo, có thể hỏng.","Hay nhầm: Quá lớn, đọc khó chính xác."],"q":{"n":13,"lv":{"Biết":3,"Hiểu":7,"Vận dụng":3}}},{"t":"Bài 25. Thực hành đo cường độ dòng điện và hiệu điện thế","req":["Đo được cường độ dòng điện và hiệu điện thế bằng dụng cụ thực hành.","Vẽ được sơ đồ mạch điện có ampe kế và vôn kế."],"sum":["Đo cường độ dòng điện: mắc ampe kế nối tiếp trong mạch sao cho dòng điện đi vào chốt (+) và ra chốt (−).","Đo cường độ dòng điện: Mắc ampe kế nối tiếp trong mạch sao cho dòng điện đi vào chốt (+) và ra chốt (−).","Đo hiệu điện thế: Nối hai chốt vôn kế vào hai đầu bóng đèn (mắc song song với bóng đèn); chốt (+) về phía dòng điện đi vào, chốt (−) về phía dòng điện đi ra.","Khi dùng pin 3 V thay pin…: Khi dùng pin 3 V thay pin 1,5 V thì hiệu điện thế hai đầu bóng đèn tăng và cường độ dòng điện thường tăng, đèn sáng hơn.","Mắc nối tiếp: Các dụng cụ mắc liên tiếp nhau trong một nhánh.","Trình tự thực hành: Chuẩn bị dụng cụ (pin, đèn, công tắc, ampe kế, vôn kế, dây nối); vẽ sơ đồ; mắc mạch khi công tắc ngắt; kiểm tra rồi đóng công tắc; ghi số liệu; tính…"],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}}]},{"t":"Chương VI. Nhiệt","l":[{"t":"Bài 26. Năng lượng nhiệt và nội năng","req":["Nêu được khái niệm năng lượng nhiệt; khái niệm nội năng.","Nêu được khi vật được làm nóng, các phân tử chuyển động nhanh lên và nội năng của vật tăng."],"sum":["Vật chất được cấu tạo từ các phân tử, nguyên tử; chúng chuyển động hỗn loạn không ngừng và giữa chúng có lực tương tác (và khoảng cách giữa chúng).","Khái niệm: Vật chất được cấu tạo từ các phân tử, nguyên tử; chúng chuyển động hỗn loạn không ngừng và giữa chúng có lực tương tác (và khoảng cách giữa chúng).","Nhiệt độ của vật càng cao thì…: Nhiệt độ của vật càng cao thì các phân tử, nguyên tử chuyển động hỗn loạn càng nhanh.","Năng lượng mà vật có được nhờ…: Năng lượng mà vật có được nhờ chuyển động nhiệt của các phân tử, nguyên tử gọi là năng lượng nhiệt (nhiệt năng).","Nội năng của một vật là tổng…: Nội năng của một vật là tổng động năng và thế năng của các phân tử, nguyên tử cấu tạo nên vật.","Khi một vật được làm nóng, các…: Khi một vật được làm nóng, các phân tử, nguyên tử chuyển động nhanh lên, nội năng của vật tăng."],"e":["Hay nhầm: Phân tử nước chuyển động.","Hay nhầm: Không phải nguyên nhân chính."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 27. Thực hành đo năng lượng nhiệt bằng joulemeter","req":["Đo được năng lượng nhiệt mà vật nhận được khi bị đun nóng.","Tính được năng lượng nhiệt để đun sôi một lượng nước xác định."],"sum":["Dây đốt đặt trong bình nhiệt lượng kế biến năng lượng điện thành năng lượng nhiệt đun nóng nước.","Khái niệm: Dây đốt đặt trong bình nhiệt lượng kế biến năng lượng điện thành năng lượng nhiệt đun nóng nước.","Cách tiến hành: Đổ nước ngập dây đốt và đầu đo nhiệt độ; mắc đúng joulemeter; chọn đại lượng đo là năng lượng; khuấy liên tục;","Nhận xét: Khi nhiệt độ tăng thêm càng nhiều thì năng lượng nhiệt cần cung cấp càng nhiều; với cùng độ tăng nhiệt độ, lượng nước càng nhiều thì cần năng lượng…","Nhiệt lượng là phần nhiệt năng mà…: Nhiệt lượng là phần nhiệt năng mà vật nhận được hay mất đi trong quá trình truyền nhiệt.","Nước sôi ở 100 °C (ở áp suất khí quyển thường): Muốn đun sôi nước từ t₁ thì Q = m·c·(100 − t₁)."],"e":["Hay nhầm: Là nhiệt độ cơ thể người.","Hay nhầm: Không phải nguyên nhân chính."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 28. Sự truyền nhiệt","req":["Lấy được ví dụ về dẫn nhiệt, đối lưu, bức xạ nhiệt và mô tả sơ lược sự truyền năng lượng trong mỗi hiện tượng.","Phân tích được công dụng của vật dẫn nhiệt tốt, vật cách nhiệt tốt.","Mô tả được sự truyền năng lượng trong hiệu ứng nhà kính."],"sum":["Dẫn nhiệt là sự truyền năng lượng trực tiếp từ các nguyên tử, phân tử có động năng lớn hơn sang các nguyên tử, phân tử có động năng nhỏ hơn thông qua va chạm.","Khái niệm: Dẫn nhiệt là sự truyền năng lượng trực tiếp từ các nguyên tử, phân tử có động năng lớn hơn sang các nguyên tử, phân tử có động năng nhỏ hơn thông…","Vật dẫn nhiệt tốt (đồng, nhôm, sắt)…: Vật dẫn nhiệt tốt (đồng, nhôm, sắt) dùng làm nồi, chảo; vật cách nhiệt tốt (không khí, xốp, gỗ, nhựa, bông) dùng làm tay cầm, quần áo giữ ấm, vỏ…","Đối lưu là sự truyền năng lượng…: Đối lưu là sự truyền năng lượng nhờ các dòng chất lưu (chất lỏng, chất khí) di chuyển: phần nóng nở ra, nhẹ đi, đi lên; phần lạnh đi xuống; tạo…","Bức xạ nhiệt là sự truyền năng…: Bức xạ nhiệt là sự truyền năng lượng bằng các tia nhiệt, có thể truyền cả trong chân không (Mặt Trời truyền năng lượng đến Trái Đất bằng bức xạ).","Ruột phích có hai lớp thuỷ tinh…: Ruột phích có hai lớp thuỷ tinh, giữa là chân không (chống dẫn nhiệt, đối lưu), mặt trong tráng bạc (phản xạ tia nhiệt), nút kín (chống đối lưu qua…"],"e":["Hay nhầm: Giữa Mặt Trời và Trái Đất là chân không.","Hay nhầm: Không phải mục đích chính."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 29. Sự nở vì nhiệt","req":["Thực hiện thí nghiệm chứng tỏ các chất khác nhau nở vì nhiệt khác nhau.","Lấy được ví dụ về công dụng và tác hại của sự nở vì nhiệt.","Giải thích được một số hiện tượng đơn giản liên quan đến sự nở vì nhiệt."],"sum":["Các chất rắn nở ra khi nóng lên, co lại khi lạnh đi. Các chất rắn khác nhau nở vì nhiệt khác nhau; ví dụ khi cùng tăng nhiệt độ, nhôm nở nhiều nhất, rồi đồng, sắt nở ít hơn.","Các chất rắn nở ra khi nóng lên, co lại khi lạnh đi: Các chất rắn khác nhau nở vì nhiệt khác nhau; ví dụ khi cùng tăng nhiệt độ, nhôm nở nhiều nhất, rồi đồng, sắt nở ít hơn.","Băng kép gồm hai thanh kim loại…: Băng kép gồm hai thanh kim loại khác nhau ghép chặt; khi nóng, băng kép cong về phía thanh nở vì nhiệt ít hơn.","Chất lỏng nở ra khi nóng lên…: Chất lỏng nở ra khi nóng lên, co lại khi lạnh đi; các chất lỏng khác nhau nở vì nhiệt khác nhau (nhiệt kế dùng sự nở vì nhiệt của thuỷ ngân, rượu).","Nước nở vì nhiệt đặc biệt: Từ 0 °C đến 4 °C nước co lại khi nóng lên; từ 4 °C trở lên nước nở ra.","Chất khí nở ra khi nóng lên…: Chất khí nở ra khi nóng lên, co lại khi lạnh đi; chất khí nở vì nhiệt nhiều hơn chất lỏng, chất lỏng nở nhiều hơn chất rắn; các chất khí khác nhau…"],"e":["Hay nhầm: Nhỏ hơn giá trị lớn nhất.","Hay nhầm: Không phải nguyên nhân chính."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương III. Khối lượng riêng và áp suất","l":[{"t":"Bài tập nâng cao · Chương III. Khối lượng riêng và áp suất (10 câu)","q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương IV. Tác dụng làm quay của lực","l":[{"t":"Bài tập nâng cao · Chương IV. Tác dụng làm quay của lực (4 câu)","e":["Hay nhầm: Cả hai đều có thể làm quay.","Hay nhầm: Không tạo ra mà làm lực lớn hơn."],"q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương V. Điện","l":[{"t":"Bài tập nâng cao · Chương V. Điện (12 câu)","e":["Hay nhầm: Không phải nguyên nhân chung."],"q":{"n":12,"lv":{"Nâng cao":12}}}]},{"t":"Chương VI. Nhiệt","l":[{"t":"Bài tập nâng cao · Chương VI. Nhiệt (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]}]}]},{"id":"hoa","name":"Hoá học","b":[{"t":"Hoá học 8","c":[{"t":"Mở đầu","l":[{"t":"Bài 1. Sử dụng một số hoá chất, thiết bị cơ bản trong phòng thí nghiệm","req":["Nhận biết được một số dụng cụ, hoá chất và nêu được quy tắc sử dụng hoá chất an toàn.","Nhận biết được các thiết bị điện trong môn KHTN 8 và trình bày được cách sử dụng điện an toàn."],"sum":["Hoá chất trong phòng thí nghiệm được đựng trong chai, lọ kín và có dán nhãn ghi tên, công thức hoá học, khối lượng hoặc thể tích, độ tinh khiết, kí hiệu cảnh báo, điều kiện bảo quản.","Khái niệm: Hoá chất trong phòng thí nghiệm được đựng trong chai, lọ kín và có dán nhãn ghi tên, công thức hoá học, khối lượng hoặc thể tích, độ tinh khiết, kí…","Quy tắc an toàn: Không dùng hoá chất đựng trong lọ không nhãn hoặc nhãn mờ; không dùng tay trực tiếp lấy hoá chất; hoá chất thừa không đổ trở lại bình chứa; khi hoá…","Lấy hoá chất rắn dạng bột, hạt…: Lấy hoá chất rắn dạng bột, hạt nhỏ bằng thìa kim loại hoặc thuỷ tinh; dạng hạt to, dây, thanh có thể dùng panh gắp.","Khi đun nóng hoá chất trong ống…: Khi đun nóng hoá chất trong ống nghiệm, dùng kẹp gỗ kẹp ở khoảng 1/3 ống tính từ miệng, miệng ống nghiêng về phía không có người, hơ nóng đều rồi…","Thiết bị điện trong KHTN 8 chỉ dùng điện một chiều: Pin 1,5 V (hai pin cho 3 V, bốn pin cho 6 V), biến áp nguồn (đổi điện xoay chiều 220 V thành điện áp nhỏ), ampe kế đo cường độ dòng điện, vôn kế đo…"],"e":["Hay nhầm: Không ngửi trực tiếp hoá chất vì có thể độc hoặc gây bỏng.","Hay nhầm: Tuyệt đối không nếm hoá chất.","Hay nhầm: Phải đọc nhãn và hiểu cảnh báo trước khi lấy hoá chất.","Hay nhầm: Panh dùng gắp chất rắn dạng hạt to, dây, thanh.","Hay nhầm: Thìa dùng xúc chất rắn dạng bột, hạt nhỏ.","Hay nhầm: Không dùng tay trực tiếp lấy hoá chất."],"q":{"n":8,"lv":{"Biết":2,"Hiểu":4,"Vận dụng":2}}}]},{"t":"Chương I. Phản ứng hoá học","l":[{"t":"Bài 2. Phản ứng hoá học","req":["Nêu được khái niệm, ví dụ và phân biệt được biến đổi vật lí, biến đổi hoá học.","Nêu được khái niệm phản ứng hoá học, chất đầu và sản phẩm.","Chỉ ra được dấu hiệu chứng tỏ có phản ứng hoá học xảy ra."],"sum":["Biến đổi vật lí là biến đổi không tạo thành chất mới (hoà tan, nóng chảy, đông đặc, bay hơi, ngưng tụ,...).","Khái niệm: Biến đổi vật lí là biến đổi không tạo thành chất mới (hoà tan, nóng chảy, đông đặc, bay hơi, ngưng tụ,...).","Quá trình biến đổi chất này thành…: Quá trình biến đổi chất này thành chất khác gọi là phản ứng hoá học.","Trong phản ứng hoá học, liên kết…: Trong phản ứng hoá học, liên kết giữa các nguyên tử trong phân tử chất đầu bị phá vỡ, các nguyên tử sắp xếp lại và hình thành liên kết mới tạo phân…","Dấu hiệu nhận biết có chất mới tạo thành: Thay đổi màu sắc, xuất hiện chất khí, xuất hiện chất kết tủa; toả nhiệt hoặc phát sáng cũng có thể là dấu hiệu có phản ứng.","Phản ứng toả nhiệt giải phóng năng…: Phản ứng toả nhiệt giải phóng năng lượng (dạng nhiệt) ra môi trường (ví dụ đốt cháy cồn, than, xăng)."],"e":["Hay nhầm: Có chất mới (CO₂, hơi nước) tạo thành nên là biến đổi hoá học.","Hay nhầm: Tạo gỉ sắt (chất mới) nên là biến đổi hoá học.","Hay nhầm: Tạo chất mới nên là biến đổi hoá học.","Hay nhầm: Chất phản ứng là chất ban đầu bị biến đổi.","Hay nhầm: Chất xúc tác chỉ làm thay đổi tốc độ phản ứng.","Hay nhầm: Dung môi là chất hoà tan chất tan."],"q":{"n":9,"lv":{"Biết":2,"Hiểu":5,"Vận dụng":2}}},{"t":"Bài 3. Mol và tỉ khối chất khí","req":["Nêu được khái niệm mol, tính được khối lượng mol và chuyển đổi giữa số mol và khối lượng.","Nêu được khái niệm tỉ khối, so sánh chất khí này nặng hay nhẹ hơn chất khí khác.","Nêu được thể tích mol của chất khí ở điều kiện chuẩn (1 bar, 25 °C) và chuyển đổi giữa số mol và thể tích chất khí."],"m":[{"t":"Bài toán tỉ khối chất khí","w":"Đề hỏi khí A nặng hay nhẹ hơn khí B bao nhiêu lần, hoặc cho tỉ khối để tìm khối lượng mol.","s":["Xác định khối lượng mol M của các khí từ công thức (hoặc từ đề bài).","Dùng d(A/B) = M(A)/M(B); với không khí dùng d(A/kk) = M(A)/29.","Thay số và tính; d > 1 thì A nặng hơn B, d < 1 thì A nhẹ hơn B.","Tìm ngược: M(A) = d(A/B) × M(B)."],"n":["Tỉ khối không có đơn vị.","Khí được so sánh (đứng trước chữ \"đối với/so với\") nằm ở tử số; khí làm chuẩn nằm ở mẫu số.","Khối lượng mol trung bình của không khí lấy là 29 g/mol."]}],"sum":["Mol là lượng chất có chứa N_A = 6,022·10²³ nguyên tử hoặc phân tử của chất đó. Số 6,022·10²³ gọi là số Avogadro.","Khái niệm: Mol là lượng chất có chứa N_A = 6,022·10²³ nguyên tử hoặc phân tử của chất đó.","Khối lượng mol (M) của một chất…: Khối lượng mol (M) của một chất là khối lượng của N_A nguyên tử hoặc phân tử chất đó tính theo gam;","Thể tích mol của chất khí là…: Thể tích mol của chất khí là thể tích chiếm bởi N_A phân tử khí.","Tỉ khối của khí A đối với khí B là tỉ lệ khối lượng mol: D(A/B) = M_A / M_B."],"d":["Bài toán tỉ khối chất khí"],"e":["Hay nhầm: Sai số mũ, số Avogadro là 6,022·10²³.","Hay nhầm: Đó là khối lượng 1 nguyên tử carbon theo amu.","Hay nhầm: Đó là thể tích mol khí ở điều kiện chuẩn (lít).","Hay nhầm: Đó chỉ là khối lượng mol của nguyên tử oxygen.","Hay nhầm: Tính sai: H₂O có 2 nguyên tử H.","Hay nhầm: Đó là thể tích mol ở 0 °C, 1 atm, không phải điều kiện chuẩn ở đây."],"q":{"n":16,"lv":{"Biết":3,"Hiểu":8,"Vận dụng":5}}},{"t":"Bài 4. Dung dịch và nồng độ","req":["Nêu được dung dịch là hỗn hợp lỏng đồng nhất của các chất đã tan trong nhau.","Nêu được định nghĩa và tính được độ tan, nồng độ phần trăm, nồng độ mol.","Pha được dung dịch theo một nồng độ cho trước."],"sum":["Dung dịch là hỗn hợp đồng nhất của chất tan và dung môi (thường là nước). Ở nhiệt độ, áp suất nhất định, dung dịch còn hoà tan thêm được chất tan là dung dịch chưa bão hoà; không hoà tan thêm được…","Khái niệm: Dung dịch là hỗn hợp đồng nhất của chất tan và dung môi (thường là nước).","Độ tan của một chất trong nước…: Độ tan của một chất trong nước là số gam chất đó hoà tan trong 100 g nước để tạo dung dịch bão hoà ở nhiệt độ, áp suất xác định.","Độ tan của đa số chất rắn tăng khi nhiệt độ tăng: Độ tan của chất khí thường giảm khi nhiệt độ tăng hoặc áp suất giảm.","Nồng độ phần trăm C% cho biết…: Nồng độ phần trăm C% cho biết số gam chất tan có trong 100 g dung dịch.","Nồng độ mol C_M cho biết số…: Nồng độ mol C_M cho biết số mol chất tan có trong 1 lít dung dịch."],"e":["Hay nhầm: Đó là huyền phù hoặc nhũ tương.","Hay nhầm: Dung dịch cần chất tan đã tan.","Hay nhầm: Đó là dung dịch chưa bão hoà.","Hay nhầm: Bão hoà là đã hoà tan tối đa.","Hay nhầm: Đó là cách tính nồng độ phần trăm.","Hay nhầm: Đó là cách tính nồng độ mol."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 5. Định luật bảo toàn khối lượng và phương trình hoá học","req":["Phát biểu được định luật bảo toàn khối lượng.","Nêu được khái niệm phương trình hoá học và các bước lập phương trình hoá học.","Trình bày được ý nghĩa của phương trình hoá học."],"m":[{"t":"Cân bằng phương trình hóa học","w":"Đề cho sơ đồ phản ứng chưa cân bằng và yêu cầu đặt hệ số, hoặc hỏi một hệ số, tổng hệ số.","s":["Viết sơ đồ phản ứng với công thức đúng của các chất tham gia và sản phẩm (không được sửa chỉ số).","Đếm số nguyên tử của từng nguyên tố ở hai vế; chọn nguyên tố chưa bằng nhau, thường bắt đầu từ nguyên tố xuất hiện ít nhất rồi để O và H cuối cùng.","Đặt hệ số (số nguyên dương) trước công thức: hệ số nhân với chỉ số cho số nguyên tử. Lặp lại cho đến khi mọi nguyên tố cân bằng; gặp hệ số phân số thì nhân tất cả với…","Kiểm tra lại từng nguyên tố ở hai vế và viết điều kiện phản ứng (nếu có)."],"n":["Chỉ được thêm hệ số trước công thức, không được thay đổi chỉ số bên trong công thức.","Hệ số 1 không cần viết; hệ số cuối cùng phải là số nguyên tối giản.","Nhóm nguyên tử giữ nguyên ở hai vế (OH, SO₄, NO₃) thì cân bằng như một nhóm."]}],"sum":["Định luật bảo toàn khối lượng: trong một phản ứng hoá học, tổng khối lượng của các chất sản phẩm bằng tổng khối lượng của các chất tham gia phản ứng.","Định luật bảo toàn khối lượng: Trong một phản ứng hoá học, tổng khối lượng của các chất sản phẩm bằng tổng khối lượng của các chất tham gia phản ứng.","Với phản ứng A + B → C + D: m_A + m_B = m_C + m_D: Biết khối lượng của (n − 1) chất trong n chất thì tính được khối lượng chất còn lại.","Phương trình hoá học biểu diễn ngắn…: Phương trình hoá học biểu diễn ngắn gọn phản ứng hoá học bằng công thức hoá học, với hệ số thích hợp để số nguyên tử mỗi nguyên tố ở hai vế bằng nhau.","Ba bước lập phương trình hoá học: Viết sơ đồ phản ứng","Ví dụ: 4Al + 3O₂ → 2Al₂O₃."],"d":["Cân bằng phương trình hóa học"],"e":["Hay nhầm: Khối lượng được bảo toàn.","Hay nhầm: Khối lượng được bảo toàn.","Hay nhầm: Đúng với mọi phản ứng hoá học.","Hay nhầm: Nguyên tử không bị phân chia trong phản ứng hoá học.","Hay nhầm: Không có nguyên tử mới sinh ra.","Hay nhầm: Làm vậy sẽ thành chất khác."],"q":{"n":15,"lv":{"Biết":3,"Hiểu":8,"Vận dụng":4}}},{"t":"Bài 6. Tính theo phương trình hoá học","req":["Tính được lượng chất trong phương trình hoá học theo số mol, khối lượng hoặc thể tích ở điều kiện 25 °C, 1 bar.","Nêu được khái niệm hiệu suất phản ứng và tính được hiệu suất."],"m":[{"t":"Bài toán hiệu suất phản ứng","w":"Đề cho khối lượng chất ban đầu và lượng sản phẩm thực tế, hoặc cho hiệu suất để tính lượng sản phẩm hay lượng chất cần dùng.","s":["Viết phương trình hóa học và cân bằng.","Tính lượng sản phẩm (hoặc chất cần dùng) theo lí thuyết, coi phản ứng xảy ra hoàn toàn: đổi ra mol rồi suy theo tỉ lệ hệ số.","Dùng H = (lượng thực tế / lượng lí thuyết) · 100%.","Biến đổi theo yêu cầu: lượng sản phẩm thực tế = lí thuyết × H/100; lượng chất cần dùng = lí thuyết × 100/H."],"n":["Hiệu suất H luôn nhỏ hơn hoặc bằng 100%.","Lượng thực tế và lượng lí thuyết phải cùng loại và cùng đơn vị (cùng khối lượng hoặc cùng số mol).","Muốn thu đủ lượng sản phẩm với H < 100% thì phải lấy nhiều chất ban đầu hơn so với lí thuyết."]}],"sum":["Tỉ lệ số mol các chất trong phản ứng bằng tỉ lệ hệ số trong phương trình hoá học. Ví dụ Fe + 2HCl → FeCl₂ + H₂: 1 mol Fe phản ứng tạo 1 mol H₂.","Khái niệm: Tỉ lệ số mol các chất trong phản ứng bằng tỉ lệ hệ số trong phương trình hoá học.","Các bước tính theo phương trình hoá học: Viết và cân bằng phương trình","Ví dụ: Zn + 2HCl → ZnCl₂ + H₂.","Hiệu suất phản ứng cho biết mức độ phản ứng xảy ra: H = (lượng sản phẩm thực tế / lượng sản phẩm theo lí thuyết) · 100%."],"d":["Bài toán hiệu suất phản ứng"],"e":["Hay nhầm: Chỉ đúng khi hệ số bằng nhau.","Hay nhầm: Phải sau khi có phương trình.","Hay nhầm: Không thể thu nhiều hơn lí thuyết.","Hay nhầm: Đó là ở điều kiện tiêu chuẩn (0 °C, 1 atm).","Hay nhầm: Là tích, không phải tổng.","Hay nhầm: Lấy nhầm nhân với hiệu suất."],"q":{"n":16,"lv":{"Biết":3,"Hiểu":8,"Vận dụng":5}}},{"t":"Bài 7. Tốc độ phản ứng và chất xúc tác","req":["Nêu được khái niệm tốc độ phản ứng (mức độ nhanh hay chậm của phản ứng hoá học).","Trình bày được một số yếu tố ảnh hưởng đến tốc độ phản ứng và nêu được ứng dụng thực tế.","Nêu được khái niệm chất xúc tác."],"sum":["Tốc độ phản ứng là đại lượng đặc trưng cho sự nhanh, chậm của phản ứng hoá học. Phản ứng đốt cháy xảy ra rất nhanh, phản ứng sắt bị gỉ xảy ra chậm hơn nhiều.","Khái niệm: Tốc độ phản ứng là đại lượng đặc trưng cho sự nhanh, chậm của phản ứng hoá học.","Để so sánh tốc độ phản ứng…: Để so sánh tốc độ phản ứng có thể đo sự thay đổi thể tích chất khí, khối lượng chất rắn hoặc nồng độ chất tan trong một khoảng thời gian; với phản…","Các yếu tố ảnh hưởng đến tốc độ phản ứng: Nồng độ (nồng độ chất phản ứng càng lớn, phản ứng càng nhanh); nhiệt độ (nhiệt độ cao, phản ứng nhanh); diện tích bề mặt tiếp xúc (chất rắn nghiền…","Chất xúc tác là chất làm tăng…: Chất xúc tác là chất làm tăng tốc độ phản ứng nhưng sau phản ứng vẫn giữ nguyên khối lượng và tính chất hoá học.","Ứng dụng: Đập nhỏ đá vôi để nung nhanh hơn; bảo quản thực phẩm trong tủ lạnh để làm chậm phản ứng ôi thiu; dùng chất xúc tác trong sản xuất hoá chất và trong…"],"e":["Hay nhầm: Tăng diện tích tiếp xúc nên tăng tốc độ.","Hay nhầm: Chất xúc tác không bị tiêu hao."],"q":{"n":10,"lv":{"Biết":3,"Hiểu":5,"Vận dụng":2}}}]},{"t":"Chương II. Một số hợp chất thông dụng","l":[{"t":"Bài 8. Acid","req":["Nêu được khái niệm acid (tạo ra ion H⁺).","Tiến hành được thí nghiệm của hydrochloric acid (đổi màu chất chỉ thị, phản ứng với kim loại) và viết phương trình hoá học.","Trình bày được ứng dụng của một số acid thông dụng (HCl, H₂SO₄, CH₃COOH)."],"sum":["Acid là những hợp chất trong phân tử có nguyên tử hydrogen liên kết với gốc acid. Khi tan trong nước, acid tạo ra ion H⁺.","Khái niệm: Acid là những hợp chất trong phân tử có nguyên tử hydrogen liên kết với gốc acid.","Dung dịch acid làm giấy quỳ tím…: Dung dịch acid làm giấy quỳ tím chuyển sang màu đỏ.","Dung dịch acid phản ứng với một…: Dung dịch acid phản ứng với một số kim loại (Mg, Zn, Fe,...) tạo muối và giải phóng khí hydrogen.","Sulfuric acid H₂SO₄ là chất lỏng sánh…: Sulfuric acid H₂SO₄ là chất lỏng sánh như dầu ăn, nặng gần gấp hai lần nước, tan vô hạn trong nước và toả rất nhiều nhiệt; tuyệt đối không tự ý pha…","Hydrochloric acid HCl là chất lỏng không…: Hydrochloric acid HCl là chất lỏng không màu, dùng tẩy gỉ thép, tổng hợp chất hữu cơ, xử lí pH nước bể bơi."],"e":["Hay nhầm: Không đặc trưng cho acid.","Hay nhầm: Chỉ có ở acid HCl, không phải đặc trưng của mọi acid.","Hay nhầm: Quỳ tím chuyển xanh trong dung dịch base.","Hay nhầm: Zn phản ứng với HCl giải phóng H₂.","Hay nhầm: Chia đôi thay vì nhân đôi."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 9. Base. Thang pH","req":["Nêu được khái niệm base (tạo ra ion OH⁻), kiềm là các hydroxide tan tốt trong nước.","Tiến hành được thí nghiệm base đổi màu chất chỉ thị, phản ứng với acid tạo muối.","Nêu được thang pH, dùng pH để đánh giá độ acid – base; đo pH bằng giấy pH."],"m":[{"t":"Nhận biết các chất","w":"Đề cho vài lọ mất nhãn (dung dịch hoặc khí) và hỏi dùng thuốc thử nào, hiện tượng gì để phân biệt.","s":["Nêu tính chất đặc trưng của từng chất cần nhận biết (acid làm quỳ tím hóa đỏ, base làm quỳ tím hóa xanh và phenolphthalein hóa hồng, muối trung tính không đổi màu).","Chọn thuốc thử đơn giản gây hiện tượng khác nhau với các chất (quỳ tím, phenolphthalein, nước vôi trong, dung dịch muối...).","Lấy mỗi lọ một ít làm mẫu thử, đánh số; nhỏ thuốc thử lần lượt vào từng mẫu và quan sát hiện tượng.","Dựa vào hiện tượng để kết luận chất nào ở mẫu nào; viết phương trình hóa học nếu có phản ứng."],"n":["Chỉ lấy một phần mẫu thử ra để thử, không đổ thuốc thử trực tiếp vào lọ gốc.","Chọn thuốc thử dùng được cho nhiều chất cùng lúc để làm ít bước nhất.","Hiện tượng phải rõ ràng và khác nhau: đổi màu, có kết tủa, có khí thoát ra, tan hoặc không tan."]}],"sum":["Base là những hợp chất trong phân tử có nguyên tử kim loại liên kết với nhóm hydroxide (−OH).","Khái niệm: Base là những hợp chất trong phân tử có nguyên tử kim loại liên kết với nhóm hydroxide (−OH).","Phần lớn base không tan trong nước: Một số ít base tan trong nước tạo dung dịch kiềm như NaOH, KOH, Ba(OH)₂, Ca(OH)₂ (ít tan).","Dung dịch kiềm làm giấy quỳ tím…: Dung dịch kiềm làm giấy quỳ tím chuyển sang màu xanh, làm dung dịch phenolphthalein không màu chuyển sang màu hồng.","Base phản ứng với acid tạo muối và nước: Đó là phản ứng trung hoà.","Thang pH có giá trị từ 1 đến 14: PH < 7 là môi trường acid; pH = 7 là trung tính; pH > 7 là môi trường base (kiềm). pH càng nhỏ acid càng mạnh, pH càng lớn base càng mạnh."],"d":["Nhận biết các chất"],"e":["Hay nhầm: Quỳ tím gặp base mới xanh.","Hay nhầm: Có oxygen và toả nhiệt, phát sáng.","Hay nhầm: Nhân nhầm 0,5 × 200 và bỏ chia.","Hay nhầm: HCl là acid nên làm quỳ tím hóa đỏ.","Hay nhầm: NaOH là base nên làm quỳ tím hóa xanh.","Hay nhầm: Chỉ có NaCl không làm đổi màu quỳ tím; hai dung dịch còn lại làm đổi màu."],"q":{"n":14,"lv":{"Biết":3,"Hiểu":7,"Vận dụng":4}}},{"t":"Bài 10. Oxide","req":["Nêu được khái niệm oxide và phân loại oxide theo khả năng phản ứng với acid/base.","Viết được phương trình tạo oxide từ kim loại/phi kim với oxygen.","Nêu và giải thích được tính chất hoá học của oxide base, oxide acid."],"sum":["Oxide là hợp chất của hai nguyên tố, trong đó có một nguyên tố là oxygen. Theo thành phần có oxide kim loại (CaO, Fe₂O₃,...) và oxide phi kim (CO₂, SO₂, P₂O₅,...).","Khái niệm: Oxide là hợp chất của hai nguyên tố, trong đó có một nguyên tố là oxygen.","Oxide tạo từ phản ứng của kim loại hoặc phi kim với oxygen: 2Mg + O₂ → 2MgO;","Tên oxide: Nguyên tố có một hoá trị: tên nguyên tố + oxide (Na₂O: sodium oxide); nhiều hoá trị: ghi hoá trị trong ngoặc (Fe₂O₃: iron(III) oxide); oxide phi kim…","Theo tính chất hoá học, oxide chia thành bốn loại: Oxide base, oxide acid, oxide lưỡng tính, oxide trung tính.","Oxide acid (CO₂, SO₂, SO₃, P₂O₅) tác…: Oxide acid (CO₂, SO₂, SO₃, P₂O₅) tác dụng với dung dịch base tạo muối và nước: CO₂ + Ca(OH)₂ → CaCO₃ + H₂O (nước vôi trong vẩn đục)."],"e":["Hay nhầm: Oxide chỉ có hai nguyên tố.","Hay nhầm: Oxide acid, tác dụng với base.","Hay nhầm: Oxide base, tác dụng với acid.","Hay nhầm: Lưỡng tính, tác dụng với cả hai.","Hay nhầm: Sai: đây là khối lượng O.","Hay nhầm: Oxide trung tính không phản ứng."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 11. Muối","req":["Nêu được khái niệm muối, đọc được tên một số muối thông dụng.","Tra được bảng tính tan để biết muối tan và không tan.","Trình bày được tính chất hoá học của muối và phương pháp điều chế muối."],"sum":["Muối là hợp chất được tạo thành khi thay thế ion H⁺ của acid bằng ion kim loại hoặc ion ammonium (NH₄⁺).","Khái niệm: Muối là hợp chất được tạo thành khi thay thế ion H⁺ của acid bằng ion kim loại hoặc ion ammonium (NH₄⁺).","Tên muối = tên kim loại (kèm…: Tên muối = tên kim loại (kèm hoá trị nếu kim loại có nhiều hoá trị) + tên gốc acid.","Đa số muối là chất rắn; có…: Đa số muối là chất rắn; có muối tan tốt, ít tan hoặc không tan trong nước.","Tính chất hoá học của muối: Dung dịch muối tác dụng với kim loại tạo muối mới và kim loại mới (Zn + FeSO₄ → ZnSO₄ + Fe)","Phản ứng của muối với acid, base, muối là phản ứng trao đổi: Điều kiện xảy ra là sản phẩm có ít nhất một chất không tan (kết tủa), hoặc chất khí, hoặc chất ít phân li."],"e":["Hay nhầm: Gốc là sulfate, không phải sulfide.","Hay nhầm: Yếu hơn Cu, không đẩy được.","Hay nhầm: Cu không phản ứng với acid loãng."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 12. Phân bón hoá học","req":["Trình bày được vai trò của phân bón đối với cây trồng.","Nêu được thành phần và tác dụng cơ bản của một số loại phân bón hoá học.","Trình bày được ảnh hưởng của phân bón hoá học đến môi trường và đề xuất biện pháp giảm thiểu ô nhiễm."],"sum":["Cây trồng cần ba nhóm nguyên tố dinh dưỡng: đa lượng (N, P, K), trung lượng (Ca, Mg, S,...) và vi lượng (Zn, Mn, Fe, Cu,...).","Cây trồng cần ba nhóm nguyên tố dinh dưỡng: Đa lượng (N, P, K), trung lượng (Ca, Mg, S,...) và vi lượng (Zn, Mn, Fe, Cu,...).","Phân bón hoá học là những hoá…: Phân bón hoá học là những hoá chất chứa các nguyên tố dinh dưỡng, bón cho cây để nâng cao năng suất.","Phân đạm cung cấp nitrogen (NH₄NO₃, (NH₄)₂SO₄…: Phân đạm cung cấp nitrogen (NH₄NO₃, (NH₄)₂SO₄, urea (NH₂)₂CO, NaNO₃,...), giúp cây phát triển thân, rễ, lá.","Tác hại khi dùng sai: Phân dư thừa rửa trôi gây ô nhiễm đất, nước ngầm, sông hồ; phân huỷ sinh khí NH₃, nitrogen oxide gây ô nhiễm không khí; tồn dư hoá chất trong thực…","Quy tắc bón phân “4 đúng”: Đúng liều, đúng loại, đúng lúc, đúng nơi."],"e":["Hay nhầm: Là nguyên tố trung lượng.","Hay nhầm: Chủ yếu là vai trò của đạm.","Hay nhầm: Chỉ tính một nguyên tử N.","Hay nhầm: Cần ủ từ rác thải hữu cơ."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Mở đầu","l":[{"t":"Bài tập nâng cao · Mở đầu (2 câu)","e":["Hay nhầm: Cần biết nồng độ để dùng đúng.","Hay nhầm: Thiếu thông tin về nồng độ chất tan.","Hay nhầm: Không dùng hoá chất không nhãn."],"q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chương I. Phản ứng hoá học","l":[{"t":"Bài tập nâng cao · Chương I. Phản ứng hoá học (13 câu)","e":["Hay nhầm: Đây là sản phẩm của quang hợp.","Hay nhầm: Đảo chỉ số: H₂O có 2 H, 1 O.","Hay nhầm: H₂O chỉ có 1 nguyên tử O.","Hay nhầm: Phương trình cân bằng được."],"q":{"n":13,"lv":{"Nâng cao":13}}}]},{"t":"Chương II. Một số hợp chất thông dụng","l":[{"t":"Bài tập nâng cao · Chương II. Một số hợp chất thông dụng (10 câu)","e":["Hay nhầm: Cả hai trung tính, không phân biệt được.","Hay nhầm: Không có hiện tượng với cả hai."],"q":{"n":10,"lv":{"Nâng cao":10}}}]}]}]},{"id":"sinh","name":"Sinh học","b":[{"t":"Sinh học 8","c":[{"t":"Chương VII. Sinh học cơ thể người","l":[{"t":"Bài 30. Khái quát về cơ thể người","req":["Nêu được tên và vai trò chính của các cơ quan, hệ cơ quan trong cơ thể người."],"sum":["Cơ thể người gồm các phần: đầu, cổ, thân, hai tay và hai chân. Toàn bộ cơ thể được bao bọc bên ngoài bởi lớp da, dưới da là lớp mỡ, dưới lớp mỡ là cơ và xương.","Cơ thể người gồm các phần: Đầu, cổ, thân, hai tay và hai chân.","Các hệ cơ quan trong cơ thể người gồm: Hệ vận động, hệ tuần hoàn, hệ hô hấp, hệ tiêu hoá, hệ bài tiết, hệ thần kinh và các giác quan, hệ nội tiết, hệ sinh dục (tám hệ cơ quan).","Vai trò chính: Hệ vận động định hình cơ thể, bảo vệ nội quan, giúp cơ thể cử động và di chuyển; hệ tuần hoàn vận chuyển chất dinh dưỡng, oxygen, hormone đến tế bào…","Hệ bài tiết (phổi, thận, da) lọc…: Hệ bài tiết (phổi, thận, da) lọc chất thải có hại; hệ thần kinh và các giác quan thu nhận kích thích, điều khiển, điều hoà hoạt động; hệ nội tiết…","Mỗi cơ quan, hệ cơ quan có…: Mỗi cơ quan, hệ cơ quan có vai trò nhất định và có mối liên quan chặt chẽ với nhau, cùng hoạt động như một thể thống nhất."],"e":["Hay nhầm: Không phải hệ cơ quan người."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 31. Hệ vận động ở người","req":["Nêu được cấu tạo, chức năng của hệ vận động; liên hệ đòn bẩy.","Trình bày được một số bệnh, tật liên quan hệ vận động và cách phòng chống.","Nêu được ý nghĩa của tập thể dục, thể thao; thực hành sơ cứu khi gãy xương."],"sum":["Hệ vận động gồm bộ xương và hệ cơ. Bộ xương người trưởng thành có khoảng 206 xương chia thành ba phần: xương đầu, xương thân, xương chi.","Hệ vận động gồm bộ xương và hệ cơ: Bộ xương người trưởng thành có khoảng 206 xương chia thành ba phần: xương đầu, xương thân, xương chi.","Chức năng: Bộ xương tạo khung cơ thể, giúp cơ thể có hình dạng nhất định và bảo vệ cơ thể; cơ co dãn làm xương cử động.","Tật cong vẹo cột sống: Các đốt sống xoay lệch về một bên hay cong quá mức; do tư thế sai kéo dài, mang vác nặng, tai nạn,...","Tập thể dục, thể thao kích thích…: Tập thể dục, thể thao kích thích tăng chiều dài và chu vi của xương, cơ bắp nở nang và rắn chắc, tăng sự dẻo dai của cơ thể.","Sơ cứu gãy xương cẳng tay: Đặt tay bị gãy sát thân nạn nhân;"],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 32. Dinh dưỡng và tiêu hoá ở người","req":["Nêu khái niệm dinh dưỡng, chất dinh dưỡng; chức năng và các cơ quan hệ tiêu hoá.","Nêu được nguyên tắc lập khẩu phần ăn, một số bệnh tiêu hoá, an toàn thực phẩm."],"sum":["Chất dinh dưỡng là các chất có trong thức ăn mà cơ thể dùng làm nguyên liệu cấu tạo cơ thể và cung cấp năng lượng.","Khái niệm: Chất dinh dưỡng là các chất có trong thức ăn mà cơ thể dùng làm nguyên liệu cấu tạo cơ thể và cung cấp năng lượng.","Hệ tiêu hoá gồm ống tiêu hoá…: Hệ tiêu hoá gồm ống tiêu hoá (miệng, hầu, thực quản, dạ dày, ruột non, ruột già, hậu môn) và các tuyến tiêu hoá (tuyến nước bọt, tuỵ, gan, mật).","Ở miệng: Tiêu hoá cơ học (nhai, nghiền, đảo trộn) và hoá học nhờ enzyme amylase biến đổi một phần tinh bột chín.","Bệnh: Sâu răng (do vi khuẩn gây tổn thương mô cứng của răng); viêm loét dạ dày – tá tràng (chủ yếu do vi khuẩn Helicobacter pylori).","Khẩu phần ăn là lượng thức ăn…: Khẩu phần ăn là lượng thức ăn cung cấp cho cơ thể trong một ngày."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 33. Máu và hệ tuần hoàn của cơ thể người","req":["Nêu chức năng máu và các thành phần; nhóm máu và truyền máu; miễn dịch, vaccine.","Nêu cấu tạo, chức năng hệ tuần hoàn; một số bệnh tim mạch và cách phòng."],"m":[{"t":"Xác định nhóm máu có thể cho và nhận","w":"Đề hỏi người nhóm máu X nhận được máu của nhóm nào, hoặc nhóm nào cho được nhóm nào.","s":["Ghi kháng nguyên trên hồng cầu và kháng thể trong huyết tương của người cho và người nhận: A (kháng nguyên A, kháng thể β), B (kháng nguyên B, kháng thể α), AB (có hai…","Kiểm tra người nhận: kháng thể α chống kháng nguyên A, kháng thể β chống kháng nguyên B. Hồng cầu người cho có kháng nguyên mà người nhận có kháng thể tương ứng thì bị…","Loại các nhóm gây kết dính; các nhóm còn lại là nhóm truyền được.","Đối chiếu với sơ đồ: O → A, B, AB; A → A và AB; B → B và AB; AB → AB. Trong thực tế ưu tiên truyền máu cùng nhóm."],"n":["Chỉ xét kháng nguyên của người cho với kháng thể của người nhận, không xét ngược lại.","Nhóm O cho được nhiều nhóm nhưng chỉ nhận được máu nhóm O; nhóm AB nhận được từ mọi nhóm nhưng chỉ cho nhóm AB.","Khi truyền máu còn phải xét thêm nhóm Rh và thử phản ứng hòa hợp trước khi truyền."]}],"sum":["Máu gồm huyết tương (khoảng 55% thể tích máu, chủ yếu là nước, giúp máu lỏng và vận chuyển chất) và các tế bào máu (khoảng 45%): hồng cầu vận chuyển O₂ và CO₂; bạch cầu bảo vệ cơ thể; tiểu cầu tham…","Khái niệm: Máu gồm huyết tương (khoảng 55% thể tích máu, chủ yếu là nước, giúp máu lỏng và vận chuyển chất) và các tế bào máu (khoảng 45%): hồng cầu vận chuyển…","Kháng nguyên là chất khi xâm nhập…: Kháng nguyên là chất khi xâm nhập cơ thể kích thích tạo kháng thể tương ứng.","Vaccine chứa mầm bệnh chết hoặc suy…: Vaccine chứa mầm bệnh chết hoặc suy yếu, kích thích tạo kháng thể mà không gây bệnh nặng; kháng thể tồn tại lâu giúp cơ thể miễn dịch với bệnh đó.","Hệ nhóm máu ABO gồm bốn nhóm…: Hệ nhóm máu ABO gồm bốn nhóm A, B, AB, O, xác định theo kháng nguyên A, B trên hồng cầu và kháng thể α, β trong huyết tương.","Hệ tuần hoàn gồm tim và hệ…: Hệ tuần hoàn gồm tim và hệ mạch (động mạch, mao mạch, tĩnh mạch), tạo thành hệ kín."],"d":["Xác định nhóm máu có thể cho và nhận"],"e":["Hay nhầm: Hồng cầu nhóm A có kháng nguyên A, bị kháng thể α trong máu người nhóm O làm kết dính.","Hay nhầm: Hồng cầu nhóm B có kháng nguyên B, bị kháng thể β trong máu người nhóm O làm kết dính.","Hay nhầm: Hồng cầu nhóm AB có cả hai kháng nguyên nên bị cả hai kháng thể làm kết dính.","Hay nhầm: Nhóm O có cả hai kháng thể nên chỉ nhận được nhóm O.","Hay nhầm: Nhóm A có kháng thể β nên không nhận được nhóm B và AB.","Hay nhầm: Nhóm B có kháng thể α nên không nhận được nhóm A và AB."],"q":{"n":16,"lv":{"Biết":3,"Hiểu":8,"Vận dụng":5}}},{"t":"Bài 34. Hệ hô hấp ở người","req":["Nêu cấu tạo và chức năng hệ hô hấp; một số bệnh hô hấp; tác hại của thuốc lá; hô hấp nhân tạo."],"sum":["Hệ hô hấp gồm đường dẫn khí (mũi, họng, thanh quản, khí quản, phế quản) và hai lá phổi. Phổi gồm nhiều phế nang là nơi trao đổi khí; phế nang được bao bọc bởi mạng mao mạch dày đặc.","Khái niệm: Hệ hô hấp gồm đường dẫn khí (mũi, họng, thanh quản, khí quản, phế quản) và hai lá phổi.","Đường dẫn khí dẫn khí ra, vào…: Đường dẫn khí dẫn khí ra, vào phổi, ngăn bụi, làm ẩm, làm ấm không khí.","Trao đổi khí ở phổi và tế bào theo cơ chế khuếch tán: O₂ từ phế nang vào máu, CO₂ từ máu ra phế nang;","Bệnh: Viêm đường hô hấp (viêm mũi, họng, phế quản), viêm phổi (phế nang bị viêm, tiết dịch), lao phổi (do vi khuẩn Mycobacterium tuberculosis, dễ lây qua…","Khói thuốc lá chứa CO (chiếm chỗ…: Khói thuốc lá chứa CO (chiếm chỗ O₂ trong hồng cầu), NO₂ (gây viêm, sưng niêm mạc), nicotine (làm tê liệt lông rung trong phế quản, tăng nguy cơ ung…"],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 35. Hệ bài tiết ở người","req":["Nêu chức năng hệ bài tiết; các cơ quan của hệ bài tiết nước tiểu; bệnh hệ bài tiết; ghép thận, chạy thận."],"sum":["Hệ bài tiết có chức năng lọc và thải ra ngoài các chất cặn bã do tế bào tạo ra và các chất có thể gây độc.","Khái niệm: Hệ bài tiết có chức năng lọc và thải ra ngoài các chất cặn bã do tế bào tạo ra và các chất có thể gây độc.","Hệ bài tiết nước tiểu gồm hai…: Hệ bài tiết nước tiểu gồm hai quả thận, ống dẫn nước tiểu, bóng đái, ống đái.","Bệnh: Sỏi thận (muối calcium oxalate, phosphate, urate tích tụ); viêm cầu thận (liên cầu khuẩn); suy thận (do tiểu đường, huyết áp cao, mất máu,...).","Ghép thận: Ghép quả thận hoạt động bình thường vào người bệnh."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 36. Điều hoà môi trường trong của cơ thể người","req":["Nêu khái niệm môi trường trong và cân bằng môi trường trong, vai trò của việc duy trì ổn định.","Đọc hiểu kết quả xét nghiệm glucose và uric acid."],"sum":["Môi trường trong của cơ thể gồm máu, nước mô và bạch huyết. Môi trường trong thường xuyên liên hệ với môi trường ngoài qua các hệ cơ quan như tiêu hoá, tuần hoàn, hô hấp, bài tiết.","Môi trường trong của cơ thể gồm máu, nước mô và bạch huyết: Môi trường trong thường xuyên liên hệ với môi trường ngoài qua các hệ cơ quan như tiêu hoá, tuần hoàn, hô hấp, bài tiết.","Cân bằng môi trường trong là sự…: Cân bằng môi trường trong là sự duy trì ổn định các điều kiện như nồng độ glucose, muối sodium chloride, urea, uric acid, pH trong máu.","Glucose trong máu khi đói (không ăn…: Glucose trong máu khi đói (không ăn 8 giờ) trên 7 mmol/L kéo dài là biểu hiện bệnh tiểu đường.","Xét nghiệm máu hoặc nước tiểu giúp…: Xét nghiệm máu hoặc nước tiểu giúp xác định nồng độ các yếu tố.","Sau khi ăn mặn, nồng độ muối…: Sau khi ăn mặn, nồng độ muối trong máu tăng nên khát; uống nhiều nước giúp pha loãng, thận thải bớt muối để đưa nồng độ trở lại bình thường."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 37. Hệ thần kinh và các giác quan ở người","req":["Nêu cấu tạo, chức năng hệ thần kinh; bệnh và chất gây nghiện.","Nêu cấu tạo và hoạt động của mắt, tai; bệnh tật về mắt, tai."],"sum":["Hệ thần kinh điều khiển, điều hoà và phối hợp hoạt động của các cơ quan thành một thể thống nhất.","Khái niệm: Hệ thần kinh điều khiển, điều hoà và phối hợp hoạt động của các cơ quan thành một thể thống nhất.","Bệnh: Parkinson (thoái hoá tế bào thần kinh, run tay, mất thăng bằng), động kinh (co giật, mất ý thức), Alzheimer (mất trí nhớ, thường ở người cao tuổi).","Con người có năm giác quan: Thị giác, thính giác, xúc giác, vị giác, khứu giác.","Đau mắt đỏ do virus Adeno, vi…: Đau mắt đỏ do virus Adeno, vi khuẩn Staphylococcus; cận thị: nhìn rõ vật gần, ảnh ở trước màng lưới, đeo kính phân kì; viễn thị: nhìn rõ vật xa, ảnh…","Tai gồm tai ngoài (vành tai, ống…: Tai gồm tai ngoài (vành tai, ống tai), tai giữa (màng nhĩ, chuỗi xương tai, vòi tai) và tai trong (ốc tai)."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 38. Hệ nội tiết ở người","req":["Kể tên và nêu chức năng các tuyến nội tiết; bệnh nội tiết và cách phòng."],"sum":["Các tuyến nội tiết tiết hormone vận chuyển theo đường máu đến cơ quan đích, điều khiển và điều hoà hoạt động, duy trì ổn định môi trường trong.","Khái niệm: Các tuyến nội tiết tiết hormone vận chuyển theo đường máu đến cơ quan đích, điều khiển và điều hoà hoạt động, duy trì ổn định môi trường trong.","Tuyến yên tiết hormone kích thích nhiều…: Tuyến yên tiết hormone kích thích nhiều tuyến khác, ảnh hưởng tăng trưởng.","Bệnh đái tháo đường do thiếu insulin…: Bệnh đái tháo đường do thiếu insulin hoặc insulin giảm tác dụng, glucose máu tăng; triệu chứng ăn nhiều, uống nhiều, tiểu nhiều, sụt cân."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 39. Da và điều hoà thân nhiệt ở người","req":["Nêu cấu tạo và chức năng của da; bệnh da và bảo vệ da.","Nêu khái niệm thân nhiệt, cơ chế điều hoà thân nhiệt, phòng chống nóng lạnh."],"sum":["Da gồm lớp biểu bì, lớp bì và lớp mỡ dưới da. Da bảo vệ cơ thể, chống thấm nước và mất nước, tham gia điều hoà thân nhiệt, nhận kích thích nhờ thụ quan và bài tiết mồ hôi.","Da gồm lớp biểu bì, lớp bì và lớp mỡ dưới da: Da bảo vệ cơ thể, chống thấm nước và mất nước, tham gia điều hoà thân nhiệt, nhận kích thích nhờ thụ quan và bài tiết mồ hôi.","Thân nhiệt là nhiệt độ của cơ…: Thân nhiệt là nhiệt độ của cơ thể, bình thường khoảng 37 °C và dao động không quá 0,5 °C.","Khi nóng: Mạch máu dưới da dãn, tăng tiết mồ hôi, tăng toả nhiệt.","Chống nóng: Đội mũ nón, uống đủ nước, tránh nắng gắt, không tắm ngay khi ra nhiều mồ hôi.","Ghép da giúp cứu chữa người bỏng nặng, nhiễm trùng da: Bệnh về da như hắc lào, ghẻ; phòng bằng vệ sinh da sạch sẽ, không dùng chung đồ."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 40. Sinh sản ở người","req":["Nêu cấu tạo và chức năng hệ sinh dục; thụ tinh, thụ thai; kinh nguyệt; biện pháp tránh thai; bệnh lây qua đường sinh dục; bảo vệ sức khoẻ sinh sản."],"sum":["Hệ sinh dục nam: hai tinh hoàn (sản sinh tinh trùng, nằm trong bìu), mào tinh, ống dẫn tinh, túi tinh, ống đái, dương vật.","Hệ sinh dục nam: Hai tinh hoàn (sản sinh tinh trùng, nằm trong bìu), mào tinh, ống dẫn tinh, túi tinh, ống đái, dương vật.","Thụ tinh: Tinh trùng kết hợp với trứng tạo hợp tử, xảy ra ở ống dẫn trứng; chỉ một tinh trùng kết hợp với một trứng.","Kinh nguyệt: Nếu trứng không được thụ tinh, thể vàng tiêu giảm, hormone progesterone giảm làm lớp niêm mạc tử cung bong ra, gây chảy máu.","Nguyên tắc tránh thai: Ngăn trứng chín và rụng, ngăn tinh trùng gặp trứng, hoặc chống trứng đã thụ tinh làm tổ.","Bệnh lây qua đường sinh dục: Giang mai (xoắn khuẩn Treponema pallidum), lậu (song cầu khuẩn Neisseria gonorrhoeae), AIDS (do HIV, tấn công tế bào lympho T; lây qua quan hệ tình…"],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}}]},{"t":"Chương VIII. Sinh vật và môi trường","l":[{"t":"Bài 41. Môi trường và các nhân tố sinh thái","req":["Nêu khái niệm môi trường sống, các loại môi trường; nhân tố sinh thái; giới hạn sinh thái."],"sum":["Môi trường sống là nơi sống của sinh vật, bao gồm các nhân tố xung quanh có ảnh hưởng trực tiếp hoặc gián tiếp đến sự tồn tại và phát triển của sinh vật.","Khái niệm: Môi trường sống là nơi sống của sinh vật, bao gồm các nhân tố xung quanh có ảnh hưởng trực tiếp hoặc gián tiếp đến sự tồn tại và phát triển của sinh…","Các loại môi trường sống chủ yếu: Môi trường trên cạn, môi trường dưới nước, môi trường trong đất và môi trường sinh vật (cơ thể động vật, thực vật, con người).","Nhân tố sinh thái là các nhân…: Nhân tố sinh thái là các nhân tố trong môi trường ảnh hưởng đến sinh vật.","Thực vật gồm cây ưa sáng và cây ưa bóng: Nhiệt độ ảnh hưởng đến hình thái và hoạt động sinh lí.","Giới hạn sinh thái là khoảng giá…: Giới hạn sinh thái là khoảng giá trị của một nhân tố sinh thái mà sinh vật có thể tồn tại và phát triển ổn định."],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}},{"t":"Bài 42. Quần thể sinh vật","req":["Nêu khái niệm quần thể sinh vật, các đặc trưng cơ bản và biện pháp bảo vệ quần thể."],"m":[{"t":"Tính mật độ, kích thước quần thể","w":"Đề cho số cá thể, diện tích (thể tích) và hỏi mật độ, kích thước hoặc sự thay đổi số lượng cá thể.","s":["Xác định số cá thể N và diện tích (hoặc thể tích) S của nơi sinh sống, đổi về cùng đơn vị.","Mật độ = số cá thể : diện tích, đơn vị là cá thể/ha, cá thể/m²,...; hỏi ngược thì kích thước = mật độ × diện tích.","Nếu có sinh, tử, nhập cư, xuất cư thì kích thước mới = kích thước ban đầu + sinh + nhập cư − tử − xuất cư.","Tỉ lệ giới tính là tỉ lệ số đực : số cái; kết luận và ghi đúng đơn vị."],"n":["Mật độ là số cá thể trên một đơn vị diện tích, không phải tổng số cá thể.","Phải đổi cùng đơn vị diện tích (ha, m², km²) trước khi chia.","Quần thể chỉ gồm các cá thể cùng loài trong cùng một vùng; không tính loài khác."]}],"sum":["Quần thể sinh vật là tập hợp các cá thể cùng loài, sinh sống trong một khoảng không gian xác định, ở một thời điểm nhất định và có khả năng sinh sản tạo thế hệ mới.","Khái niệm: Quần thể sinh vật là tập hợp các cá thể cùng loài, sinh sống trong một khoảng không gian xác định, ở một thời điểm nhất định và có khả năng sinh sản…","Đặc trưng cơ bản: Kích thước quần thể (số lượng cá thể), mật độ cá thể (số cá thể trên một đơn vị diện tích hay thể tích), tỉ lệ giới tính (tỉ lệ đực : cái), thành…","Mật độ = số lượng cá thể : diện tích (hoặc thể tích): Ba kiểu phân bố cá thể: đều (điều kiện sống phân bố đều, cạnh tranh gay gắt), theo nhóm (điều kiện sống không đều, có tập tính sống bầy đàn), ngẫu…","Biện pháp bảo vệ quần thể: Bảo vệ môi trường sống, thành lập vườn quốc gia và khu bảo tồn, kiểm soát dịch bệnh, khai thác tài nguyên hợp lí; quần thể có nguy cơ tuyệt chủng…"],"d":["Tính mật độ, kích thước quần thể"],"e":["Lưu ý: Mật độ là số cá thể trên một đơn vị diện tích, không phải tổng số cá thể.","Lưu ý: Phải đổi cùng đơn vị diện tích (ha, m², km²) trước khi chia.","Lưu ý: Quần thể chỉ gồm các cá thể cùng loài trong cùng một vùng; không tính loài khác."],"q":{"n":15,"lv":{"Biết":3,"Hiểu":8,"Vận dụng":4}}},{"t":"Bài 43. Quần xã sinh vật","req":["Nêu khái niệm quần xã, đặc trưng cơ bản và bảo vệ đa dạng sinh học."],"sum":["Quần xã sinh vật là tập hợp các quần thể sinh vật thuộc nhiều loài khác nhau, cùng sống trong một không gian và thời gian nhất định, có mối quan hệ gắn bó như một thể thống nhất.","Khái niệm: Quần xã sinh vật là tập hợp các quần thể sinh vật thuộc nhiều loài khác nhau, cùng sống trong một không gian và thời gian nhất định, có mối quan hệ…","Đặc trưng cơ bản: Độ đa dạng (mức phong phú về số loài và số cá thể mỗi loài) và thành phần loài.","Loài ưu thế là loài có số…: Loài ưu thế là loài có số lượng cá thể nhiều, hoạt động mạnh, vai trò quan trọng (ví dụ lúa ở ruộng lúa).","Bảo vệ đa dạng sinh học: Tuyên truyền, xây dựng luật và chiến lược quốc gia, thành lập vườn quốc gia, khu bảo tồn, bảo vệ nguồn tài nguyên sinh vật, nghiêm cấm săn bắt mua…"],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 44. Hệ sinh thái","req":["Nêu khái niệm hệ sinh thái, thành phần; chuỗi, lưới thức ăn; trao đổi chất, năng lượng; bảo vệ hệ sinh thái."],"m":[{"t":"Bài tập chuỗi thức ăn và lưới thức ăn","w":"Đề cho danh sách loài và quan hệ ăn nhau, hỏi sắp xếp thành chuỗi, xác định bậc dinh dưỡng, đếm chuỗi hoặc dự đoán khi một loài thay đổi.","s":["Tìm sinh vật sản xuất (thực vật, tảo): luôn là mắt xích đầu tiên của chuỗi.","Sắp xếp các loài theo quan hệ ăn và bị ăn; vẽ mũi tên từ loài bị ăn sang loài ăn (chiều đi của năng lượng).","Xác định bậc: sinh vật sản xuất, rồi sinh vật tiêu thụ bậc 1 (ăn sinh vật sản xuất), bậc 2, bậc 3 ... theo thứ tự trong chuỗi.","Với lưới thức ăn: liệt kê từng chuỗi bắt đầu từ sinh vật sản xuất; xét ảnh hưởng khi một loài tăng hoặc giảm theo các mũi tên."],"n":["Mũi tên đi từ loài bị ăn đến loài ăn, không viết ngược.","Trong lưới thức ăn một loài có thể ở nhiều chuỗi và nhiều bậc dinh dưỡng khác nhau.","Năng lượng giảm dần qua mỗi bậc (khoảng 10% được chuyển sang bậc sau), nên chuỗi thường ngắn."]}],"sum":["Hệ sinh thái là hệ thống gồm quần xã sinh vật và môi trường sống của chúng. Thành phần: vô sinh và hữu sinh.","Khái niệm: Hệ sinh thái là hệ thống gồm quần xã sinh vật và môi trường sống của chúng.","Hệ sinh thái chia thành tự nhiên (trên cạn: Rừng mưa nhiệt đới, sa mạc; dưới nước: nước ngọt như hồ, sông; nước mặn như rừng ngập mặn, rạn san hô) và nhân tạo (đồng ruộng, rừng trồng, khu dân…","Chuỗi thức ăn gồm nhiều loài có…: Chuỗi thức ăn gồm nhiều loài có quan hệ dinh dưỡng, ví dụ cỏ → châu chấu → ếch → rắn → đại bàng.","Năng lượng ánh sáng Mặt Trời được…: Năng lượng ánh sáng Mặt Trời được sinh vật sản xuất hấp thụ, truyền một chiều qua các bậc dinh dưỡng và giảm dần do sinh vật dùng và toả nhiệt ra…","Bảo vệ hệ sinh thái: Ngăn chặn phá rừng, khai thác hợp lí; quản lí chất thải, kiểm soát ô nhiễm biển; bảo vệ đất, chống xói mòn, khô hạn, mặn cho hệ sinh thái nông nghiệp."],"d":["Bài tập chuỗi thức ăn và lưới thức ăn"],"e":["Hay nhầm: Mũi tên viết ngược chiều dòng năng lượng.","Hay nhầm: Chuỗi phải bắt đầu bằng sinh vật sản xuất (cỏ), không phải châu chấu.","Hay nhầm: Ếch không ăn cỏ, châu chấu mới ăn cỏ rồi bị ếch ăn.","Hay nhầm: Thiếu thức ăn thì thỏ không thể tăng mãi.","Hay nhầm: Động vật không tự tổng hợp được chất hữu cơ như thực vật.","Hay nhầm: Các loài trong chuỗi phụ thuộc nhau nên sự biến mất của cỏ ảnh hưởng đến cả chuỗi."],"q":{"n":17,"lv":{"Biết":3,"Hiểu":8,"Vận dụng":6}}},{"t":"Bài 45. Sinh quyển","req":["Nêu khái niệm sinh quyển; nhận biết các khu sinh học chủ yếu."],"sum":["Sinh quyển là toàn bộ sinh vật sống trên Trái Đất cùng với các nhân tố vô sinh của môi trường.","Khái niệm: Sinh quyển là toàn bộ sinh vật sống trên Trái Đất cùng với các nhân tố vô sinh của môi trường.","Khu sinh học là hệ sinh thái…: Khu sinh học là hệ sinh thái đặc trưng cho vùng địa lí do điều kiện khí hậu khác nhau.","Khu sinh học trên cạn từ cực đến nhiệt đới: Đồng rêu hàn đới, rừng lá kim phương bắc, rừng ôn đới, rừng mưa nhiệt đới."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 46. Cân bằng tự nhiên","req":["Nêu khái niệm cân bằng tự nhiên, nguyên nhân mất cân bằng, biện pháp bảo vệ."],"sum":["Cân bằng tự nhiên là trạng thái ổn định tự nhiên của các cấp độ tổ chức sống, hướng tới sự thích nghi cao nhất với điều kiện sống.","Khái niệm: Cân bằng tự nhiên là trạng thái ổn định tự nhiên của các cấp độ tổ chức sống, hướng tới sự thích nghi cao nhất với điều kiện sống.","Quần thể tự điều chỉnh số lượng…: Quần thể tự điều chỉnh số lượng khi quá thấp hoặc quá cao để đạt trạng thái cân bằng, phù hợp khả năng cung cấp nguồn sống.","Khống chế sinh học là hiện tượng…: Khống chế sinh học là hiện tượng số lượng cá thể của quần thể này bị khống chế ở mức nhất định bởi quần thể kia (ví dụ thỏ tuyết và linh miêu).","Nguyên nhân mất cân bằng: Chủ yếu do con người (phá rừng, săn bắt, khai thác quá mức, chất thải ô nhiễm) và thiên tai (động đất, núi lửa)."],"e":["Hay nhầm: Không phải trạng thái tĩnh."],"q":{"n":11,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":2}}},{"t":"Bài 47. Bảo vệ môi trường","req":["Trình bày tác động của con người đến môi trường; ô nhiễm môi trường; biến đổi khí hậu; bảo vệ động vật hoang dã."],"sum":["Tác động qua các thời kì: nguyên thuỷ (hái lượm, săn bắn, dùng lửa); xã hội nông nghiệp (trồng trọt, chăn nuôi, định cư, thuần hoá, thuỷ lợi); công nghiệp và hậu công nghiệp (cơ giới hoá, khai thác…","Tác động qua các thời kì: Nguyên thuỷ (hái lượm, săn bắn, dùng lửa); xã hội nông nghiệp (trồng trọt, chăn nuôi, định cư, thuần hoá, thuỷ lợi); công nghiệp và hậu công nghiệp…","Ô nhiễm môi trường là sự biến…: Ô nhiễm môi trường là sự biến đổi tính chất vật lí, hoá học, sinh học của môi trường không phù hợp tiêu chuẩn, gây ảnh hưởng xấu đến sức khoẻ con…","Nguyên nhân: Chất thải công nghiệp và sinh hoạt (CO, SO₂, CO₂, NO₂,...), hoá chất bảo vệ thực vật, chất phóng xạ, vi sinh vật gây bệnh.","Biến đổi khí hậu là sự thay…: Biến đổi khí hậu là sự thay đổi của khí hậu trong thời gian dài, chủ yếu do khí nhà kính tăng; biện pháp thích ứng: trồng rừng, tiết kiệm năng…","Cần bảo vệ động vật hoang dã…: Cần bảo vệ động vật hoang dã có nguy cơ tuyệt chủng để giữ đa dạng sinh học và cân bằng sinh thái: cấm săn bắt buôn bán trái phép, bảo vệ nơi sống,…"],"q":{"n":12,"lv":{"Biết":3,"Hiểu":6,"Vận dụng":3}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương VII. Sinh học cơ thể người","l":[{"t":"Bài tập nâng cao · Chương VII. Sinh học cơ thể người (22 câu)","q":{"n":22,"lv":{"Nâng cao":22}}}]},{"t":"Chương VIII. Sinh vật và môi trường","l":[{"t":"Bài tập nâng cao · Chương VIII. Sinh vật và môi trường (14 câu)","q":{"n":14,"lv":{"Nâng cao":14}}}]}]}]},{"id":"anh","name":"Tiếng Anh","b":[{"t":"Tiếng Anh 8","c":[{"t":"Chủ điểm 1. Our Communities (Cộng đồng của chúng ta)","l":[{"t":"Unit 1. Leisure time (Thời gian rảnh rỗi)","req":["Dùng đúng động từ chỉ sở thích với V-ing hoặc to V.","Dùng be keen on / fond of / crazy about + V-ing.","Nói và viết về hoạt động lúc rảnh rỗi."],"sum":["Love, like, enjoy, hate… + V-ing. Chỉ love, like, hate, prefer mới đi được với to V.","Động từ yêu / ghét + V-ing: Dùng V-ing khi nói về một hoạt động nói chung.","Love, like, hate, prefer + to V: Bốn động từ này có thể đi với to V, nghĩa gần như không đổi.","Tính từ chỉ sở thích: Đi với V-ing hoặc danh từ. Sau giới từ (of, on, about, in) luôn là V-ing."],"e":["Sai: He enjoys to read comics. → Đúng: He enjoys reading comics. (Chỉ enjoy, fancy, detest, dislike, don’t mind CHỈ đi với V-ing, không đi với to V.)","Sai: I’m crazy about to snowboard. → Đúng: I’m crazy about snowboarding. (Sau giới từ luôn dùng V-ing.)","Hay nhầm: Enjoy không đi với động từ nguyên mẫu.","Hay nhầm: Does là động từ chia, không đứng sau enjoy.","Hay nhầm: Fancy không đi với nguyên mẫu không to.","Hay nhầm: Went là quá khứ, không đứng sau fancy."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 2. Life in the countryside (Cuộc sống ở nông thôn)","req":["Dùng đúng so sánh hơn của trạng từ ngắn, dài và bất quy tắc.","Phân biệt so sánh hơn của tính từ và trạng từ.","Nói về công việc và cuộc sống ở nông thôn."],"sum":["Trạng từ ngắn thêm -er + than. Trạng từ dài dùng more / less + adv + than. Bất quy tắc: well → better, badly → worse.","Trạng từ ngắn: thêm -er: Trạng từ một âm tiết, thường cùng dạng với tính từ.","Trạng từ dài: more / less: Trạng từ thường có đuôi -ly dùng more + adv + than. Kém hơn dùng less + adv + than.","Trạng từ bất quy tắc","Trạng từ khác tính từ ở đâu?: Tính từ bổ nghĩa cho danh từ. Trạng từ bổ nghĩa cho động từ. Sau than có thể dùng đại từ tân ngữ (than me) hoặc mệnh đề (than I do).","Từ vựng công việc nhà nông"],"e":["Sai: Life goes more slow here. → Đúng: Life goes more slowly here. (Bổ nghĩa cho động từ “goes” nên phải dùng trạng từ slowly.)","Hay nhầm: Early là trạng từ ngắn, không dùng more.","Hay nhầm: Earliest là so sánh nhất.","Hay nhầm: Cần trạng từ, không dùng tính từ.","Hay nhầm: More peaceful là tính từ, không bổ nghĩa cho live.","Hay nhầm: Trạng từ dài không thêm -er."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 3. Teenagers (Tuổi thiếu niên)","req":["Phân biệt và viết đúng câu đơn, câu ghép.","Dùng các cặp liên từ either … or, neither … nor, both … and, not only … but also.","Nói về áp lực tuổi thiếu niên và cách giải quyết."],"sum":["Câu đơn = 1 mệnh đề. Câu ghép = 2 mệnh đề độc lập nối bằng dấu phẩy + liên từ hoặc dấu chấm phẩy.","Câu đơn (simple sentence): Chỉ có một mệnh đề độc lập. Chủ ngữ hoặc động từ có thể là cụm ghép mà câu vẫn là câu đơn.","Câu ghép (compound sentence): Có hai mệnh đề độc lập trở lên. Nối bằng dấu phẩy và liên từ đẳng lập (and, but, or, so, yet) hoặc bằng dấu chấm phẩy.","Cặp liên từ (correlative conjunctions)","Lỗi hay gặp: dấu phẩy đặt sau liên từ"],"e":["Sai: Teenagers face a lot of pressure, they need support. → Đúng: Teenagers face a lot of pressure, so they need support. (Nối hai mệnh đề chỉ bằng dấu phẩy gọi là comma splice, là lỗi sai.)","Sai: Teenagers face a lot of pressure so, they need support. → Đúng: Teenagers face a lot of pressure, so they need support. (Dấu phẩy phải đứng trước liên từ, không đứng sau.)","Hay nhầm: Hai chủ ngữ nhưng chỉ một mệnh đề: câu đơn.","Hay nhầm: Hai động từ cùng một chủ ngữ: câu đơn.","Hay nhầm: Session là tiết học, buổi.","Hay nhầm: Media là phương tiện truyền thông."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 2. Our Heritage (Di sản của chúng ta)","l":[{"t":"Unit 4. Ethnic groups of Viet Nam (Các dân tộc Việt Nam)","req":["Đặt câu hỏi Yes/No và Wh- đúng cấu trúc.","Phân biệt danh từ đếm được và không đếm được.","Giới thiệu được một dân tộc Việt Nam."],"sum":["Yes/No: đưa trợ động từ / be / khuyết thiếu lên đầu câu. Wh-: từ để hỏi đứng trước trợ động từ. Đếm được → How many, không đếm được → How much.","Câu hỏi Yes/No: Đưa trợ động từ (do / does / did), động từ be hoặc động từ khuyết thiếu (can, will, should) lên đầu câu. Trả lời ngắn lặp lại trợ động từ đó.","Câu hỏi Wh-: Từ để hỏi đứng trước trợ động từ.","Danh từ đếm được và không đếm được: Hỏi số lượng: How many + đếm được số nhiều; How much + không đếm được.","Lưu ý khi đếm: Livestock và cattle là danh từ tập hợp, không thêm -s. Dùng a piece of cloth, a bag of rice để đếm danh từ không đếm được."],"e":["Sai: How many rice do they eat? → Đúng: How much rice do they eat? (rice là danh từ không đếm được nên dùng How much.)","Hay nhầm: Are không đi với động từ live.","Hay nhầm: Did là quá khứ, nhưng trả lời ở hiện tại.","Hay nhầm: Communal house là nhà rông.","Hay nhầm: Wooden house chỉ là nhà gỗ nói chung.","Hay nhầm: Terraced house là nhà liền kề (ở Anh)."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 5. Our customs and traditions (Phong tục và truyền thống)","req":["Dùng đúng a, an, the và trường hợp không dùng mạo từ.","Phân biệt các cụm cố định có và không có mạo từ.","Nói về phong tục, truyền thống của gia đình và quê hương."],"sum":["a / an: chọn theo ÂM đầu. the: đã xác định, duy nhất, so sánh nhất, nhạc cụ. Không mạo từ: số nhiều và không đếm được nói chung.","a / an: Dùng với danh từ đếm được số ít, nhắc lần đầu hoặc nói chung chung. Chọn theo ÂM đầu, không theo chữ cái.","the: Dùng khi người nói và người nghe đều biết là cái nào.","Không dùng mạo từ","So sánh: có the và không the"],"e":["Sai: She waited for a hour. → Đúng: She waited for an hour. (hour đọc là /aʊə/, âm đầu là nguyên âm.)","Hay nhầm: Pagoda bắt đầu bằng phụ âm.","Hay nhầm: Danh từ đếm được số ít cần mạo từ.","Hay nhầm: Carp bắt đầu bằng phụ âm.","Hay nhầm: Danh từ đếm được số ít cần mạo từ.","Hay nhầm: Ornamental tree là cây cảnh."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 6. Lifestyles (Lối sống)","req":["Dùng đúng thì tương lai đơn với will / won’t.","Viết đúng câu điều kiện loại 1 và unless.","Nói về lối sống và dự đoán sự thay đổi."],"sum":["Tương lai đơn: will + V. Điều kiện loại 1: If + hiện tại đơn, will + V. Không dùng will trong mệnh đề If.","Thì tương lai đơn: Dùng will + V để dự đoán, hứa hẹn hoặc quyết định tức thời.","Câu điều kiện loại 1: Nói về điều có thể xảy ra ở hiện tại hoặc tương lai. Mệnh đề If ở hiện tại đơn, mệnh đề chính ở tương lai đơn (hoặc can / should / câu mệnh lệnh).","Lỗi hay gặp và Unless: Unless = if … not.","Từ vựng về lối sống"],"e":["Sai: If it will rain, we will stay at home. → Đúng: If it rains, we will stay at home. (Không dùng will trong mệnh đề If.)","Hay nhầm: Không dùng will trong mệnh đề If.","Hay nhầm: Câu điều kiện loại 1 không dùng quá khứ.","Hay nhầm: Dogsled là xe trượt tuyết chó kéo.","Hay nhầm: Musher là người điều khiển xe chó kéo.","Hay nhầm: Are không đi với serve như vậy."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 3. Our World (Thế giới của chúng ta)","l":[{"t":"Unit 7. Environmental protection (Bảo vệ môi trường)","req":["Viết đúng câu phức với mệnh đề trạng ngữ chỉ thời gian.","Dùng hiện tại đơn trong mệnh đề thời gian nói về tương lai.","Nói về cách bảo vệ môi trường và các loài có nguy cơ tuyệt chủng."],"sum":["Câu phức = mệnh đề chính + mệnh đề thời gian (when, while, before, after, until, as soon as…). Nói về tương lai: mệnh đề thời gian dùng hiện tại đơn.","Câu phức với mệnh đề thời gian: Mệnh đề thời gian có thể đứng trước (có dấu phẩy) hoặc sau mệnh đề chính (không dấu phẩy).","Nghĩa của từng liên từ","Nói về tương lai: không dùng will: Mệnh đề thời gian dùng hiện tại đơn, dù mệnh đề chính nói về tương lai.","While và rút gọn mệnh đề: While thường đi với thì tiếp diễn cho hành động đang diễn ra. Khi hai mệnh đề cùng chủ ngữ, có thể rút gọn."],"e":["Sai: As soon as the storm will end, residents will clean the beach. → Đúng: As soon as the storm ends, residents will clean the beach. (Không dùng will trong mệnh đề thời gian.)","Hay nhầm: Until là cho đến khi, sai nghĩa.","Hay nhầm: Unless là trừ khi, sai nghĩa.","Hay nhầm: Although là mặc dù, sai nghĩa.","Hay nhầm: After là sau khi, sai nghĩa.","Hay nhầm: Until là cho đến khi, sai nghĩa."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 8. Shopping (Mua sắm)","req":["Dùng đúng vị trí trạng từ và cụm chỉ tần suất.","Dùng hiện tại đơn cho sự kiện theo lịch trong tương lai.","Nói về các kiểu chợ, cửa hàng và thói quen mua sắm."],"sum":["Trạng từ tần suất đứng trước động từ thường, sau be, sau trợ động từ. Hiện tại đơn dùng cho lịch cố định trong tương lai.","Trạng từ tần suất","Cụm chỉ tần suất: Đứng cuối hoặc đầu câu.","Hiện tại đơn cho lịch cố định: Dùng cho sự kiện tương lai theo lịch, thời gian biểu cố định: giờ mở cửa, tàu xe, lịch chiếu phim, hội chợ.","Lịch và dự định: Lịch cố định dùng hiện tại đơn. Dự định cá nhân dùng will hoặc be going to."],"e":["Hay nhầm: Không dùng am với động từ go.","Hay nhầm: Không dùng am với động từ go.","Hay nhầm: Trạng từ đứng trước động từ thường.","Hay nhầm: Chủ ngữ số ít cần closes.","Hay nhầm: Lịch cố định không dùng tiếp diễn.","Hay nhầm: Không có dạng will closes."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 9. Natural disasters (Thiên tai)","req":["Dùng đúng thì quá khứ tiếp diễn.","Kết hợp quá khứ tiếp diễn và quá khứ đơn với when / while.","Kể lại một thiên tai hoặc sự việc bất ngờ."],"sum":["Quá khứ tiếp diễn: was / were + V-ing. Việc dài đang diễn ra (tiếp diễn) thì việc ngắn xen vào (quá khứ đơn).","Thì quá khứ tiếp diễn: Diễn tả hành động đang diễn ra tại một thời điểm trong quá khứ: at 7 p.m. yesterday, at that time, this time last week.","Quá khứ tiếp diễn + when + quá khứ đơn: Hành động dài đang diễn ra (tiếp diễn) thì một hành động ngắn xen vào (quá khứ đơn). While + quá khứ tiếp diễn cho hành động nền.","Phân biệt quá khứ đơn và tiếp diễn","Từ vựng thiên tai"],"e":["Sai: I was knowing the answer. → Đúng: I knew the answer. (Động từ trạng thái (know, want, have nghĩa sở hữu) không dùng tiếp diễn.)","Hay nhầm: Quá khứ đơn không nhấn mạnh việc đang diễn ra lúc 9 giờ.","Hay nhầm: Are watching là hiện tại.","Hay nhầm: Quá khứ đơn không diễn tả hành động nền.","Hay nhầm: Was dùng cho I / he / she / it.","Hay nhầm: Đảo ngược vai trò của hai hành động."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]},{"t":"Chủ điểm 4. Visions of the Future (Tầm nhìn tương lai)","l":[{"t":"Unit 10. Communication in the future (Giao tiếp trong tương lai)","req":["Dùng đúng giới từ chỉ thời gian và nơi chốn, kể cả on the screen, on the Internet, by 2030.","Dùng đúng đại từ sở hữu và a friend of mine.","Nói về các cách giao tiếp hiện nay và trong tương lai."],"sum":["Giới từ: at (giờ, địa điểm cụ thể), on (thứ, ngày, bề mặt / màn hình), in (tháng, năm, bên trong). Đại từ sở hữu: mine, yours, his, hers, ours, theirs.","Giới từ chỉ thời gian","Giới từ chỉ nơi chốn","Đại từ sở hữu: Thay cho tính từ sở hữu + danh từ, để tránh lặp.","Lưu ý"],"e":["Sai: This is mine phone. → Đúng: This is my phone. / This phone is mine. (Đại từ sở hữu không đứng trước danh từ.)","Hay nhầm: Không dùng in với screen.","Hay nhầm: Không dùng at với screen.","Hay nhầm: By không chỉ vị trí ở đây.","Hay nhầm: Thứ không dùng at; giờ không dùng on.","Hay nhầm: Voice message là tin nhắn thoại."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 11. Science and technology (Khoa học và công nghệ)","req":["Tường thuật câu kể với said / told và lùi thì đúng.","Đổi đại từ, trạng từ thời gian và nơi chốn khi tường thuật.","Nói về công nghệ trong học tập và đời sống."],"sum":["Tường thuật: said (that) / told + người + (that), bỏ ngoặc kép, lùi thì một bậc, đổi đại từ và trạng từ.","Cấu trúc: Khi thuật lại lời người khác, dùng said (that) hoặc told + người (that), bỏ dấu ngoặc kép và lùi thì động từ một bậc về quá khứ.","Lùi thì","Đổi đại từ và trạng từ","Lỗi hay gặp"],"e":["Sai: He said me that he was busy. → Đúng: He told me that he was busy. / He said that he was busy. (Say không đi với tân ngữ chỉ người; tell luôn có tân ngữ.)","Hay nhầm: Hiện tại tiếp diễn lùi thành quá khứ tiếp diễn, không phải quá khứ đơn.","Hay nhầm: Will phải lùi thành would.","Hay nhầm: Will không lùi thành quá khứ đơn.","Hay nhầm: Say không có tân ngữ chỉ người ngay sau.","Hay nhầm: Said to me là được nhưng ít dùng ở lớp 8; đáp án chuẩn là told."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}},{"t":"Unit 12. Life on other planets (Sự sống trên các hành tinh khác)","req":["Tường thuật câu hỏi Yes/No với if / whether.","Tường thuật câu hỏi Wh- với trật tự câu kể và lùi thì.","Nói về các hành tinh và khả năng có sự sống ngoài Trái Đất."],"sum":["Tường thuật câu hỏi: dùng asked (+ người) + if / whether (Yes/No) hoặc từ để hỏi (Wh-), trật tự câu kể, lùi thì, không dấu hỏi.","Câu hỏi Yes/No: Dùng asked (+ người) + if / whether + S + V (lùi thì). Trật tự câu kể (không đảo trợ động từ), không có dấu hỏi.","Câu hỏi Wh-: Giữ từ để hỏi, bỏ trợ động từ do / does / did, đưa về trật tự câu kể và lùi thì.","Động từ tường thuật và đổi từ: Dùng ask, wonder, want to know. Đại từ và trạng từ đổi như câu kể.","Lỗi hay gặp"],"e":["Sai: She asked where was Mars. → Đúng: She asked where Mars was. (Giữ trật tự đảo là sai; phải dùng trật tự câu kể.)","Hay nhầm: What dùng cho câu hỏi Wh-.","Hay nhầm: Không dùng does trong câu tường thuật.","Hay nhầm: Không đảo và không giữ do.","Hay nhầm: Can phải lùi thành could.","Hay nhầm: Không lùi thành quá khứ đơn."],"q":{"n":18,"lv":{"Biết":5,"Hiểu":6,"Vận dụng":5,"Nâng cao":2}}}]}]}]},{"id":"lichsu","name":"Lịch sử","b":[{"t":"Lịch sử 8","c":[{"t":"Chương 1. Châu Âu và Bắc Mỹ từ nửa sau thế kỉ XVI đến thế kỉ XVIII","l":[{"t":"Bài 1. Cách mạng tư sản Anh và Chiến tranh giành độc lập của 13 thuộc địa Anh ở Bắc Mỹ","req":["Trình bày được nguyên nhân, kết quả, ý nghĩa, tính chất của Cách mạng tư sản Anh và Chiến tranh giành độc lập của 13 thuộc địa Anh ở Bắc Mỹ."],"sum":["Cách mạng tư sản Anh (1642–1688): nguyên nhân do mâu thuẫn giữa chế độ quân chủ chuyên chế với tư sản, quý tộc mới.","Cách mạng tư sản Anh (1642–1688): Nguyên nhân do mâu thuẫn giữa chế độ quân chủ chuyên chế với tư sản, quý tộc mới.","Từ khoá cần ghi nhớ: Cách mạng tư sản Anh;","Mốc sự kiện cần nhớ: 1649: vua Sác-lơ I bị xử tử, nước Anh thành cộng hoà;","Tính chất: Là cuộc cách mạng tư sản không triệt để, do liên minh tư sản – quý tộc mới lãnh đạo; mở đường cho chủ nghĩa tư bản phát triển ở Anh.","Chiến tranh giành độc lập của 13 thuộc địa Anh ở Bắc Mỹ (1775–1783): Do chính sách bóc lột, kìm hãm của Anh."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 2. Cách mạng tư sản Pháp cuối thế kỉ XVIII","req":["Trình bày được nguyên nhân, diễn biến chính, kết quả, ý nghĩa, tính chất của Cách mạng tư sản Pháp cuối thế kỉ XVIII."],"sum":["Nguyên nhân: chế độ quân chủ chuyên chế khủng hoảng; xã hội phân chia ba đẳng cấp (tăng lữ, quý tộc, đẳng cấp thứ ba) với mâu thuẫn gay gắt; trào lưu Triết học Ánh sáng (Mông-te-xki-ơ, Vôn-te,…","Nguyên nhân: Chế độ quân chủ chuyên chế khủng hoảng; xã hội phân chia ba đẳng cấp (tăng lữ, quý tộc, đẳng cấp thứ ba) với mâu thuẫn gay gắt; trào lưu Triết học…","Từ khoá cần ghi nhớ: Cách mạng tư sản Pháp;","Mốc sự kiện cần nhớ: 14/7/1789: phá ngục Ba-xti; tháng 8/1789: thông qua Tuyên ngôn Nhân quyền và Dân quyền;","Diễn biến: Ngày 14/7/1789 quần chúng tấn công pháo đài – nhà tù Ba-xti, mở đầu cách mạng.","Kết quả, ý nghĩa: Lật đổ chế độ phong kiến, mở đường cho chủ nghĩa tư bản phát triển; là cuộc cách mạng tư sản triệt để nhất, có ảnh hưởng sâu rộng trên thế giới."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 3. Cách mạng công nghiệp (nửa sau thế kỉ XVIII – giữa thế kỉ XIX)","req":["Mô tả được những nét chính về thành tựu tiêu biểu của Cách mạng công nghiệp; nêu được tác động quan trọng về kinh tế, xã hội."],"sum":["Cách mạng công nghiệp bắt đầu ở Anh từ những năm 60 của thế kỉ XVIII, sau đó lan sang Pháp, Đức, Mỹ…","Khái niệm: Cách mạng công nghiệp bắt đầu ở Anh từ những năm 60 của thế kỉ XVIII, sau đó lan sang Pháp, Đức, Mỹ…","Từ khoá cần ghi nhớ: Cách mạng công nghiệp; máy kéo sợi Gien-ni; máy hơi nước;","Mốc sự kiện cần nhớ: Bắt đầu ở Anh từ những năm 60 thế kỉ XVIII; máy hơi nước (1784, Giêm Oát);","Thành tựu tiêu biểu: Máy kéo sợi Gien-ni (1764, Giêm Ha-gri-vơ), máy dệt chạy bằng sức nước (1785, Ét-mơn Các-rai), máy hơi nước (1784, Giêm Oát), đầu máy xe lửa (1814,…","Tác động kinh tế: Chuyển từ lao động thủ công sang lao động bằng máy móc; năng suất tăng, nhiều trung tâm công nghiệp, thành phố mới ra đời."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 2. Đông Nam Á từ nửa sau thế kỉ XVI đến giữa thế kỉ XIX","l":[{"t":"Bài 4. Đông Nam Á từ nửa sau thế kỉ XVI đến giữa thế kỉ XIX","req":["Trình bày được những nét chính về quá trình xâm nhập của tư bản phương Tây vào Đông Nam Á; tình hình chính trị, kinh tế, văn hoá – xã hội; cuộc đấu tranh chống ách đô hộ."],"sum":["Từ thế kỉ XVI, các nước phương Tây (Bồ Đào Nha, Tây Ban Nha, Hà Lan, Anh, Pháp) xâm nhập Đông Nam Á qua buôn bán, truyền giáo, rồi dùng vũ lực xâm chiếm.","Khái niệm: Từ thế kỉ XVI, các nước phương Tây (Bồ Đào Nha, Tây Ban Nha, Hà Lan, Anh, Pháp) xâm nhập Đông Nam Á qua buôn bán, truyền giáo, rồi dùng vũ lực xâm…","Từ khoá cần ghi nhớ: Đông Nam Á; thực dân phương Tây; thuộc địa;","Mốc sự kiện cần nhớ: Từ thế kỉ XVI phương Tây xâm nhập;","Chính quyền thực dân thiết lập bộ…: Chính quyền thực dân thiết lập bộ máy cai trị, bóc lột kinh tế (thu thuế, độc quyền buôn bán, đồn điền), áp đặt văn hoá phương Tây.","Nhân dân Đông Nam Á đấu tranh chống thực dân: Khởi nghĩa ở In-đô-nê-xi-a, Phi-líp-pin… dù thất bại nhưng thể hiện tinh thần yêu nước."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 3. Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII","l":[{"t":"Bài 5. Cuộc xung đột Nam – Bắc triều và Trịnh – Nguyễn","req":["Nêu được những nét chính về sự ra đời của Vương triều Mạc; nguyên nhân, hệ quả của xung đột Nam – Bắc triều, Trịnh – Nguyễn."],"sum":["Đầu thế kỉ XVI, nhà Lê sơ suy yếu; năm 1527 Mạc Đăng Dung lập ra nhà Mạc. Nhà Mạc có nhiều chính sách tích cực ổn định đất nước.","Khái niệm: Đầu thế kỉ XVI, nhà Lê sơ suy yếu; năm 1527 Mạc Đăng Dung lập ra nhà Mạc.","Từ khoá cần ghi nhớ: Nhà Mạc;","Mốc sự kiện cần nhớ: 1527: Mạc Đăng Dung lập nhà Mạc;","Năm 1533, Nguyễn Kim lập Nam triều…: Năm 1533, Nguyễn Kim lập Nam triều (danh nghĩa phù Lê) ở Thanh Hoá; nhà Mạc ở phía bắc gọi là Bắc triều.","Sau đó, mâu thuẫn giữa họ Trịnh…: Sau đó, mâu thuẫn giữa họ Trịnh (Đàng Ngoài) và họ Nguyễn (Đàng Trong) dẫn đến chiến tranh Trịnh – Nguyễn (1627–1672), lấy sông Gianh (Quảng Bình)…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 6. Công cuộc khai phá vùng đất phía Nam từ thế kỉ XVI đến thế kỉ XVIII","req":["Trình bày được khái quát quá trình mở cõi từ thế kỉ XVI đến thế kỉ XVIII; quá trình thực thi chủ quyền đối với quần đảo Hoàng Sa và quần đảo Trường Sa của các chúa Nguyễn."],"sum":["Từ năm 1558, Nguyễn Hoàng vào trấn thủ Thuận Hoá, sau đó kiêm Quảng Nam. Các chúa Nguyễn tiếp tục mở rộng vùng đất phía Nam: năm 1611 lập phủ Phú Yên; năm 1653 lập dinh Thái Khang (Khánh Hoà); năm…","Khái niệm: Từ năm 1558, Nguyễn Hoàng vào trấn thủ Thuận Hoá, sau đó kiêm Quảng Nam.","Từ khoá cần ghi nhớ: Nguyễn Hoàng;","Mốc sự kiện cần nhớ: 1558: Nguyễn Hoàng vào trấn thủ Thuận Hoá;","Lưu dân người Việt cùng các dân…: Lưu dân người Việt cùng các dân tộc tại chỗ khai hoang, lập làng, xây dựng cuộc sống mới.","Các chúa Nguyễn tổ chức đội Hoàng…: Các chúa Nguyễn tổ chức đội Hoàng Sa, sau đó lập thêm đội Bắc Hải, hằng năm ra khai thác sản vật, đo đạc, thực thi chủ quyền ở quần đảo Hoàng Sa và…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 7. Khởi nghĩa nông dân ở Đàng Ngoài thế kỉ XVIII","req":["Nêu được một số nét chính (bối cảnh, diễn biến, kết quả, ý nghĩa) của phong trào nông dân ở Đàng Ngoài thế kỉ XVIII."],"sum":["Bối cảnh: chính quyền Lê – Trịnh suy yếu, quan lại tham nhũng; ruộng đất bị địa chủ chiếm đoạt; nông dân đói khổ, phiêu tán.","Bối cảnh: Chính quyền Lê – Trịnh suy yếu, quan lại tham nhũng; ruộng đất bị địa chủ chiếm đoạt; nông dân đói khổ, phiêu tán.","Từ khoá cần ghi nhớ: Khởi nghĩa nông dân;","Mốc sự kiện cần nhớ: Các cuộc khởi nghĩa tiêu biểu nổ ra từ năm 1737 đến 1770 và đều thất bại","Các cuộc khởi nghĩa tiêu biểu: Nguyễn Dương Hưng (1737), Lê Duy Mật (1738–1770), Nguyễn Danh Phương (1740–1751), Nguyễn Hữu Cầu (1741–1751), Hoàng Công Chất (1739–1769).","Kết quả: Các cuộc khởi nghĩa đều thất bại."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Phong trào Tây Sơn","req":["Trình bày được nguyên nhân, kết quả, ý nghĩa của phong trào Tây Sơn; đánh giá vai trò của Nguyễn Huệ – Quang Trung."],"sum":["Năm 1771, ba anh em Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ phát động khởi nghĩa ở Tây Sơn thượng đạo (Gia Lai), chống chính quyền chúa Nguyễn.","Khái niệm: Năm 1771, ba anh em Nguyễn Nhạc, Nguyễn Huệ, Nguyễn Lữ phát động khởi nghĩa ở Tây Sơn thượng đạo (Gia Lai), chống chính quyền chúa Nguyễn.","Từ khoá cần ghi nhớ: Tây Sơn;","Mốc sự kiện cần nhớ: 1771: khởi nghĩa Tây Sơn;","Năm 1777 lật đổ chính quyền chúa Nguyễn: Năm 1785, Nguyễn Huệ chỉ huy trận Rạch Gầm – Xoài Mút (Tiền Giang) đánh tan 5 vạn quân Xiêm.","Năm 1786, Tây Sơn tiến ra Bắc…: Năm 1786, Tây Sơn tiến ra Bắc lật đổ chính quyền chúa Trịnh, xoá bỏ ranh giới sông Gianh."],"e":["Hay nhầm: Trận Rạch Gầm – Xoài Mút."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 9. Tình hình kinh tế, văn hoá, tôn giáo trong các thế kỉ XVI – XVIII","req":["Nêu được những nét chính về tình hình kinh tế, văn hoá, tôn giáo ở Đại Việt thế kỉ XVI – XVIII."],"sum":["Nông nghiệp: Đàng Ngoài bị đình trệ do chiến tranh; Đàng Trong phát triển nhờ khai hoang vùng đất mới, nhất là Nam Bộ.","Nông nghiệp: Đàng Ngoài bị đình trệ do chiến tranh;","Từ khoá cần ghi nhớ: Kinh tế Đàng Trong;","Mốc sự kiện cần nhớ: Đô thị, thương cảng hưng thịnh: Thăng Long, Phố Hiến, Hội An, Thanh Hà, Gia Định","Thủ công nghiệp và thương nghiệp phát triển: Nhiều làng nghề (gốm Bát Tràng, dệt La Khê…);","Tôn giáo: Nho giáo suy thoái;"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 4. Châu Âu và nước Mỹ từ cuối thế kỉ XVIII đến đầu thế kỉ XX","l":[{"t":"Bài 10. Sự hình thành chủ nghĩa đế quốc ở các nước Âu – Mỹ (cuối thế kỉ XIX – đầu thế kỉ XX)","req":["Nêu được những nét chính về quá trình hình thành chủ nghĩa đế quốc; những chuyển biến lớn về kinh tế, chính sách đối nội, đối ngoại của các nước Anh, Pháp, Đức, Mỹ."],"sum":["Cuối thế kỉ XIX – đầu thế kỉ XX, các nước tư bản phát triển nhanh nhờ tiến bộ khoa học – kĩ thuật; sản xuất tập trung cao, hình thành các công ty độc quyền (các-ten, xanh-đi-ca, tơ-rớt).","Khái niệm: Cuối thế kỉ XIX – đầu thế kỉ XX, các nước tư bản phát triển nhanh nhờ tiến bộ khoa học – kĩ thuật; sản xuất tập trung cao, hình thành các công ty…","Từ khoá cần ghi nhớ: Chủ nghĩa đế quốc;","Mốc sự kiện cần nhớ: Cuối thế kỉ XIX – đầu thế kỉ XX: chủ nghĩa tư bản chuyển sang giai đoạn đế quốc","Anh: Mất vị trí công nghiệp số 1, nhưng có hệ thống thuộc địa lớn nhất (\"đế quốc mặt trời không bao giờ lặn\").","Đức: Phát triển công nghiệp nhanh, vươn lên đứng đầu châu Âu, ráo riết đòi chia lại thuộc địa (\"chủ nghĩa đế quốc quân phiệt, hiếu chiến\")."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 11. Phong trào công nhân từ cuối thế kỉ XVIII đến đầu thế kỉ XX và sự ra đời của chủ nghĩa xã hội khoa học","req":["Nêu được sự ra đời của giai cấp công nhân; một số hoạt động chính của phong trào công nhân; sự ra đời của chủ nghĩa xã hội khoa học; Công xã Pa-ri."],"sum":["Giai cấp công nhân ra đời cùng với Cách mạng công nghiệp. Ban đầu công nhân đập phá máy móc, đốt công xưởng; sau đó đình công, thành lập công đoàn.","Giai cấp công nhân ra đời cùng với Cách mạng công nghiệp: Ban đầu công nhân đập phá máy móc, đốt công xưởng; sau đó đình công, thành lập công đoàn.","Từ khoá cần ghi nhớ: Giai cấp công nhân;","Mốc sự kiện cần nhớ: 1848: Tuyên ngôn của Đảng Cộng sản;","Năm 1848, C: Mác và Ph.","Công xã Pa-ri (18/3 – 28/5/1871) là…: Công xã Pa-ri (18/3 – 28/5/1871) là nhà nước kiểu mới đầu tiên của giai cấp vô sản; tồn tại 72 ngày."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 12. Chiến tranh thế giới thứ nhất (1914 – 1918) và Cách mạng tháng Mười Nga năm 1917","req":["Trình bày được nguyên nhân, hậu quả của Chiến tranh thế giới thứ nhất; nguyên nhân, ý nghĩa của Cách mạng tháng Mười Nga."],"sum":["Nguyên nhân sâu xa: mâu thuẫn giữa các nước đế quốc về thuộc địa; hình thành hai khối quân sự đối lập: khối Liên minh (Đức, Áo – Hung, I-ta-li-a, 1882) và khối Hiệp ước (Anh, Pháp, Nga, 1907).","Nguyên nhân sâu xa: Mâu thuẫn giữa các nước đế quốc về thuộc địa; hình thành hai khối quân sự đối lập: khối Liên minh (Đức, Áo – Hung, I-ta-li-a, 1882) và khối Hiệp ước…","Từ khoá cần ghi nhớ: Chiến tranh thế giới thứ nhất; khối Liên minh; khối Hiệp ước; hậu quả;","Mốc sự kiện cần nhớ: 28/6/1914: thái tử Áo – Hung bị ám sát ở Xéc-bi;","Chiến tranh kết thúc năm 1918 với thất bại của phe Liên minh: Hậu quả: khoảng 10 triệu người chết, hơn 20 triệu người bị thương, thiệt hại vật chất khổng lồ.","Cách mạng tháng Mười Nga (7/11/1917 theo lịch mới): Dưới sự lãnh đạo của Đảng Bôn-sê-vích do Lê-nin đứng đầu, công nhân, binh lính khởi nghĩa ở Pê-tơ-rô-grát, lật đổ Chính phủ tư sản lâm thời, thành…"],"e":["Hay nhầm: Chiến tranh thế giới thứ hai.","Hay nhầm: Không phải lãnh tụ chính."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 5. Sự phát triển của khoa học, kĩ thuật, văn học, nghệ thuật trong các thế kỉ XVIII – XIX","l":[{"t":"Bài 13. Sự phát triển của khoa học, kĩ thuật, văn học, nghệ thuật trong các thế kỉ XVIII – XIX","req":["Mô tả được sự phát triển của khoa học, kĩ thuật, văn học, nghệ thuật trong các thế kỉ XVIII – XIX; tác động đối với xã hội."],"sum":["Khoa học tự nhiên: Niu-tơn (định luật vạn vật hấp dẫn), Lô-mô-nô-xốp (định luật bảo toàn vật chất), Đác-uyn (thuyết tiến hoá), Men-đê-lê-ép (bảng tuần hoàn), Pa-xtơ (vaccine).","Khoa học tự nhiên: Niu-tơn (định luật vạn vật hấp dẫn), Lô-mô-nô-xốp (định luật bảo toàn vật chất), Đác-uyn (thuyết tiến hoá), Men-đê-lê-ép (bảng tuần hoàn), Pa-xtơ…","Từ khoá cần ghi nhớ: Khoa học tự nhiên;","Mốc sự kiện cần nhớ: Điện báo (1837);","Kĩ thuật: Máy hơi nước, đầu máy xe lửa, tàu thuỷ, điện báo (Moóc-xơ, 1837), điện thoại (Graham Bell, 1876), bóng đèn (Ê-đi-xơn, 1879), ô tô, máy bay (anh em…","Khoa học xã hội: Chủ nghĩa duy vật, chủ nghĩa xã hội khoa học; kinh tế chính trị học (A-đam Xmít)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 6. Châu Á từ nửa sau thế kỉ XIX đến đầu thế kỉ XX","l":[{"t":"Bài 14. Trung Quốc và Nhật Bản từ nửa sau thế kỉ XIX đến đầu thế kỉ XX","req":["Trình bày được quá trình xâm lược Trung Quốc của các nước đế quốc; Cách mạng Tân Hợi; cuộc Duy tân Minh Trị và sự hình thành chủ nghĩa đế quốc ở Nhật Bản."],"sum":["Từ sau Chiến tranh thuốc phiện (1840–1842), Trung Quốc bị các nước đế quốc xâu xé, trở thành nước nửa thuộc địa, nửa phong kiến.","Khái niệm: Từ sau Chiến tranh thuốc phiện (1840–1842), Trung Quốc bị các nước đế quốc xâu xé, trở thành nước nửa thuộc địa, nửa phong kiến.","Từ khoá cần ghi nhớ: Chiến tranh thuốc phiện; nửa thuộc địa;","Mốc sự kiện cần nhớ: 1840–1842: Chiến tranh thuốc phiện;","Cách mạng Tân Hợi (1911) do Tôn…: Cách mạng Tân Hợi (1911) do Tôn Trung Sơn lãnh đạo (Trung Quốc Đồng minh hội, học thuyết Tam dân: dân tộc độc lập, dân quyền tự do, dân sinh hạnh…","Năm 1868, Thiên hoàng Minh Trị tiến…: Năm 1868, Thiên hoàng Minh Trị tiến hành cải cách toàn diện (chính trị, kinh tế, quân sự, giáo dục), đưa Nhật Bản thoát khỏi nguy cơ trở thành thuộc…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 15. Ấn Độ và Đông Nam Á từ nửa sau thế kỉ XIX đến đầu thế kỉ XX","req":["Nêu được những nét chính về tình hình chính trị, kinh tế, xã hội Ấn Độ; phong trào đấu tranh chống thực dân ở Đông Nam Á."],"sum":["Giữa thế kỉ XIX, Ấn Độ trở thành thuộc địa của Anh. Thực dân Anh bóc lột nặng nề, chia để trị.","Giữa thế kỉ XIX, Ấn Độ trở thành thuộc địa của Anh: Thực dân Anh bóc lột nặng nề, chia để trị.","Từ khoá cần ghi nhớ: Thuộc địa Anh; chia để trị;","Mốc sự kiện cần nhớ: Giữa thế kỉ XIX: Ấn Độ thành thuộc địa của Anh;","Cuối thế kỉ XIX, hầu hết các…: Cuối thế kỉ XIX, hầu hết các nước Đông Nam Á (trừ Xiêm) trở thành thuộc địa: In-đô-nê-xi-a (Hà Lan), Phi-líp-pin (Tây Ban Nha, sau đó Mỹ), Miến…","Phong trào đấu tranh: In-đô-nê-xi-a, Phi-líp-pin (Cách mạng 1896–1898, thành lập Cộng hoà Phi-líp-pin), Việt Nam, Lào, Cam-pu-chia…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 7. Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX","l":[{"t":"Bài 16. Việt Nam dưới thời Nguyễn (nửa đầu thế kỉ XIX)","req":["Nêu được những nét chính về tình hình chính trị, kinh tế, xã hội, văn hoá dưới thời Nguyễn; quá trình thực thi chủ quyền đối với quần đảo Hoàng Sa và Trường Sa."],"sum":["Năm 1802, Nguyễn Ánh lên ngôi hoàng đế (Gia Long), lập ra nhà Nguyễn, đóng đô ở Phú Xuân (Huế).","Khái niệm: Năm 1802, Nguyễn Ánh lên ngôi hoàng đế (Gia Long), lập ra nhà Nguyễn, đóng đô ở Phú Xuân (Huế).","Từ khoá cần ghi nhớ: Gia Long; nhà Nguyễn;","Mốc sự kiện cần nhớ: 1802: Gia Long lên ngôi;","Chính trị: Xây dựng nhà nước quân chủ trung ương tập quyền; vua Minh Mạng cải cách hành chính (1831–1832), chia cả nước thành 30 tỉnh và phủ Thừa Thiên.","Kinh tế: Khuyến khích khẩn hoang, lập ấp, đồn điền; thủ công nghiệp có bước phát triển; thực hiện chính sách \"bế quan toả cảng\" hạn chế buôn bán với phương…"],"e":["Hay nhầm: Việt Nam Dân chủ Cộng hoà."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 17. Cuộc kháng chiến chống thực dân Pháp xâm lược từ năm 1858 đến năm 1884","req":["Trình bày được quá trình thực dân Pháp xâm lược Việt Nam và cuộc kháng chiến của nhân dân ta; nêu được nguyên nhân dẫn đến việc mất nước."],"sum":["Ngày 1/9/1858, liên quân Pháp – Tây Ban Nha nổ súng tấn công Đà Nẵng, mở đầu cuộc xâm lược Việt Nam.","Khái niệm: Ngày 1/9/1858, liên quân Pháp – Tây Ban Nha nổ súng tấn công Đà Nẵng, mở đầu cuộc xâm lược Việt Nam.","Từ khoá cần ghi nhớ: Đà Nẵng;","Mốc sự kiện cần nhớ: 1/9/1858: Pháp nổ súng tấn công Đà Nẵng;","Nhân dân kháng chiến anh dũng: Nguyễn Trung Trực đốt tàu Hy Vọng (1861);","Pháp đánh Bắc Kì lần thứ nhất (1873) và lần thứ hai (1882): Tổng đốc Hoàng Diệu tử tiết khi thành Hà Nội thất thủ (1882)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 18. Phong trào chống Pháp trong những năm 1885 – 1896","req":["Trình bày được một số cuộc khởi nghĩa tiêu biểu trong phong trào Cần vương và khởi nghĩa Yên Thế."],"sum":["Ngày 13/7/1885, nhân danh vua Hàm Nghi, Tôn Thất Thuyết ra chiếu Cần vương, kêu gọi văn thân, sĩ phu và nhân dân đứng lên giúp vua cứu nước.","Khái niệm: Ngày 13/7/1885, nhân danh vua Hàm Nghi, Tôn Thất Thuyết ra chiếu Cần vương, kêu gọi văn thân, sĩ phu và nhân dân đứng lên giúp vua cứu nước.","Từ khoá cần ghi nhớ: Cần vương;","Mốc sự kiện cần nhớ: 13/7/1885: chiếu Cần vương; phong trào kéo dài đến năm 1896","Các cuộc khởi nghĩa tiêu biểu: Ba Đình (Thanh Hoá, 1886–1887) do Phạm Bành, Đinh Công Tráng lãnh đạo;","Khởi nghĩa Yên Thế (Bắc Giang, 1884–1913)…: Khởi nghĩa Yên Thế (Bắc Giang, 1884–1913) do Hoàng Hoa Thám lãnh đạo, là cuộc khởi nghĩa nông dân tự phát, kéo dài nhất."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 19. Phong trào yêu nước chống Pháp ở Việt Nam từ đầu thế kỉ XX đến năm 1917","req":["Nêu được tác động của cuộc khai thác thuộc địa lần thứ nhất; hoạt động yêu nước của Phan Bội Châu, Phan Châu Trinh; hành trình đi tìm đường cứu nước của Nguyễn Tất Thành."],"sum":["Cuộc khai thác thuộc địa lần thứ nhất của Pháp (1897–1914) làm xã hội Việt Nam chuyển biến: xuất hiện tầng lớp mới (tư sản, tiểu tư sản) và giai cấp công nhân;","Khái niệm: Cuộc khai thác thuộc địa lần thứ nhất của Pháp (1897–1914) làm xã hội Việt Nam chuyển biến: xuất hiện tầng lớp mới (tư sản, tiểu tư sản) và giai cấp…","Từ khoá cần ghi nhớ: Khai thác thuộc địa lần thứ nhất;","Mốc sự kiện cần nhớ: 1897–1914: khai thác thuộc địa lần thứ nhất;","Phan Bội Châu chủ trương dùng bạo lực giành độc lập: Lập Hội Duy tân (1904), tổ chức phong trào Đông du (1905–1908) đưa thanh niên sang Nhật học; năm 1912 lập Việt Nam Quang phục hội.","Phan Châu Trinh chủ trương cải cách: Cuộc vận động Duy tân ở Trung Kì (1906) với mục tiêu \"khai dân trí, chấn dân khí, hậu dân sinh\"; phong trào chống thuế ở Trung Kì (1908)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề chung. Văn minh châu thổ sông Hồng và sông Cửu Long","l":[{"t":"Chủ đề chung. Văn minh châu thổ sông Hồng và sông Cửu Long","req":["Trình bày được quá trình hình thành, phát triển của châu thổ sông Hồng và sông Cửu Long; những nét chính của nền văn minh châu thổ."],"sum":["Châu thổ sông Hồng do phù sa sông Hồng, sông Thái Bình bồi đắp, diện tích khoảng 15 000 km²; là nơi hình thành nền văn minh sông Hồng với nhà nước Văn Lang – Âu Lạc.","Khái niệm: Châu thổ sông Hồng do phù sa sông Hồng, sông Thái Bình bồi đắp, diện tích khoảng 15 000 km²; là nơi hình thành nền văn minh sông Hồng với nhà nước…","Từ khoá cần ghi nhớ: Châu thổ sông Hồng; châu thổ sông Cửu Long; văn minh châu thổ; lưu dân; trồng lúa nước.","Mốc sự kiện cần nhớ: Châu thổ sông Hồng khoảng 15 000 km²; châu thổ sông Cửu Long khoảng 40 000 km²","Châu thổ sông Cửu Long do phù…: Châu thổ sông Cửu Long do phù sa sông Mê Công bồi đắp, diện tích khoảng 40 000 km²; gắn với văn hoá Óc Eo, vương quốc Phù Nam và công cuộc khai phá…","Văn minh châu thổ gắn với nghề…: Văn minh châu thổ gắn với nghề trồng lúa nước, hệ thống đê điều (sông Hồng), kênh rạch (sông Cửu Long); làng xã; tín ngưỡng thờ cúng tổ tiên, thờ…"],"q":{"n":6,"lv":{"Biết":2,"Hiểu":2,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương 1. Châu Âu và Bắc Mỹ từ nửa sau thế kỉ XVI đến thế kỉ XVIII","l":[{"t":"Bài tập nâng cao · Chương 1. Châu Âu và Bắc Mỹ từ nửa sau thế kỉ XVI đến thế kỉ XVIII (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 2. Đông Nam Á từ nửa sau thế kỉ XVI đến giữa thế kỉ XIX","l":[{"t":"Bài tập nâng cao · Chương 2. Đông Nam Á từ nửa sau thế kỉ XVI đến giữa thế kỉ XIX (2 câu)","q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chương 3. Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII","l":[{"t":"Bài tập nâng cao · Chương 3. Việt Nam từ đầu thế kỉ XVI đến thế kỉ XVIII (10 câu)","q":{"n":10,"lv":{"Nâng cao":10}}}]},{"t":"Chương 4. Châu Âu và nước Mỹ từ cuối thế kỉ XVIII đến đầu thế kỉ XX","l":[{"t":"Bài tập nâng cao · Chương 4. Châu Âu và nước Mỹ từ cuối thế kỉ XVIII đến đầu thế kỉ XX (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 5. Sự phát triển của khoa học, kĩ thuật, văn học, nghệ thuật trong các thế kỉ XVIII – XIX","l":[{"t":"Bài tập nâng cao · Chương 5. Sự phát triển của khoa học, kĩ thuật, văn học, nghệ thuật trong các thế kỉ XVIII – XIX (2…","q":{"n":2,"lv":{"Nâng cao":2}}}]},{"t":"Chương 6. Châu Á từ nửa sau thế kỉ XIX đến đầu thế kỉ XX","l":[{"t":"Bài tập nâng cao · Chương 6. Châu Á từ nửa sau thế kỉ XIX đến đầu thế kỉ XX (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương 7. Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX","l":[{"t":"Bài tập nâng cao · Chương 7. Việt Nam từ thế kỉ XIX đến đầu thế kỉ XX (8 câu)","q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chủ đề chung. Văn minh châu thổ sông Hồng và sông Cửu Long","l":[{"t":"Bài tập nâng cao · Chủ đề chung. Văn minh châu thổ sông Hồng và sông Cửu Long (2 câu)","q":{"n":2,"lv":{"Nâng cao":2}}}]}]}]},{"id":"diali","name":"Địa lí","b":[{"t":"Địa lí 8","c":[{"t":"Chương 1. Đặc điểm vị trí địa lí, phạm vi lãnh thổ, địa hình và khoáng sản Việt Nam","l":[{"t":"Bài 1. Vị trí địa lí và phạm vi lãnh thổ Việt Nam","req":["Trình bày được đặc điểm vị trí địa lí, phạm vi lãnh thổ Việt Nam; phân tích ảnh hưởng của vị trí địa lí đến đặc điểm tự nhiên."],"sum":["Việt Nam nằm ở rìa phía đông bán đảo Đông Dương, gần trung tâm khu vực Đông Nam Á; trong vùng nội chí tuyến bán cầu Bắc; tiếp giáp Trung Quốc, Lào, Cam-pu-chia và Biển Đông.","Khái niệm: Việt Nam nằm ở rìa phía đông bán đảo Đông Dương, gần trung tâm khu vực Đông Nam Á; trong vùng nội chí tuyến bán cầu Bắc; tiếp giáp Trung Quốc, Lào,…","Từ khoá cần ghi nhớ: Vị trí; nội chí tuyến; phạm vi lãnh thổ; cực Bắc, Nam, Tây, Đông; biên giới;","Điểm nhấn ghi nhớ: Bốn điểm cực: Bắc (Lũng Cú), Nam (Đất Mũi), Tây (Sín Thầu), Đông (Vạn Thạnh)","Hệ toạ độ phần đất liền: Cực Bắc 23°23′B (Lũng Cú, Hà Giang), cực Nam 8°34′B (Đất Mũi, Cà Mau), cực Tây 102°09′Đ (Sín Thầu, Điện Biên), cực Đông 109°28′Đ (Vạn Thạnh, Khánh…","Phạm vi lãnh thổ gồm vùng đất…: Phạm vi lãnh thổ gồm vùng đất (diện tích khoảng 331 000 km², đường biên giới đất liền khoảng 4 600 km, đường bờ biển dài 3 260 km), vùng biển…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 2. Địa hình Việt Nam","req":["Trình bày được đặc điểm chủ yếu của địa hình Việt Nam; đặc điểm các khu vực địa hình; ảnh hưởng của địa hình đối với sự phân hoá tự nhiên và khai thác kinh tế."],"sum":["Đồi núi chiếm 3/4 diện tích lãnh thổ, chủ yếu là đồi núi thấp (địa hình dưới 1 000 m chiếm khoảng 85%, núi cao trên 2 000 m chỉ khoảng 1%).","Khái niệm: Đồi núi chiếm 3/4 diện tích lãnh thổ, chủ yếu là đồi núi thấp (địa hình dưới 1 000 m chiếm khoảng 85%, núi cao trên 2 000 m chỉ khoảng 1%).","Từ khoá cần ghi nhớ: Đồi núi;","Điểm nhấn ghi nhớ: Đồi núi chiếm 3/4 diện tích; núi cao trên 2 000 m chỉ khoảng 1%","Địa hình được nâng lên trong giai…: Địa hình được nâng lên trong giai đoạn Tân kiến tạo, phân thành nhiều bậc; hướng chính là tây bắc – đông nam và vòng cung.","Các khu vực: Đông Bắc (vòng cung), Tây Bắc (cao nhất, hướng tây bắc – đông nam, có Phan-xi-păng 3 143 m), Trường Sơn Bắc, Trường Sơn Nam (cao nguyên ba-dan);"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 3. Khoáng sản Việt Nam","req":["Trình bày được đặc điểm chung của tài nguyên khoáng sản Việt Nam; sự phân bố các loại khoáng sản chủ yếu; vấn đề sử dụng hợp lí."],"sum":["Việt Nam có nguồn khoáng sản phong phú, đa dạng (khoảng 60 loại khoáng sản khác nhau, hơn 5 000 điểm mỏ), phần lớn có trữ lượng vừa và nhỏ; một số có trữ lượng lớn: than, dầu khí, bô-xít, sắt, đá…","Khái niệm: Việt Nam có nguồn khoáng sản phong phú, đa dạng (khoảng 60 loại khoáng sản khác nhau, hơn 5 000 điểm mỏ), phần lớn có trữ lượng vừa và nhỏ; một số…","Từ khoá cần ghi nhớ: Khoáng sản; than; dầu khí; bô-xít; a-pa-tít; titan; sử dụng hợp lí.","Điểm nhấn ghi nhớ: Khoảng 60 loại khoáng sản, hơn 5 000 điểm mỏ; than đá tập trung ở Quảng Ninh","Phân bố: Than đá (Quảng Ninh), dầu mỏ, khí tự nhiên (thềm lục địa phía nam – bể Cửu Long, Nam Côn Sơn), bô-xít (Tây Nguyên), sắt (Thái Nguyên, Hà Tĩnh),…","Sử dụng hợp lí: Khai thác tiết kiệm, hiệu quả, áp dụng công nghệ hiện đại; bảo vệ môi trường; thực hiện nghiêm Luật Khoáng sản."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 2. Đặc điểm khí hậu và thuỷ văn Việt Nam","l":[{"t":"Bài 4. Khí hậu Việt Nam","req":["Trình bày được đặc điểm khí hậu nhiệt đới ẩm gió mùa của Việt Nam; sự phân hoá đa dạng của khí hậu."],"sum":["Tính chất nhiệt đới: tổng lượng bức xạ lớn, nhiệt độ trung bình năm trên 20 °C (trừ vùng núi cao), số giờ nắng 1 400–3 000 giờ/năm.","Tính chất nhiệt đới: Tổng lượng bức xạ lớn, nhiệt độ trung bình năm trên 20 °C (trừ vùng núi cao), số giờ nắng 1 400–3 000 giờ/năm.","Từ khoá cần ghi nhớ: Nhiệt đới; gió mùa Đông Bắc; gió mùa Tây Nam; dãy Bạch Mã;","Điểm nhấn ghi nhớ: Gió mùa Đông Bắc từ tháng 11 đến tháng 4; gió mùa Tây Nam từ tháng 5 đến tháng 10","Tính chất ẩm: Lượng mưa trung bình năm 1 500–2 000 mm (nơi đón gió có thể 3 500–4 000 mm), độ ẩm không khí trên 80%.","Tính chất gió mùa: Mùa đông có gió mùa Đông Bắc (tháng 11–4) làm miền Bắc lạnh, mùa hạ có gió mùa Tây Nam (tháng 5–10) gây mưa lớn cho cả nước."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 6. Thuỷ văn Việt Nam","req":["Trình bày được đặc điểm mạng lưới và chế độ nước sông; xác định các hệ thống sông lớn; vai trò của hồ, đầm và nước ngầm."],"sum":["Mạng lưới sông dày đặc: có 2 360 con sông dài trên 10 km, trong đó 93% là sông nhỏ, ngắn. Hai hướng chính: tây bắc – đông nam và vòng cung.","Mạng lưới sông dày đặc: Có 2 360 con sông dài trên 10 km, trong đó 93% là sông nhỏ, ngắn.","Từ khoá cần ghi nhớ: Sông ngòi; chế độ nước; mùa lũ; phù sa; sông Hồng; sông Mê Công; hồ, đầm.","Điểm nhấn ghi nhớ: Mùa lũ chiếm 70–80% lượng nước cả năm; sông mang khoảng 200 triệu tấn phù sa mỗi năm","Chế độ nước theo mùa: Mùa lũ trùng với mùa mưa, mùa cạn trùng với mùa khô; lượng nước mùa lũ chiếm 70–80% lượng nước cả năm.","Các hệ thống sông lớn: Sông Hồng, sông Thái Bình, sông Mã, sông Cả, sông Thu Bồn, sông Đà Rằng (Ba), sông Đồng Nai, sông Mê Công (Cửu Long)…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 7. Vai trò của tài nguyên khí hậu và tài nguyên nước đối với sự phát triển kinh tế – xã hội của nước ta","req":["Phân tích được vai trò của khí hậu và tài nguyên nước đối với sự phát triển nông nghiệp, du lịch, công nghiệp; vấn đề sử dụng hợp lí tài nguyên nước."],"sum":["Khí hậu nhiệt đới ẩm gió mùa thuận lợi cho nông nghiệp nhiệt đới, thâm canh, tăng vụ, đa dạng cây trồng; khí hậu phân hoá tạo điều kiện phát triển cây ôn đới, cận nhiệt ở vùng núi.","Khái niệm: Khí hậu nhiệt đới ẩm gió mùa thuận lợi cho nông nghiệp nhiệt đới, thâm canh, tăng vụ, đa dạng cây trồng; khí hậu phân hoá tạo điều kiện phát triển…","Từ khoá cần ghi nhớ: Tài nguyên khí hậu; tài nguyên nước; nông nghiệp nhiệt đới; thuỷ điện; du lịch; thiên tai.","Điểm nhấn ghi nhớ: Khí hậu nhiệt đới ẩm gió mùa thuận lợi cho tăng vụ; thiên tai gồm bão, lũ, hạn hán, rét đậm","Khí hậu tạo điều kiện phát triển…: Khí hậu tạo điều kiện phát triển du lịch quanh năm (biển ở phía nam), du lịch nghỉ dưỡng vùng núi (Sa Pa, Đà Lạt).","Tài nguyên nước phục vụ nông nghiệp…: Tài nguyên nước phục vụ nông nghiệp (tưới tiêu, thuỷ sản), công nghiệp (thuỷ điện), giao thông đường thuỷ, du lịch, sinh hoạt."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 8. Tác động của biến đổi khí hậu đối với khí hậu và thuỷ văn Việt Nam","req":["Phân tích được tác động của biến đổi khí hậu đối với khí hậu và thuỷ văn Việt Nam; tìm ví dụ về giải pháp ứng phó."],"sum":["Biểu hiện của biến đổi khí hậu ở Việt Nam: nhiệt độ trung bình năm tăng (khoảng 0,89 °C giai đoạn 1958–2018); lượng mưa thay đổi, mưa lớn bất thường; thiên tai cực đoan (bão mạnh, rét đậm, nắng…","Biểu hiện của biến đổi khí hậu ở Việt Nam: Nhiệt độ trung bình năm tăng (khoảng 0,89 °C giai đoạn 1958–2018); lượng mưa thay đổi, mưa lớn bất thường; thiên tai cực đoan (bão mạnh, rét đậm,…","Từ khoá cần ghi nhớ: Biến đổi khí hậu; nhiệt độ tăng; mực nước biển dâng; lũ quét; xâm nhập mặn; giảm nhẹ; thích ứng.","Điểm nhấn ghi nhớ: Nhiệt độ trung bình năm tăng khoảng 0,89 °C trong giai đoạn 1958–2018","Tác động đến thuỷ văn: Lũ lụt tăng về cường độ, lũ quét ở miền núi; mùa cạn kéo dài, thiếu nước; xâm nhập mặn ở đồng bằng sông Cửu Long ngày càng sâu.","Giải pháp: Giảm nhẹ (tiết kiệm năng lượng, phát triển năng lượng tái tạo, trồng rừng) và thích ứng (xây dựng công trình phòng chống thiên tai, chuyển đổi cơ…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 3. Đặc điểm thổ nhưỡng và sinh vật Việt Nam","l":[{"t":"Bài 9. Thổ nhưỡng Việt Nam","req":["Chứng minh được tính chất nhiệt đới gió mùa của lớp phủ thổ nhưỡng; trình bày đặc điểm và sự phân bố các nhóm đất chính; vấn đề thoái hoá đất."],"sum":["Lớp phủ thổ nhưỡng mang tính chất nhiệt đới gió mùa: quá trình feralit diễn ra mạnh, tạo đất có màu đỏ vàng, lớp vỏ phong hoá dày;","Lớp phủ thổ nhưỡng mang tính chất nhiệt đới gió mùa: Quá trình feralit diễn ra mạnh, tạo đất có màu đỏ vàng, lớp vỏ phong hoá dày;","Từ khoá cần ghi nhớ: Thổ nhưỡng; feralit;","Điểm nhấn ghi nhớ: Đất feralit khoảng 65% diện tích;","Ba nhóm đất chính: Đất feralit (khoảng 65% diện tích, ở vùng đồi núi thấp, chua, nghèo mùn;","Thoái hoá đất (xói mòn, bạc màu…: Thoái hoá đất (xói mòn, bạc màu, nhiễm mặn, nhiễm phèn, hoang mạc hoá) do tự nhiên và con người."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 10. Sinh vật Việt Nam","req":["Chứng minh được sự đa dạng của sinh vật Việt Nam; vấn đề bảo tồn đa dạng sinh học."],"sum":["Sinh vật Việt Nam đa dạng về thành phần loài (khoảng hơn 50 000 loài sinh vật đã được xác định), về gen, về hệ sinh thái.","Khái niệm: Sinh vật Việt Nam đa dạng về thành phần loài (khoảng hơn 50 000 loài sinh vật đã được xác định), về gen, về hệ sinh thái.","Từ khoá cần ghi nhớ: Đa dạng sinh học; hệ sinh thái; rừng ngập mặn; rạn san hô;","Điểm nhấn ghi nhớ: Hơn 50 000 loài đã được xác định; nhiều loài bị đe doạ, được ghi trong Sách Đỏ Việt Nam","Các hệ sinh thái: Tự nhiên trên cạn (rừng kín thường xanh, rừng nhiệt đới gió mùa, rừng trên núi đá vôi…), dưới nước (rừng ngập mặn, rạn san hô, đầm lầy…); hệ sinh…","Đa dạng sinh học đang bị suy giảm: Diện tích rừng tự nhiên giảm, nhiều loài bị đe doạ tuyệt chủng (trong Sách Đỏ Việt Nam)."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chương 4. Biển đảo Việt Nam","l":[{"t":"Bài 11. Phạm vi Biển Đông. Vùng biển đảo và đặc điểm tự nhiên vùng biển đảo Việt Nam","req":["Xác định được phạm vi Biển Đông; các vùng biển của Việt Nam theo Luật Biển; đặc điểm tự nhiên vùng biển đảo."],"sum":["Biển Đông là biển nửa kín, rộng khoảng 3,44 triệu km², trải dài từ khoảng vĩ độ 3°N đến 26°B, được bao bọc bởi 9 quốc gia và vùng lãnh thổ.","Khái niệm: Biển Đông là biển nửa kín, rộng khoảng 3,44 triệu km², trải dài từ khoảng vĩ độ 3°N đến 26°B, được bao bọc bởi 9 quốc gia và vùng lãnh thổ.","Từ khoá cần ghi nhớ: Biển Đông; biển nửa kín; nội thuỷ; lãnh hải; vùng tiếp giáp lãnh hải;","Điểm nhấn ghi nhớ: Biển Đông rộng khoảng 3,44 triệu km², được bao bọc bởi 9 quốc gia và vùng lãnh thổ; vùng đặc quyền kinh tế rộng 200 hải lí","Theo Luật Biển Việt Nam năm 2012…: Theo Luật Biển Việt Nam năm 2012 và Công ước của Liên hợp quốc về Luật Biển năm 1982, vùng biển Việt Nam gồm: nội thuỷ, lãnh hải (rộng 12 hải lí…","Nước ta có hàng nghìn đảo lớn nhỏ: Phú Quốc (lớn nhất), Cát Bà, Côn Đảo, Lý Sơn… và hai quần đảo xa bờ: quần đảo Hoàng Sa (thuộc thành phố Đà Nẵng) và quần đảo Trường Sa (thuộc tỉnh…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}},{"t":"Bài 12. Môi trường và tài nguyên biển đảo Việt Nam","req":["Nêu được đặc điểm môi trường biển đảo và vấn đề bảo vệ môi trường biển; các tài nguyên biển đảo và vấn đề khai thác."],"sum":["Môi trường biển đảo nước ta còn khá trong lành, nhưng ở một số nơi bị ô nhiễm do chất thải sinh hoạt, công nghiệp, khai thác dầu khí, rác thải nhựa; suy giảm hệ sinh thái rạn san hô, rừng ngập mặn.","Khái niệm: Môi trường biển đảo nước ta còn khá trong lành, nhưng ở một số nơi bị ô nhiễm do chất thải sinh hoạt, công nghiệp, khai thác dầu khí, rác thải nhựa;…","Từ khoá cần ghi nhớ: Ô nhiễm biển; rạn san hô; rừng ngập mặn; sinh vật biển; khoáng sản biển; du lịch biển; năng lượng gió.","Điểm nhấn ghi nhớ: Hơn 2 000 loài cá; các bãi biển tiêu biểu: Hạ Long, Nha Trang, Phú Quốc","Tài nguyên biển: Sinh vật biển (hơn 2 000 loài cá, nhiều tôm, mực, hải sâm, rong biển…); khoáng sản (dầu mỏ, khí tự nhiên, titan, cát thuỷ tinh, muối); du lịch…","Cần khai thác hợp lí, gắn với…: Cần khai thác hợp lí, gắn với bảo vệ môi trường biển, bảo vệ chủ quyền biển đảo; phát triển kinh tế biển bền vững."],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]},{"t":"Chủ đề chung. Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","l":[{"t":"Chủ đề chung. Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","req":["Trình bày được quá trình xác lập và thực thi chủ quyền của Việt Nam đối với Biển Đông và hai quần đảo Hoàng Sa, Trường Sa; nêu được vai trò của biển đảo."],"sum":["Biển Đông có vị trí chiến lược quan trọng: nằm trên tuyến đường hàng hải quốc tế nối Thái Bình Dương và Ấn Độ Dương; giàu tài nguyên; có ý nghĩa quốc phòng, an ninh.","Biển Đông có vị trí chiến lược quan trọng: Nằm trên tuyến đường hàng hải quốc tế nối Thái Bình Dương và Ấn Độ Dương; giàu tài nguyên; có ý nghĩa quốc phòng, an ninh.","Từ khoá cần ghi nhớ: Chủ quyền;","Điểm nhấn ghi nhớ: Việt Nam xác lập chủ quyền hoà bình, liên tục; từ thế kỉ XVII các chúa Nguyễn lập đội Hoàng Sa","Việt Nam là nhà nước đầu tiên…: Việt Nam là nhà nước đầu tiên xác lập và thực thi chủ quyền đối với hai quần đảo Hoàng Sa và Trường Sa một cách hoà bình, liên tục: từ thế kỉ XVII…","Việt Nam đã ban hành Luật Biển…: Việt Nam đã ban hành Luật Biển Việt Nam (2012), là thành viên Công ước Liên hợp quốc về Luật Biển 1982; chủ trương giải quyết tranh chấp bằng biện…"],"q":{"n":7,"lv":{"Biết":2,"Hiểu":3,"Vận dụng":2}}}]}]},{"t":"Bài tập nâng cao","c":[{"t":"Chương 1. Đặc điểm vị trí địa lí, phạm vi lãnh thổ, địa hình và khoáng sản Việt Nam","l":[{"t":"Bài tập nâng cao · Chương 1. Đặc điểm vị trí địa lí, phạm vi lãnh thổ, địa hình và khoáng sản Việt Nam (6 câu)","q":{"n":6,"lv":{"Nâng cao":6}}}]},{"t":"Chương 2. Đặc điểm khí hậu và thuỷ văn Việt Nam","l":[{"t":"Bài tập nâng cao · Chương 2. Đặc điểm khí hậu và thuỷ văn Việt Nam (8 câu)","e":["Hay nhầm: Không phải nguyên nhân chính toàn miền."],"q":{"n":8,"lv":{"Nâng cao":8}}}]},{"t":"Chương 3. Đặc điểm thổ nhưỡng và sinh vật Việt Nam","l":[{"t":"Bài tập nâng cao · Chương 3. Đặc điểm thổ nhưỡng và sinh vật Việt Nam (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chương 4. Biển đảo Việt Nam","l":[{"t":"Bài tập nâng cao · Chương 4. Biển đảo Việt Nam (4 câu)","q":{"n":4,"lv":{"Nâng cao":4}}}]},{"t":"Chủ đề chung. Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông","l":[{"t":"Bài tập nâng cao · Chủ đề chung. Bảo vệ chủ quyền, các quyền và lợi ích hợp pháp của Việt Nam ở Biển Đông (2 câu)","q":{"n":2,"lv":{"Nâng cao":2}}}]}]}]}]};
